SELECT 'moj-all-verified-judgments-review-002-chunk-021' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a08720c7-d034-5d83-86c1-a48918911ba8","document_type":"judgment","category":"judicial","subcategory":"general","title":"زيارة -املطالبة بزيارة أب البنته -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب تقدير قسم اخلبراء.","document_number":"3413376","case_number":"49266","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"زيارة -املطالبة بزيارة أب البنته -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب تقدير قسم اخلبراء.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3413376 :‬‬\n                            ‫َر ْق ُم الدعوى‪49266 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34283175‬تاريخه‪1434/7/30:‬هـ‬\n\n\n      ‫زيــارة ‪ -‬املطالبــة بزيــارة أب البنتــه ‪ -‬حتديــد الزيــارة ووقتهــا عــن طريــق‬\n                       ‫قســم اخلبــراء ‪ -‬احلكــم مبوجــب تقديــر قســم اخلبــراء‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــال اهلل تعالــى‪( :‬وقضــى ربــك أال تعبــدوا إال إيــاه وبالوالديــن‬\n                                                                    ‫إحســان ًا )‪.‬‬\n                                     ‫‪ -2‬املادة ‪ 122‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n      ‫أقــام رجــل دعــوى علــى مطلقتــه يطالــب بتمكــن ابنتــه املولــودة يف‬\n      ‫‪1421/1/1‬ه ـ مــن زيارتــه واملبيــت عنــده ومنــع املدعــى عليهــا مــن منــع‬\n      ‫ابنتــه مــن االتصــال بــه يف أي وقــت‪ -‬وافقــت املدعــى عليهــا علــى طلــب‬\n      ‫املدعــي متكــن ابنتــه مــن زيارتــه علــى أن تكــون الزيــارة يف منزلهــا ألن‬\n      ‫ابنتهــا ترفــض بشــدة أن تذهــب إلــى بيــت والدهــا ملــا جتــده مــن اضطهــاد‬\n      ‫واعتــداءات متكــررة مــن قبــل زوجــة أبيهــا ووالدتــه ‪ -‬قــررت احملكمــة‬\n      ‫الكتابــة لقســم اخلبــراء لتحديــد مــدة الزيــارة ومكانهــا فــورد اجلــواب‬\n      ‫مــن قســم اخلبــراء أن تكــون الزيــارة يومــا مــن كل أســبوع وبعــرض ذلــك‬\n      ‫علــى الطرفــن رفضــا قــرار مكتــب الصلــح ‪ -‬حكمــت احملكمــة مبــا‬\n      ‫جــاء يف قــرار قســم اخلبــراء علــى أن يقــوم املدعــي بأخــذ ابنتــه لزيارتــه‬\n        ‫وإعادتهــا ملنــزل والدتهــا ‪ -‬اعترضــت املدعــى عليهــا ‪ -‬صــدق احلكــم‪.‬‬\n‫‪305‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي (‪ ).....‬يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامة‪/‬املســاعد وتاريــخ ‪1431/11/19‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n‫‪1431/11/19‬ه ـ واملعــادة مــن حفــظ احملكمــة لعــدم املراجعــة يف‬\n‫‪1431/4/14‬ه ـ ففــي يــوم الســبت املوافق‪1433/08/03‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية وادعــى علــى احلاضــر معــه‬\n‫(‪ ).....‬ســعودي اجلنســية مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بالريــاض برقــم (‪ ).....‬يف ‪1430/2/8‬ه ـ جلــد ‪ 17523‬والتــي‬\n‫تخولهــا لنيابــة عنهــا يف كل دعــوى تقــام منــه أو ضــده ولهــم يف ذلــك حــق‬\n‫املطالبــة واملرافعــة واملدافعــة وقبــول الصلــح والتنازل واإلقــرار واإلنكار‬\n‫وقبــول اليمــن وردهــا وقبــول األحــكام واالعتــراض عليهــا وطلــب‬\n‫ا يف دعــواه‪ :‬إن‬ ‫متييزهــا واســتالم وتســليم املســتندات والصكــوك‪ .‬قائـ ً‬\n‫املدعــى عليهــا كانــت زوجــة لــي وقــد طلقتهــا وقــد بانــت منــي منــذ ســبع‬\n‫ســنوات وقــد أجنبــت لــي علــى فــراش الزوجيــة بنتــا اســمها (‪ ).....‬املولــودة‬\n‫يف ‪1421/1/1‬ه ـ وقــد طلبــت منهــا عــدة مــرات زيــارة ابنتــي لــي فرفضت‬\n‫وقــد بذلــت وأرســلت مــن يســعى للصلــح دون اللجــوء للمحاكــم لكــن‬\n‫ذلــك لــم يــأت بفائــدة أطلــب احلكــم علــى املدعــى عليهــا والــدة ابنتــي بــأن‬\n‫تزورنــي ابنتــي كل يــوم مــن الســاعة الواحــدة ظهــر ًا وحتــى الســاعة‬\n‫الرابعــة عصــر ًا وأســبوعي ًا مــن عصــر يــوم األربعــاء إلــى عصــر يــوم اجلمعة‬\n‫وتبيــت عنــدي ليلــة األربعــاء وليلــة اخلميــس ونصــف اإلجــازة الصيفيــة ويف‬\n‫شــهر رمضــان مــن منتصفــه وحتــى ثالــث يــوم بعــد عيــد الفطــر تكــون‬\n\n                                                                                        ‫‪306‬‬\n\f      ‫عنــدي كمــا أطلــب عــدم منعهــا مــن أن تتصــل بــي أو أتصــل بهــا يف أي‬\n      ‫وقــت هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‪ :‬أطلــب‬\n      ‫مهلــة إلــى اجللســة القادمــة ويف جلســة أخــرى بتاريــخ ‪1433/09/19‬ه ـ‬\n      ‫حضــر وكيــل املدعــي وحضــر وكيــل املدعــى عليهــا ولــم حتضــر بنــت‬\n      ‫املدعــي (‪ ).....‬وبســؤال املدعــى عليــه وكالــة عــن جوابــه علــى دعــوى‬\n      ‫املدعــي وعــن ســبب عــدم حضــور بنــت املدعــي (‪ ).....‬أجــاب إنــه ســبق‬\n      ‫للمدعــي أصالــة التقــدم بدعــوى مماثلة وقيدت الدعــوى برقم‪3034131‬‬\n      ‫اطلــب ضــم أوراق هــذه القضيــة لســابقتها وأمــا بالنســبة إلــى املوضــوع‬\n      ‫أعــاه فإنــه يشــرفني أن أتقــدم لفضيلتكــم بالوكالــة عــن موكلتــي‬\n      ‫بردنــا علــى مــا جــاء يف دعــوى املدعــي وذلــك علــى النحــو التالــي‪ :‬أو ًال ‪:‬‬\n      ‫فيمــا يتعلــق مبــا ذكــره املدعــي أنــه كان زوج ـ ًا ملوكلتــي وقــد طلقهــا‬\n      ‫وقــد بانــت منــه منــذ ســبع ســنوات وأنهــا أجنبــت لــه علــى فــراش الزوجيــة‬\n      ‫البنــت (‪ ).....‬املولــودة بتاريــخ ‪1421/1/1‬ه ـ فــإن ذلــك صحيــح‪ .‬ثاني ًا ‪ :‬أما‬\n      ‫بخصــوص مــا ذكــره املدعــي مــن أنــه طلــب عــدة مــرات زيــارة ابنتــه لــه‬\n      ‫فرفضــت والدتهــا وأنــه أرســل مــن يســعى للصلــح دون اللجــوء للمحاكــم‬\n      ‫فــإن مــا ذكــره املدعــي غيــر صحيــح ‪ ،‬والصحيــح أن موكلتــي ال متانــع‬\n      ‫مــن زيــارة املدعــي البنتــه وهــي حريصــة كل احلــرص علــى أن ال تنقطــع‬\n      ‫صلــة ابنتهــا بوالدهــا ولكــن املدعــي ومــن بعد أن صدر حكم ســلفكم‬\n      ‫الشــيخ (‪ ).....‬بــرد دعــواه املتعلقــة بحضانــة ابنتــه قطــع صلتــه بابنتــه ولــم‬\n      ‫يعــد يزورهــا أو يتصــل كونهــا اختــارت البقــاء عنــد والدتهــا‪ .‬ثالثـاً‪ :‬لقــد‬\n      ‫ذكــر املدعــي أنــه قــد أرســل مــن يســعى للصلــح دون اللجــوء للقضــاء‬\n      ‫فــإن املدعــي قــد أرســل شــخص ًا مجهــول الهويــة يطلــب منهــا تســليم‬\n      ‫ابنتهــا لوالدهــا فطلبــت منــه موكلتــي التعريــف بنفســه وقامــت بإعطائه‬\n\n\n‫‪307‬‬\n\f‫رقــم هاتــف شــقيقها ولكنــه لــم يتواصــل معــه رابع ـ ًا ‪ :‬بخصــوص مــا‬\n‫طلبــه املدعــي مــن أن تــزوره ابنتــه يف منزلــه مــن الســاعة الواحــدة ظهــر ًا‬\n‫وحتــى الســاعة الرابعــة عصــر ًا طــوال أيــام األســبوع وتبيــت عنــده يــوم‬\n‫األربعــاء واخلميــس إلــى عصــر يــوم اجلمعــة باإلضافــة إلــى زيارتهــا لــه مــن‬\n‫منتصــف شــهر رمضــان وحتــى ثالــث أيــام عيــد الفطــر وعليــه فإننــا‬\n‫جنيــب علــى ذلــك بــأن موكلتــي ال متانــع مــن زيــارة املدعــي البنتــه يف‬\n‫منزلهــا كــون أن ابنتهــا ترفــض وبشــدة أن تذهــب إلــى بيــت والدهــا ملــا‬\n‫جتــده مــن اضطهــاد واعتــداءات متكــررة مــن قبــل زوجــة أبيهــا ووالدتــه‬\n‫وخوفهــا مــن حرمانهــا مــن العــودة لوالدتهــا بعــد انتهــاء فترة زيــارة والدها‬\n‫وقــد تعرضــت ابنــة موكلتــي العتــداء مــن قبــل والــدة املدعــي قامــت‬\n‫بضربهــا أمــام زميالتهــا يف املدرســة وحاولــت أخذهــا بالقــوة‪ ،‬وقــد مت‬\n‫إحالــة املوضــوع إلــى مركــز شــرطة العليــا والتــي بدورهــا أحالــت كامل‬\n‫ملــف التحقيــق إلــى ســلفكم الشــيخ بتاريــخ ‪1430/05/25‬ه ـ خامسـ ًا ‪:‬‬\n‫أمــا فيمــا يخــص طلــب فضيلتكــم إحضــار ابنــة موكلتــي جللســة هــذا‬\n‫اليــوم فــإن ابنــة موكلتــي قــد حضــرت إلــى مكتــب فضيلتكــم مرتــن‬\n‫قبــل املوعــد احملــدد لهــذه اجللســة وطلبــت مقابلتكــم ولــم تتمكــن مــن‬\n‫ذلــك‪ ،‬وقــد زاد رفضهــا للحضــور يف هــذه اجللســة لعلمهــا حضــور زوجــة‬\n‫املدعــي للجلســة املاضيــة أمــام فضيلتكــم وهــي ليســت طرف ـ ًا يف‬\n‫الدعــوى ‪ .‬صاحــب الفضيلــة يتضــح لفضيلتكــم مــن خــال مــا ســبق‬\n‫عــدم صحــة مــا ذكــره املدعــي يف دعــواه مــن منعــه مــن رؤيــة ابنتــه‬\n‫ولكــن هنالــك ظــروف حتتــم مراعــاة مصلحــة هــذه الطفلــة وعــدم‬\n‫الضغــط عليهــا خصوصـ ًا بعــد تعرضهــا العتداءات موضحــة يف محاضر‬\n‫رســمية وقــد أدت هــذه االعتــداءات إلخضاعهــا لعالج نفســي يف مراكز‬\n\n\n                                                                                       ‫‪308‬‬\n\f      ‫متخصصــة‪ ،‬وحيــث إن موكلتــي ال متانــع مــن زيــارة املدعــي البنتــه يف‬\n      ‫منزلهــا فإننــا نرجــو مــن فضيلتكــم النظــر بعــن االعتبــار مــا عانتــه هــذه‬\n      ‫الطفلــة طــوال الفتــرات املاضيــة ‪ ،‬وبســؤال وكيــل املدعــي عــن مــا‬\n      ‫ذكــره وكيــل املدعــى عليهــا أجــاب غيــر صحيــح مــا ذكــره وكيــل‬\n      ‫املدعــى عليهــا يف رد دعــوى موكلــي والصحيــح مــا ذكرنــاه ســابق ًا‬\n      ‫وموكلــي يرفــض مــا طرحــه وكيــل املدعيــة بعــدم املمانعــة مــن زيــارة‬\n      ‫ابنتــه يف منــزل والدتهــا ويطالــب باحلكــم بزيــارة ابنتــه يف بيتــه وعليــه‬\n      ‫قــررت الكتابــة لقســم اخلبــراء لتحديــد مــدة الزيــارة ومكانهــا ويف‬\n      ‫جلســة أخــرى بتاريــخ ‪1434/01/14‬ه ـ وفيهــا حضــر حامــل بطاقــة‬\n      ‫وكيــا عــن ‪ ......‬بصفتــه وكيــا عــن املدعــي بالوكالــة (‪ ).....‬يف‬\n      ‫‪1433/6/9‬ه ـ جلــد ‪ 20481‬الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بالريــاض كمــا حضــر وكيــل املدعــى عليــه واملدعــي أصالــة ووكيلــه‬\n      ‫ووكيــل املدعــى عليهــا احلاضــرون يف جلســات ســابقة وقــد وردنــا قــرار‬\n      ‫قســم اخلبــراء تاريــخ ‪1433/12/26‬ه ـ ونــص احلاجــة منــه (وجــرى عــرض‬\n      ‫الصلــح عليهمــا بشــأن الزيــارة فلــم يصطلحــا وقــد أقــر وكيــل املدعــى‬\n      ‫عليهــا بأنــه ال مانــع لــدى موكلتــه مــن زيــارة املدعــى البنتــه يف منزلهــا‬\n      ‫مبدئي ـ ًا حتــى تتحســن نفســيتها ومــن ثــم ميكــن االتفــاق بعــد حتســن‬\n      ‫نفســيتها بــأن تقــوم بزيــارة والدهــا يف منزلــه نظــر ًا لالعتــداءات التــي‬\n      ‫كانــت تقــع عليهــا وتكــون يومـ ًا واحــد ًا منــزل والدتهــا كمــا يف إقــراره‬\n      ‫املرفــق وأقــر املدعــي برغبتــه يف زيــارة ابنتــه لــه يف بيتــه أســبوعي ًا مــن‬\n      ‫بعــد عصــر يــوم األربعــاء مباشــرة إلــى قبــل صــاة املغــرب مــن يــوم اجلمعــة‬\n      ‫وأمــا اإلجــازات املدرســية فتكــون عنــده يف النصــف األول مــن اإلجــازة‬\n      ‫الصيفيــة كمــا يف إقــراره املرفــق وقــد حضــرت البنــت (‪ ).....‬وأقــرت‬\n\n\n‫‪309‬‬\n\f‫بعــدم رغبتهــا يف زيــارة والدهــا يف منزلــه وذكــرت عــدة أســباب مرفقــة‬\n‫باملعاملــة لــذا فــإن الــذي نــراه إن ثبــت لــدى فضيلــة ناظــر القضيــة مــا‬\n‫ذكرتــه احملضونــة فتكــون الزيــارة يف منــزل والدتهــا يــوم األربعــاء مــن‬\n‫كل أســبوع مــن بعــد صــاة العصــر يــوم األربعــاء حتــى صــاة املغــرب‬\n‫وإن لــم يثبــت ذلــك فتكــون الزيــارة أســبوعي ًا مــن بعــد صــاة العصــر‬\n‫يــوم األربعــاء حتــى صــاة العصــر يــوم اخلميــس ويف اإلجــازات تكــون‬\n‫الزيــارة لــأب يف اإلجــازة الصيفيــة يف الشــهر األول منهــا وهــو شــهر‬\n‫شــعبان كامــا ويف األعيــاد تكــون الزيــارة لــأب يف عيــد األضحــى‬\n‫يأخــذ ابنتــه مــع بدايــة إجــازة عيــد األضحــى ويعيدهــا يــوم األربعــاء‬\n‫األخيــر قبــل الدراســة علــى أن يقــوم املدعي بأخذ ابنتــه لزيارته وإعادتها‬\n‫ملنــزل والدتهــا هــذا مــا لدينا)أه ـ وبعــرض ذلــك علــى املدعــي أصالــة‬\n‫واملدعــى عليــه وكالــة قــال املدعــي أصالــة ال أوافــق علــى تقديــر الزيــارة‬\n‫املرصــودة أعــاه فهــي غيــر كافيــة وال أوافــق علــى القــرار جملــة‬\n‫وتفصيــا فــا يكفــي زيــارة يــوم واحــد ملــدة أربــع وعشــرين ســاعة‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال أوافــق‬\n‫علــى الزيــارة تكــون يف بيــت والدتهــا علــى مــا جــاء يف القــرار املرصــود‬\n‫أعــاه أمــا الذهــاب لبيــت والدهــا فابنتــه ال توافــق علــى ذلــك هكــذا‬\n‫أجــاب وقــد جــرى االطــاع علــى مــا مت إرفاقــه يف قســم اخلبــراء منســوب ًا‬\n‫للبنــت (‪ ).....‬املتضمــن (أنــا ال أرغــب بزيــارة والــدي يف منزلــه وإذا أبــي‬\n‫يرغــب بزيارتــي فليتفضــل عنــدي يف البيــت وذلــك ألســباب منهــا القســوة‬\n‫مــن بابــا وعمــي وجدتــي وأخــاف أال أرجــع ألمــي وتعرضــت للعنــف مــن‬\n‫جدتــي واخلنــق واإلهانــة يف املدرســة ومــا كنــت أقــدر أتنفــس وكانــت‬\n‫مامــا تســاعدني وأنــا أبكــي وكل هــذا أمــام مــن يف املدرســة وأنــي‬\n\n\n                                                                                     ‫‪310‬‬\n\f      ‫أتعالــج نفســي ًا بســبب هــذه احلادثــة وانقطــاع أبــي عــن زيارتــي ‪ 4‬ســنوات‬\n      ‫وأخــاف مــن القســوة واملعاملــة الســيئة مــن زوجــة والــدي) أه ـ وبعــرض‬\n      ‫ذلــك علــى املدعــي أصالــة قــال هــذا غيــر صحيــح هكــذا أجــاب ‪ .‬وهــذا‬\n      ‫وقــد جــرى ســؤاله هــل يســكن مــع زوجتــه احلاليــة يف بيــت مســتقل قــال‬\n      ‫نعــم فأنــا أســكن يف بيــت مســتقل مــع أوالدي وزوجتــي (‪ ).....‬ووالدتــي‬\n      ‫يف بيــت مســتقل لوحدهــا خــارج مدينــة الريــاض هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه وكالــة قــال صحيــح بأنــه يســكن مــع زوجتــه‬\n      ‫احلاليــة وأوالدهــا ولكــن والدتــه تســكن معــه وليســت يف بيــت مســتقل‬\n      ‫هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى صــك احلضانــة الصــادر‬\n      ‫مــن هــذه احملكمــة جلــد ‪19/35‬بتاريــخ ‪1430/10/22‬ه ـ املتضمــن‬\n      ‫حكــم احلضانــة للمدعــى عليهــا بابنــة املدعــي (‪ ).....‬فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وألن الولــد مأمــور باإلحســان لوالديــه فقــد قــال‬\n      ‫اهلل تعالــى ((وقضــى ربــك أال تعبــدوا إال إيــاه وبالوالديــن إحســانا)) وهــو‬\n      ‫محتــاج إلــى أبيــه كمــا هــو محتــاج إلــى أمــه والبنــت محتاجــة إلــى أبيهــا‬\n      ‫يف تزويجهــا وتربيتهــا علــى أهــداف حســنة قــد ال جتدهــا عنــد األم وملــا‬\n      ‫فيــه مــن تربيــة لهــا علــى صلــة الرحــم بأبيهــا وأقاربــه وألن يف مثــل حــال‬\n      ‫اخلصمــن عنــد حصــول الفرقــة بينهمــا قــد حتصــل اخلالفــات وتظهــر‬\n      ‫الدعــاوى الكاذبــة لذلــك كلــه فقــد حكمــت مبــا جــاء يف قســم اخلبراء‬\n      ‫ونصــه (فتكــون الزيــارة أســبوعي ًا مــن بعــد صــاة العصــر يــوم األربعــاء‬\n      ‫حتــى صــاة العصــر يــوم اخلميــس ويف اإلجــازات تكــون الزيــارة لــأب‬\n      ‫يف اإلجــازة الصيفيــة يف الشــهر األول منهــا وهــو شــهر شــعبان كامــا‬\n      ‫ويف األعيــاد تكــون الزيــارة لــأب يف عيــد األضحــى يأخــذ ابنتــه مــع‬\n      ‫بدايــة إجــازة عيــد األضحــى ويعيدهــا يــوم األربعــاء األخيــر قبــل الدراســة‬\n\n\n‫‪311‬‬\n\f‫علــى أن يقــوم املدعــي بأخــذ ابنتــه لزيارتــه وإعادتهــا ملنــزل والدتهــا)) مــع‬\n‫أخــذ كفيــل علــى املدعــي أصالــة يف االلتــزام بإعــادة ابنتــه (‪ ).....‬إلــى‬\n‫والدتهــا بعــد نهايــة فتــرة كل زيــارة وبعــد إعالنــه لــم يقنــع بــه املدعــي‬\n‫أصالــة وكذلــك لــم يقنــع بــه املدعــى عليــه وكالــة وطلبــا متيــزه واســتعد‬\n‫التقــدمي الئحــة اعتراضيــة فأفهمــا بــأن عليهمــا مراجعــة احملكمــة يــوم‬\n‫االثنــن ‪1434/1/19‬ه ـ الســتالم نســخة مــن احلكــم وأن لهمــا مــدة‬\n‫ثالثــن يوم ـ ًا تبــدأ مــن موعــد اســتالم نســخة احلكــم وإذا انتهــت املــدة‬\n‫ولــم يقدمــا خاللهــا الئحتهمــا االعتراضيــة فيســقط حــق مــن لــم يعتــرض‬\n‫ويكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/01/14‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/02/13‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي وقــدم الئحتــه االعتراضيــة‬\n‫املقيــدة يف احملكمــة برقــم يف ‪1434/2/13‬ه ـ واملكونــة مــن ســبع‬\n‫ورقــات مكتوبــة باحلاســب اآللــي مــع مرفقاتهــا وقــد رفعــت اجللســة‬\n‫لدراســتها ويف جلســة أخــرى بتاريــخ ‪1434/2/17‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر وكيــل املدعــى عليهــا وقــدم الئحتــه االعتراضيــة املقيــدة‬\n‫يف احملكمــة برقــم يف ‪1434/2/17‬ه ـ واملكونــة مــن ورقتــن مكتوبــة‬\n‫باحلاســب اآللــي مــع مرفقاتهــا وقــد رفعــت اجللســة لدراســتها ويف جلســة‬\n‫أخــرى بتاريــخ ‪1434/4/2‬ه وفيهــا حضــر املدعــي أصالــة وحضر وكيله‬\n‫كمــا حضــر املدعــى عليــه وكالــة احلاضــرون يف جلســة ســابقة وبعــد‬\n‫االطــاع علــى الالئحــة املقدمــة مــن املدعــى عليــه وكالــة جــرى ســؤاله‬\n‫عــن القضيــة التــي يذكــر بأنــه مســجل فيهــا بــاغ ضــد املدعــي ووالدتــه‬\n‫بشــأن االعتــداء علــى ابنتــه (‪ ).....‬فقــال إن املعاملــة لــدى إدارة احلقــوق‬\n\n\n                                                                                        ‫‪312‬‬\n\f      ‫املدنيــة وســوف أحضــر رقمهــا غــدا لطلبهــا منكــم مــن احلقــوق املدنيــة‬\n      ‫لالطــاع عليهــا لوجــود مــا يؤثــر فيهــا علــى احلكــم هكــذا أجــاب ويف‬\n      ‫جلســة أخــرى بتاريــخ ‪1434/5/6‬ه ـ حضــر املدعــي أصالــة وحضــر‬\n      ‫وكيلــه كمــا حضــر املدعــى عليــه وكالــة احلاضــرون يف جلســة ســابقة‬\n      ‫وقــد ســبق الكتابــة ملديــر إدارة تنفيــذ األحــكام احلقوقيــة برقــم (‪).....‬‬\n      ‫وتاريــخ ‪1434/04/06‬ه ـ لتزويدنــا ببيانــات املدعــى عليــه وكالــة ولــم‬\n      ‫تردنــا اإلفــادة حتــى تاريخــه ويف جلســة أخــرى بتاريــخ ‪1434/06/25‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n      ‫احلاضــران يف اجللســة الســابقة‪ ،‬وقــد ســبق الكتابــة ملديــر إدارة تنفيــذ‬\n      ‫األحــكام احلقوقيــة برقــم (‪ ).....‬وتاريــخ ‪1434/04/06‬ه لتزويدنــا‬\n      ‫ببيانــات املدعــى عليــه وكالــة ولــم تردنــا اإلفــادة حتــى تاريخــه‪ ،‬كمــا‬\n      ‫قــرر املدعــى عليــه وكالــة بــأن قــام مبراجعــة إدارة تنفيــذ األحــكام‬\n      ‫احلقوقيــة ومت إفادتــه بــأن املعاملــة صــدرت إلــى احملكمــة ‪ ،‬ومبراجعــة‬\n      ‫االتصــاالت اإلداريــة يف احملكمــة أفــاد املوظــف بــأن املعاملــة قــد‬\n      ‫أحيلــت باخلطــأ لدائــرة التنفيــذ الثانيــة وقــد أبــرز ورقــة املراجعــة التــي‬\n      ‫تثبــت ذلــك وأنهــا أحيلــت لدائــرة التنفيــذ برقــم القيــد ‪ 341484344‬يف‬\n      ‫‪1434/06/21‬هــ‪ ،‬كمــا تعهــد املدعــى عليــه وكالــة مبراجعــة دائــرة‬\n                                                           ‫التنفيــذ إلحالتهــا ملكتبنــا‪.‬‬\n      ‫ويف جلســة أخــرى بتاريــخ ‪1434/07/10‬ه ـ حضــر املدعــي أصالــة‬\n      ‫ووكيلــه واملدعــى عليــه وكالــة احلاضــرون يف اجللســة الســابقة‪،‬‬\n      ‫وجــرى ســؤال املدعــى عليــه وكالــة عــن املعاملــة التــي وعــد بإحضارهــا‬\n      ‫والتعقيــب عليهــا يف اجللســة الســابقة ‪ ،‬فقــال إن املعاملــة بعــد مراجعــة‬\n      ‫قســم صحائــف الدعــوى قالــوا بأنهــا مفقــودة ويطلبــون مهلــة للبحــث‬\n\n\n‫‪313‬‬\n\f‫عنهــا هكــذا قــرر‪ ،‬ونظــرا لعــدم إحضــار املدعــى عليــه وكالــة بينتــه‬\n‫والتــي طلــب املهلــة مــن أجــل إحضارهــا أكثــر مــن مــرة‪ ،‬ممــا يعــد ذلــك‬\n‫عجــزا عــن إحضارهــا ‪ ،‬ولكــون ذلــك فيــه ضــرر بخصمــه وبنــاء علــى‬\n‫املــادة (‪ )122‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ‪ ،‬وبعــد‬\n‫االطــاع علــى الالئحتــن االعتراضيتــن املقدمتــن مــن املدعــي واملدعــى‬\n‫عليــه وكالــة واملشــار لهمــا يف جلســات ســابقة لــم يظهــر لــي ســوى مــا‬\n‫حكمــت بــه وقــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيقــه‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/10‬ه ـ‬\n‫احلمد هلل وحده وبعد يف هذا اليوم الثالثاء ‪1434/09/01‬هـ وقد عادت‬\n‫املعاملــة مــن محكمــة االســتئناف بكتابهــم وتاريــخ ‪1434/08/14‬ه ـ‬\n‫وبرفقــه القــرار وتاريــخ ‪1434/7/30‬ه ـ الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية الثانيــة املتضمــن مــا نصــه (وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحتــن االعتراضيتــن وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى‬\n‫احلكــم ) اهــ‪ .‬وكــي ال يخفــى جــرى إحلاقــه ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                               ‫ســلم علــى محمــد‪ ،‬حــرر يف ‪1434/09/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض وتاريــخ ‪1433/7/11‬ه ـ املرفــق بهــا الصــك الصــادر من فضيلة‬\n‫القاضــي باحملكمــة الشــيخ(‪ ).....‬وتاريــخ ‪1434/1/17‬ه ـ اخلــاص‬\n‫بدعــوى يف قضيــة زيــارة أوالده وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحتــن‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫االعتراضيتــن وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":305,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2fa340bf2cfb9a2e68edb1296e8c104d1834dd5e19f7f98aee075a63e12f0c12","normalized_text_hash":"923ae917b01de3f16bf675f91181ec5096fadc09d1154489ce2a507c277f30a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p305-3413376"},{"id":"46cce139-f652-5479-bfc6-c1885fedc1a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"زيارة -املطالبة بزيارة أم البنتها وحتديد وقت لذلك -وافق املدعى عليه على الطلب واختلفا يف طريقة الزيارة -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب قرار اخلبراء- حكم الزيارة مشمول بالنفاذ املعجل .","document_number":"3410413","case_number":"3267845","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"زيارة -املطالبة بزيارة أم البنتها وحتديد وقت لذلك -وافق املدعى عليه على الطلب واختلفا يف طريقة الزيارة -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب قرار اخلبراء- حكم الزيارة مشمول بالنفاذ املعجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3410413 :‬‬\n                   ‫َر ْق ُم الدعوى‪3267845 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34201776‬تاريخه‪1434/4/3:‬هـ‬\n\n\n‫زيــارة ‪ -‬املطالبــة بزيــارة أم البنتهــا وحتديــد وقــت لذلــك ‪ -‬وافــق املدعى‬\n‫عليــه علــى الطلــب واختلفــا يف طريقــة الزيــارة ‪ -‬حتديــد الزيــارة‬\n‫ووقتهــا عــن طريــق قســم اخلبــراء ‪ -‬احلكــم مبوجــب قــرار اخلبــراء‪-‬‬\n                               ‫حكــم الزيــارة مشــمول بالنفــاذ املعجــل ‪.‬‬\n\n\n\n\n‫‪ -1‬قــال اهلل تعالــى (وقضــى ربــك أال تعبــدوا إال إيــاه وبالوالديــن‬\n                                                                     ‫إحســانا)‬\n‫‪ -2‬قــول الرســول صلــى اهلل عليــه وســلم مــن أولــى النــاس بصحبتــي‬\n‫قــال (امــك قــال ثــم مــن قــال أمــك قــال ثــم مــن قــال أمــك قــال ثــم‬\n                                                             ‫مــن قــال أبــوك)‪.‬‬\n                     ‫‪-3‬املادة رقم ‪ 199-198‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت أم بدعواهــا ضــد مطلقهــا تطالبــه بتمكينهــا مــن زيــارة ابنتهــا ‪-‬‬\n‫صــادق املدعــى عليــه علــى دعــوى املدعيــة ووافــق علــى طلبهــا ‪ -‬اختلــف‬\n‫الطرفــان علــى وقــت الزيــارة ‪ -‬كتبــت احملكمــة لهيئــة النظــر لديهــا‬\n‫فاجتمعــت الهيئــة بالطرفــن وقــررت حتديــد موعــد الزيــارة ووافقــت‬\n‫املدعيــة علــى قــرار الهيئــة يف حتديــد الزيــارة ورفضــه املدعــى عليــه‬\n\n                                                                                   ‫‪316‬‬\n\f      ‫بحجــة انــه وقــت طويــل وفيــه مبيــت ويرفــض مبيــت ابنتــه عنــد والدتهــا‬\n      ‫‪ -‬حكمــت احملكمــة مبوجــب قــرار هيئــة النظــر والزمــت األب بــأن‬\n      ‫يقــوم هــو بإيصالهــا إلــى بيــت أمهــا وان تكــون املدعيــة هــي املســؤولة‬\n      ‫عــن إعادتهــا وكان احلكــم مشــمو ًال بالنفــاذ املعجــل بــدون كفالــة بنــاء‬\n      ‫علــى املــادة ‪ 199/198‬مــن نظــام املرافعــات الشــرعية ‪ -‬لــم يقنــع املدعــى‬\n                                                              ‫عليــه ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامة‪/‬املســاعد وتاريــخ ‪1432/03/05‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n      ‫‪1432/3/5‬ه وفيهــا حضــرت املدعيــة (‪ ).....‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي (‪ ).....‬وحضــر أخوهــا املعــرف لها (‪ ).....‬ســعودي اجلنســية‬\n      ‫وحضــر حلضــوره (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬قائلــة يف دعواهــا ‪ ......‬املدعــى عليــه هــو مطلقــي مبوجــب الصــك‬\n      ‫الشــرعي الصــادر مــن قبــل احملكمــة العامــة بالريــاض رقــم (‪).....‬‬\n      ‫وتاريــخ ‪1432/11/27‬ه ـ وقــد أجنبــت منــه علــى فــراش الزوجيــة بنت ـ ًا‬\n      ‫واحــدة اســمها (‪ ).....‬املولــودة بتاريــخ ‪1419/02/23‬ه ـ وألن البنــت‬\n      ‫يف حضانــة ورعايــة والدهــا أرغــب يف حتديــد وقــت لزيارتهــا لــي هــذه‬\n      ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه صــادق علــى صحتــه الدعــوى‬\n      ‫جملــة وتفصيــا وقــرر بأنــه ال مانــع لــدي مــن حتديــد وقــت لزيــارة ابنتنــا‬\n      ‫لهــا وهكــذا أجــاب ثــم قــرر الطرفــان أن هنــاك جلســة لــدى هيئــة‬\n      ‫النظــر يــوم الثالثــاء ‪1433/08/27‬ه ـ لتحديــد وقــت الزيــارة ومــا يتعلــق‬\n\n‫‪317‬‬\n\f‫بشــؤون البنــت وتطلــب اإلمهــال حتــى ذلــك احلــن فأجيــب لطلبهــا ويف‬\n‫جلســة أخــرى حضــرت (‪ ).....‬ســعودية وحضــر أخوهــا املعــرف لهــا (‪).....‬‬\n‫ســعودي ســجل رقــم (‪ ).....‬وحضــر حلضــوره (‪ ).....‬ســجل رقــم(‪ ).....‬وقــد‬\n‫وردنــا خطــاب هيئــة النظــر قــرار رقــم (‪ ).....‬وتاريــخ ‪1433/11/08‬ه ـ‬\n                       ‫واملتضمــن مــا نصــه قــرار وتاريــخ ‪1433/11/02‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ...‬وبعــد ‪:‬‬\n‫بنــاء علــى خطــاب فضيلــة القاضــي وتاريــخ ‪1433/07/20‬ه ـ بخصــوص‬\n‫دعــوى (‪ ).....‬ضــد (‪ ).....‬ومطالبــة املدعيــة بزيــارة ابنتهــا (‪ ).....‬وطلــب‬\n‫فضيلتــه حتديــد وقــت الزيــارة املناســبة نفيــد فضيلتــه انــه جــرى اجللــوس‬\n‫مــع الطرفــن ومداولــة الصلــح بينهمــا يف أكثــر مــن جلســة ولــم نتوصــل‬\n‫إلــى حــل ينهــي النــزاع القائــم بينهمــا وقــد طالبــت املدعيــة أن تكــون‬\n‫الزيــارة يومــن باألســبوع أمــا املدعــى عليــه فإنــه ال مانــع لديــه مــن متكني‬\n‫املدعيــة مــن زيــارة ابنتهــا يف آخــر جمعــة مــن كل شــهر وإذا أرادت‬\n‫املدعيــة زيــارة ابنتهــا يف مــدة اقــل مــن ذلــك فإنــه ال مانــع لديــه بشــرط ان‬\n‫تأتــي لزيارتهــا يف منزلــه وبرفقتهــا أحــد محارمهــا متــى مــا أرادا ذلــك مــا‬\n‫عــدا يــوم اخلميــس كل ذلــك جــاء بإقراريهمــا املرفقــن بطــي املعاملة ويف‬\n‫يــوم األربعــاء املوافــق ‪1433/10/25‬ه ـ حضــرت البنــت محــل الدعــوى‬\n‫برفقــة والدهــا املدعــى عليــه وأقــر أنهــا تطلــب زيــارة والدتهــا يــوم اجلمعــة‬\n‫أســبوع بعــد أســبوع وأن يكــون الوقــت مــن الســاعة السادســة مســاء‬\n‫إلــى الســاعة الثامنــة مســاء مــن نفــس اليــوم كمــا ذكــرت أن والدهــا‬\n‫ليــس لــه أي ضغــوط عليهــا أو تدخــل بخصــوص حتديــد الزيــارة وجتــدون‬\n‫إقرارهــا بطــي املعاملــة ويف يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ‬\n‫حضــرت املدعيــة إلــى مكتبنــا وجــرى اطالعهــا علــى مــا كتبــت ابنتهــا‬\n\n\n                                                                                         ‫‪318‬‬\n\f      ‫بخصــوص الزيــارة وأفــادت أن مــا كتبتــه ابنتهــا جــراء ضغــوط مــن‬\n      ‫والدهــا كمــا ذكــرت أن البنــت عاشــت معهــا وبحضانتهــا مــدة اثنــي‬\n      ‫عشــرة ســنة وكانــت متعلقــة بهــا أمــا والدهــا فــا يزورهــا تلــك الفتــرة إال‬\n      ‫نــادر ًا وكانــت تخــاف منــه كثيــر ًا إضافــة إلــى أن البنــت تســكن حاليـ ًا‬\n      ‫مــع والدهــا واخلادمــة فقــط وال تــدري رمبــا تكــون عمتهــا (‪ ).....‬معهــم‬\n      ‫يف املنــزل كمــا أن والدهــا كثيــر اخلــروج مــن املنــزل كمــا ذكــرت‬\n      ‫انــه البــد مــن األخــذ بعــن االعتبــار بــدون النظــر إلــى رغبــة البنــت ألن‬\n      ‫البنــت يف مرحلــة املراهقــة ويعتريهــا مــا يعتــري النســاء فهــي بحاجــة إلــى‬\n      ‫والدتهــا واستشــارتها وكذلــك إرشــادها ملــا فيه مصلحتهــا كما أفادت‬\n      ‫أن البنــت انقطعــت عنهــا ملــدة ثــاث ســنوات ولــم تتمكــن مــن التواصــل‬\n      ‫معهــا إال نــادر ًا أمــا والدهــا فانــه ال يرغــب بزيارتهــا بســبب ان املدعيــة‬\n      ‫طلقــت منــه بــدون رضــاه وقــد ضايقهــا يف عملهــا ورفــع عليهــا اكثــر مــن‬\n      ‫قضيــة يف احملكمــة اجلزائيــة والعامــة وكلهــا حكــم بصــرف النظــر‬\n      ‫عنهــا كمــا أن لديهــا دعــوى بالنفقــة والزيــارة عليــه كل ذلــك جــاء يف‬\n      ‫إقرارهــا املرفــق بطــي املعاملــة والــذي نــراه بعــد اجللــوس مــع الطرفــن‬\n      ‫بأكثــر مــن جلســة والتأمــل يف حالهمــا ومــا جــاء يف إقرارهمــا وإقــرار‬\n      ‫البنــت أن تكــون الزيــارة يــوم اخلميــس مــن الســاعة اخلامســة عصــر ًا‬\n      ‫حتــى يــوم اجلمعــة الســاعة اخلامســة عصــرا وذلــك لعظــم حــق األم ومــا‬\n      ‫جــاء يف عمــوم األدلــة الــواردة عنــه عليــه الصــاة والســام بحــق األم ومــن‬\n      ‫ذلــك قولــه للرجــل الــذي ســأله ‪ :‬مــن أولــى النــاس بصحبتــي يــا رســول‬\n      ‫اهلل قــال أمــك قــال ثــم مــن قــال أمــك قــال ثــم مــن قــال أمــك قــال ثــم مــن‬\n      ‫قــال أبــوك والبــد مــن تربيــة البنــت علــى النهــج الصحيــح وهــو معرفــة‬\n      ‫قــدر والدتهــا وأن زيارتهــا أســبوع بعــد أســبوع كمــا طالبــت البنــت فيــه‬\n\n\n‫‪319‬‬\n\f‫محــذور شــرعي حيــث انــه ليــس مــن البــر واإلحســان الــذي أمــر اهلل بــه‬\n‫وحــث عليــه رســوله صلــى اهلل عليــه وســلم ( وقضــى ربــك أال تعبــدوا‬\n‫إال إيــاه وبالوالديــن إحســاناً) ‪ .‬هــذا مــا لدينــا واهلل يحفظكــم أعضــاء‬\n‫مكتــب الصلــح وتوقيعــه و وتوقيعــه ) أ‪.‬هــ‪ .‬وبعرضــه علــى الطرفــن‬\n‫قــررا موافقتهمــا علــى ذلــك علــى أن يكــون اللقــاء عصــر يــوم األربعــاء‬\n‫إلــى عصــر يــوم اخلميــس مــن كل أســبوع ثــم عــاد األب وقــرر رغبتــه‬\n‫أن يكــون الزيــارة مــن بعــد يــوم األربعــاء إلــى عصــر اخلميــس ولكــن‬\n‫كل أســبوعني هكــذا أجــاب عليــه وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وملــا تضمنــه نقــرر هيئــة النظــر وهــم أهــل اخلبــرة ومــا ورد مــن‬\n‫حيثيــات فيــه حيــال حاجــة البنــت إلــى التواصــل مــع أمهــا وبرهــا وان‬\n‫هــذا يقتضــي التواصــل القريــب ال البعيــد خصوصــا مــع بلــوغ البنــت هــذه‬\n‫الســن لذلــك كلــه وبنــاء علــى املــادة ‪ 199 - 198‬مــن نظــام املرافعــات‬\n‫فقــد حكمــت بزيــارة البنــت (‪ ).....‬ألمهــا كل أســبوع مــن عصــر يــوم‬\n‫األربعــاء إلــى عصــر يــوم اخلميــس علــى أن يكــون املســؤول عــن إيصالهــا‬\n‫ألمهــا هــو والدهــا واملســؤول عــن إعادتهــا لوالدهــا هــي أمهــا وذلــك‬\n‫حكمــا مشــموال بالنفــاذ املعجــل بــدون كفالــة فقنعــت املدعيــة ولــم‬\n‫يقنــع املدعــى عليــه فافهــم بــان لــه أن يتقــدم باعتراضــه علــى احلكــم‬\n‫مــن تاريــخ اســتالم نســخة احلكــم وهــو هــذا اليــوم ‪1434/01/12‬ه ملــدة‬\n‫ال تتجــاوز ثالثــون يومــا ففهــم ذلــك إذا لــم يقــدم االعتــراض خــال املــدة‬\n‫فإنــه يســقط حــق االعتــراض ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل‬\n         ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/1/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء املوافق‪1434/05/22‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 08.15‬وقــد عــادت املعاملــة مــن محكمــة‬\n\n\n                                                                                      ‫‪320‬‬\n\f      ‫االســتئناف وبرفقهــا قــرار دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n      ‫وتاريــخ ‪1434/04/03‬ه ـ واملتضمــن‪ :‬أنــه بدراســة الصــك وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n      ‫باألكثريــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى مراعــاة تدويــن شــرح‬\n      ‫اطالعــه علــى الالئحــة االعتراضيــة وذلــك يف الضبــط حســب التعليمــات‬\n      ‫ال ‪ ).....( .‬ختمــه وتوقيعــه ‪ ).....( ،‬ختمــه وتوقيعــه ‪ ).....( ،‬ختمــه‬\n                                                                              ‫مســتقب ً‬\n      ‫وتوقيعــه ‪ .‬اهــ‪ .‬وبذلــك يكــون احلكــم قــد اكتســب القطعيــة وحتــى ال‬\n      ‫يخفــى جــرى تدوينــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة املســاعد‬\n      ‫وتاريــخ ‪1434/4/13‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n      ‫باحملكمــة الشــيخ (‪ ).....‬وتاريــخ ‪1434/1/12‬ه ـ اخلــاص بدعــوى‬\n      ‫(‪ ).....‬يف قضيــة زيــارة أوالده وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة باألكثريــة علــى‬\n      ‫احلكــم مــع تنبيــه فضيلتــه إلــى مراعــاة تدويــن شــرح اطالعــه علــى‬\n      ‫ال‬\n      ‫الالئحــة االعتراضيــة وذلــك يف الضبــط حســب التعليمــات مســتقب ً‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪321‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                  ‫املوضوع‬                   ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة الزوجة بسداد املؤخر من الصداق‬\n  ‫‪5‬‬      ‫وحلفها بيمني النفي واحلكم على املدعى‬      ‫صداق‬     ‫‪1‬‬\n                   ‫عليه بدفع املؤخر‬\n\n\n         ‫مطالبة الزوجة بصداق مؤخر وتكاليف‬\n           ‫احلفل حيث وقع الطالق قبل الدخول‬\n  ‫‪9‬‬                                                ‫صداق‬     ‫‪2‬‬\n           ‫باقرار املتداعيني وإلزام املدعى عليه‬\n         ‫(الزوج) بدفع نصف املهر وتكاليف احلفل‬\n\n\n           ‫طلب أرملة مبؤخر صداقها وما أضيف‬\n  ‫‪15‬‬      ‫عليه من زيادة من التركة وإثبات صحة‬       ‫صداق‬     ‫‪3‬‬\n                 ‫دعواها بشاهد وميينها‬\n\n\n          ‫مطالبة الزوجة زوجها بدفع املهر املتفق‬\n  ‫‪24‬‬     ‫عليه وسماع الدعوى غيابي ًا واحلكم على‬     ‫صداق‬     ‫‪4‬‬\n                       ‫الزوج بدفع املهر‬\n\n\n          ‫املطالبة باملهر بعد طالق الزوجة حسب‬\n          ‫العادات والتقاليد القبلية يف باكستان‬\n  ‫‪32‬‬                                               ‫صداق‬     ‫‪5‬‬\n             ‫واحلكم برد الدعوى لعدم ثبوتها‬\n                ‫وملخالفتها أحكام الشريعة‬\n\n\n            ‫مطالبة الزوجة لزوجها بعد الطالق‬\n          ‫برد ذهبها حيث أخذه وال بينة للمدعية‬\n  ‫‪44‬‬                                               ‫صداق‬     ‫‪6‬‬\n         ‫ورفضها ميني املدعى عليه (الزوج) واحلكم‬\n                       ‫برد دعواها‬\n\f‫الصفحة‬                  ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫املطالبة من وكيل الزوجة للمدعى عليه‬\n         ‫(الزوج)بإعادة مبلغ استلمه من وليها مقابل‬\n  ‫‪48‬‬       ‫طالقها حيث وقع الطالق وأثبت بصك‬           ‫صداق‬     ‫‪7‬‬\n            ‫شرعي قبل استالم العوض ومصادقة‬\n           ‫املدعى عليه وإلزامه برد املبلغ للمدعية‬\n\n\n          ‫مطالبة الزوج بإمتام الزواج ومتكينه من‬\n         ‫زوجته ورغبة الزوجة يف عدم أمتام النكاح‬\n  ‫‪59‬‬        ‫من غير سبب ظاهر‪،‬مخالفة الزوجة‬            ‫صداق‬     ‫‪8‬‬\n           ‫لزوجها وإلزامها برد املبالغ التي دفعها‬\n                  ‫الزوج من مهر وشبكة‬\n\n\n          ‫مطالبة مطلقة بالصداق املؤخر ورفض‬\n          ‫الزوج السداد ألن الطالق سببه املرأة‬\n  ‫‪65‬‬                                                 ‫صداق‬     ‫‪9‬‬\n          ‫ومصادقته على عقد النكاح وصك‬\n           ‫الطالق واحلكم عليه بدفع املؤخر‬\n\n\n          ‫مطالبة أم بإثبات عضل األب البنته ونقل‬\n           ‫الوالية إلى األخوة أنكر املدعى عليه‬\n  ‫‪73‬‬      ‫العضل ولم تثبت املدعية ما تدعيها وألن‬      ‫عضل‬      ‫‪10‬‬\n           ‫األصل براءة الذمة وال بينه لديها أخلت‬\n                   ‫احملكمة سبيل األب‬\n\n\n         ‫ادعت ابنة تطالب بإثبات غيبة والدها ورفع‬\n  ‫‪80‬‬      ‫والية تزويجها عنه وجعلها لألخ الشقيق‪.‬‬      ‫عضل‬      ‫‪11‬‬\n                        ‫الضرر يزال‬\n\n\n         ‫عضل األب لبناته وقيام البينة على الدعوى‬\n  ‫‪85‬‬      ‫بالشاهدين املعدلني واحلكم برفع والية‬       ‫عضل‬      ‫‪12‬‬\n              ‫األب الغائب وجعلها لألخ الشقيق‬\n\f‫الصفحة‬                  ‫املوضوع‬                     ‫التصنيف‬      ‫م‬\n\n\n             ‫احلكم بثبوت عضل الولي(األخ)‬\n  ‫‪92‬‬     ‫للمدعيتني بشهادة الشهود العدول وانتقال‬       ‫عضل‬        ‫‪13‬‬\n            ‫والية النكاح إلى احلاكم الشرعي‬\n\n\n         ‫مطالبة البنتني بإثبات عضل والدهما ورفع‬\n           ‫واليته عنهما وجعلها ألخيهما الشقيق‬\n          ‫ومطالبة أم املدعيتني برفع والية األب عن‬\n ‫‪100‬‬                                                  ‫عضل‬        ‫‪14‬‬\n         ‫بقية بناتها حتى ال يتضررن واثبات العضل‬\n         ‫بشهادة الشاهدين وإفادات اخلطاب وجعل‬\n         ‫والية التزويج جلميع البنات ألخيهن الشقيق‬\n\n\n          ‫مطالبة بنت بإلزام والدها بتزويجها أو‬\n           ‫احلكم بعضله رفض والدها تزويجها‬\n             ‫من اخلاطب كونه أجنبي ولشهادة‬\n ‫‪114‬‬      ‫الشهود بصالحيته وكفء اخلاطب ثبت‬             ‫عضل‬        ‫‪15‬‬\n          ‫لدى احملكمة صالحية اخلاطب ورفض‬\n          ‫احملكمة والية األب وجعلتها للحاكم‬\n                        ‫الشرعي‬\n\n\n          ‫مطالبة أخو الزوجة املتوفاة بإحلاق نسب‬\n ‫‪125‬‬                                                ‫إثبات نسب‬    ‫‪16‬‬\n              ‫ابنة أخته بأبيها املدعى عليه‬\n\n\n          ‫طلب إضافة بنت يف دفتر العائلة اخلاص‬\n ‫‪133‬‬                                                ‫إثبات نسب‬    ‫‪17‬‬\n                  ‫بوالدها املدعى عليه‬\n\n\n          ‫مطالبة الزوجة إثبات طالقها من زوجها‬\n            ‫املدعى عليه حيث طلقها ولم يراجعها‬\n           ‫ونفي الزوج لذلك حيث أقر مبراجعتها‬\n ‫‪143‬‬                                                ‫إثبات طالق‬   ‫‪18‬‬\n            ‫وقبول الزوجة لشهادة الشهود ووجود‬\n         ‫القرينة مع ميني املدعية‪،‬حيث تشرع اليمني‬\n                 ‫يف جانب أقوى املتداعيني‬\n\f‫الصفحة‬                   ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫طلب األم حضانة أوالدها حيث لم تتزوج‬\n          ‫بعد الطالق وتسكن يف سكن مستقل‬\n          ‫ومطالبة الزوج بحضانة ابنته ذات األربعة‬\n ‫‪159‬‬                                                  ‫حضانة‬    ‫‪19‬‬\n         ‫عشر عام ًا وتخيير األوالد بني أبيهم وأمهم‬\n         ‫واحلكم بحضانة الطفل ألمه لكونها لم‬\n            ‫تتزوج ولم يبلغ الطفل السن السابعة‬\n\n\n          ‫طلب األب حضانة أوالده ‪ ،‬وأن مطلقته‬\n          ‫(املدعى عليها) ال تصلح حلضانتهم حيث‬\n         ‫أنها ال حتافظ على الصالة وكثرة اخلروج‬\n ‫‪170‬‬       ‫من املنزل ووجود القنوات الفاسدة يف‬         ‫حضانة‬    ‫‪20‬‬\n          ‫منزلها ‪،‬مت تخيير األبناء فقرروا رغبتهم‬\n          ‫اإلقامة مع والدتهم ‪ ،‬واحلكم برد دعوى‬\n                ‫املدعي يف مطالبته باحلضانة‬\n\n\n         ‫طلب األم حضانة ابنها وتخيير االبن بني‬\n ‫‪180‬‬     ‫أمه وأبيه واختياره لوالده واحلكم ألبيه‬       ‫حضانة‬    ‫‪21‬‬\n         ‫بحضانته حيث قد بلغ السابعة من العمر‬\n\n\n         ‫مطالبة الزوج ملطلقته بحضانة ابنته التي‬\n          ‫جتاوزت السبع سنوات وتخيير القاضي‬\n ‫‪185‬‬                                                  ‫حضانة‬    ‫‪22‬‬\n         ‫البنت بني والديها فاختارت أمها‪ ،‬حكم‬\n         ‫القاضي لألم باحلضانة ألنها أحق من األب‬\n\n\n          ‫طلب حضانة بنت جتاوزت السابعة من‬\n          ‫أمها كون أبيها متزوج من عدة نساء‬\n ‫‪191‬‬                                                  ‫حضانة‬    ‫‪23‬‬\n          ‫وطلب أبيها احلضانة ملساومة األم على‬\n                    ‫التنازل عن النفقة‬\n\n\n            ‫طلب حضانة أوالد واحلكم لألم غير‬\n ‫‪196‬‬                                                  ‫حضانة‬    ‫‪24‬‬\n         ‫املتزوجة باحلضانة كونها األحق باحلضانة‬\n\f‫الصفحة‬                  ‫املوضوع‬                    ‫التصنيف‬   ‫م‬\n\n\n          ‫احلكم بحضانة البنات لألم من زوجها‬\n ‫‪203‬‬     ‫املتغيب عن البالد وقد طلقت منه مبوجب‬       ‫حضانة‬    ‫‪25‬‬\n              ‫صك من احملكمة الشرعية‬\n\n\n          ‫طلب اجلد حضانة أوالد ابنه املتوفى وقد‬\n            ‫تزوجت أمهم واحلكم لألم باحلضانة‬\n ‫‪208‬‬     ‫مصلحة لألبناء مع حضور زوج األم وإقراره‬     ‫حضانة‬    ‫‪26‬‬\n            ‫أنه ال مانع من بقاء أوالد زوجته عنده‬\n                     ‫وحتت حضانة أمهم‬\n\n\n           ‫طلب األم حضانة األوالد مع بقاء عقد‬\n            ‫الزوجية حيث ساءت العشرة بينهما‬\n ‫‪213‬‬                                                ‫حضانة‬    ‫‪27‬‬\n            ‫وخرجت الزوجة من بيت الزوجية‪،‬‬\n           ‫واحلكم بالنفاذ املعجل لألم باحلضانة‬\n\n\n          ‫طلب األم حضانة األوالد من بلغ ومن لم‬\n ‫‪217‬‬       ‫يبلغ مع تسليم األوراق الثبوتية وشهادة‬    ‫حضانة‬    ‫‪28‬‬\n                          ‫امليالد‪.‬‬\n\n\n          ‫احلكم بحضانة ابن عمره سبع سنوات‬\n ‫‪223‬‬      ‫لوالدته من دون تخيير بني األب واألم‬       ‫حضانة‬    ‫‪29‬‬\n          ‫لصالحية األم خالف ًا لقاعدة التخيير‬\n\n\n         ‫احلكم باحلضانة لألم كونها األحق حيث‬\n         ‫لم تتزوج وإلزامها بتمكني األب من زيارة‬\n ‫‪227‬‬                                                ‫حضانة‬    ‫‪30‬‬\n            ‫ابنتيه وحتديد مدة الزيارة عن طريق‬\n                         ‫اخلبراء‬\n\f‫الصفحة‬                  ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫طلب اجلدة حضانة بنت ابنتها ورغبة البنت‬\n ‫‪241‬‬      ‫أن تكون عند جدتها ألمها وتفضيلها‬           ‫حضانة‬    ‫‪31‬‬\n          ‫لذلك واألخذ برأي أهل اخلبرة يف ذلك‬\n\n\n          ‫طلب حضانة األوالد من الزوجة الناشر‬\n          ‫واختالف مكان إقامة الوالدين وتخيير‬\n ‫‪247‬‬                                                 ‫حضانة‬    ‫‪32‬‬\n           ‫األوالد بني والدهم ووالدتهم ملن جتاوز‬\n                         ‫السابعة‬\n\n\n         ‫مطالبة مبستندات تخص احملضون (جواز‬\n            ‫سفر وشهادة ميالد) وسفر احلاضنة‬\n ‫‪260‬‬                                                 ‫حضانة‬    ‫‪33‬‬\n         ‫باحملضون لغرض مؤقت ال يؤثر يف حقها‬\n                       ‫يف احلضانة‬\n\n\n            ‫احلكم باستحقاق األم حضانة بنت‬\n ‫‪267‬‬     ‫جتاوزت السابعة رغم زواج األم وعمل األب‬      ‫حضانة‬    ‫‪34‬‬\n                   ‫خارج مقر سكنه‬\n\n\n         ‫مطالبة األب املدعي ابنته البالغة (املدعى‬\n ‫‪274‬‬      ‫عليها) الغير متزوجة بتسليم نفسها له‬        ‫حضانة‬    ‫‪35‬‬\n                        ‫خوف ًا عليها‬\n\n\n          ‫املطالبة بحضانة أوالد بالغني وصرف‬\n ‫‪281‬‬      ‫النظر عن ذلك واحلكم بحضانة البنت‬           ‫حضانة‬    ‫‪36‬‬\n            ‫الغير بالغة ألمها كونها لم تتزوج‬\n\n\n         ‫طلب العمة حضانة أوالد أخيها لزواج األم‬\n ‫‪285‬‬     ‫وعملها وموافقة زوج األم على حضانة األم‬      ‫حضانة‬    ‫‪37‬‬\n           ‫ألوالدها وحترير ذلك يف عقد النكاح‬\n\f‫الصفحة‬                   ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n           ‫حضانة بنات دون السابعة ألمهم رغم‬\n ‫‪293‬‬      ‫تنازلها عن احلضانة مقابل اخللع كونه‬         ‫حضانة‬    ‫‪38‬‬\n                      ‫األصلح لهن‬\n\n\n         ‫مطالبة األب بزيارة ابنته وحتديد الزيارة‬\n ‫‪305‬‬                                                  ‫زيارة‬    ‫‪39‬‬\n              ‫ووقتها عن طريق قسم اخلبراء‬\n\n\n         ‫املطالبة بزيارة أم ألبنتها وحتديد الزيارة‬\n ‫‪316‬‬      ‫ووقتها عن طريق قسم اخلبراء واحلكم‬           ‫زيارة‬    ‫‪40‬‬\n                        ‫مبوجبه‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":316,"source_page_end":328,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b0e241a754a2a1ec9d30fd06a5421fe9463590cbe67f3383e4064c97952055f0","normalized_text_hash":"43150b3c3bbeca2473554546b694e976252a1a452dfdd24296252fd1bf74da5c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p316-3410413"},{"id":"cb8bc7a0-f55d-51bd-a937-745ee1480a5a","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة طفل -املطالبة بنفقة الطفل من والدته -دفع املدعى عليه بامتناعه عن النفقة المتناع الزيارة البنته -صرف النظر عن طلب األم نفقة ابنتها املاضية من األب ألنها لم تنو الرجوع بالنفقة عليه .","document_number":"347261","case_number":"3333621","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/10","year":"1434","subject":"نفقة -نفقة طفل -املطالبة بنفقة الطفل من والدته -دفع املدعى عليه بامتناعه عن النفقة المتناع الزيارة البنته -صرف النظر عن طلب األم نفقة ابنتها املاضية من األب ألنها لم تنو الرجوع بالنفقة عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/1/10 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪347261 :‬‬\n                       ‫َر ْق ُم الدعوى‪3333621 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 34277428‬تاريخه‪1434/7/24 :‬هـ‬\n\n\n\n    ‫نفقــة‪ -‬نفقــة طفــل‪ -‬املطالبــة بنفقــة الطفــل مــن والدتــه‪ -‬دفــع املدعــى‬\n    ‫عليــه بامتناعــه عــن النفقــة المتنــاع الزيــارة البنتــه‪ -‬صــرف النظــر‬\n    ‫عــن طلــب األم نفقــة ابنتهــا املاضيــة مــن األب ألنهــا لــم تنــو الرجــوع‬\n                                                                  ‫بالنفقــة عليــه ‪.‬‬\n\n\n\n    ‫مــا قــرره الفقهــاء مــن أن نفقــه األقــارب مــن آبــاء وابنائهــم وغيرهــم‬\n    ‫تســقط أذا انفــق غيــر مــن جتــب عليــه النفقــة عليهــم بغيــر نيــة الرجــوع‬\n    ‫جــاء يف كشــاف القنــاع (‪( )161/13‬ولــو امتنــع زوج أو قريــب مــن نفقــة‬\n    ‫واجبــة بــأن تطلــب منــه النفقــة فيمتنــع فقــام بهــا غيــره رجــع عليــه‬\n                                                            ‫منفــق بنيــة الرجــوع)‬\n\n\n\n\n    ‫ادعــت املدعيــة علــى املدعــى عليــه وكالــة بــأن موكلــه تزوجهــا ثــم‬\n    ‫طلقهــا بعــد أن أجنبــت لــه طفلــة وأنــه مــن تاريــخ والدة الطفلــة حتــى‬\n    ‫أخذهــا والدهــا لــم ينفــق عليهــا ســوى ألــف ومائتــن وخمســن ريــاالً‪،‬‬\n    ‫طلبــت املدعيــة إلــزام املدعــى عليــه بدفــع نفقــه ابنتهــا عــن املــدة املاضية‪،‬‬\n    ‫صــادق املدعــى عليــه وكالــة علــى مــا جــاء يف الدعــوى ودفــع بــأن ســبب‬\n    ‫امتنــاع موكلــه مــن النفقــة هــو منعــه مــن زيــارة ابنتــه‪ ،‬أبــرزت املدعيــة‬\n\n‫‪5‬‬\n\f‫ورقــة الصلــح واالتفــاق ومت رصــد مضمونهــا‪ ،‬جــرى ســؤال املدعيــة هــل‬\n‫كانــت تنــوي الرجــوع بالنفقــة على املدعى عليه قالت الســوى يف الشــهر‬\n‫األخيــر قبــل أن يأخــذ املدعــى عليــه ابنتــه‪ ،‬جرى تقدير نفقه هذا الشــهر‬\n‫عــن طريــق هيئــة النظــر‪ ،‬حيــث إن املطالبــة بالنفقــة تســقط إذا لــم ينــو‬\n‫املنفــق الرجــوع بالنفقــة علــى مــن جتــب عليــه لــذا صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بــأن يدفــع للمدعيــة نفقــة الشــهر األخيــر وصــرف النظــر‬\n‫عمــا زاد عــن ذلــك ممــا جــاء يف دعــوى املدعيــة‪ ،‬اعترضــت املدعيــة علــى‬\n                     ‫احلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بنجــران املســاعد برقــم ‪ 3333621‬وتاريــخ ‪ 1433/01/12‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3385627‬وتاريــخ ‪ 1433/01/12‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافق‪1433/02/10‬ه ـ حضــرت ‪ ...‬ســعودية اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬واملعــرف بهــا مــن قبــل اخيهــا ‪ ...‬مدعيــة‬\n‫علــى ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...‬الغائــب عــن‬\n‫مجلــس احلكــم وحضــر بالوكالــة عنــه ‪ ...‬ســعودي اجلنســية رقــم ‪...‬‬\n‫مبوجــب صــك الوكالــه رقــم‪ 34154‬بتاريــخ ‪1425/11/17‬ه ـ والتــي‬\n‫تخولــه حــق املرافعــة واملدافعــة لــدى احملكمــة ضــد طليقتــه ‪...‬قائلــة يف‬\n‫دعواهــا تزوجــت املدعــى عليــه ‪ ...‬يف عــام ‪1417‬ه ـ واجنبــت منــه ابنــة‬\n‫إســمها ‪ ...‬وعمرها االن ‪13‬ســنه وطلقني يف ‪1420/12/29‬هـ ولم ينفق‬\n‫علــى ابنتــي منــذ والد تهــا إال ألــف ومائتــن وخمســن ريــاال حتــى هــذا‬\n\n                                                                                    ‫‪6‬‬\n\f    ‫اليــوم أطلــب إلزامــه بالنفقــة املاضيــة علــى ابنتــي هــذه دعــواى وبعــرض‬\n    ‫ا ماذكرتــه‬     ‫ماجــاء يف الدعــوى علــى املدعــى عليــه وكالــة أجــاب قائ ـ ً‬\n    ‫املدعيــة صحيــح جملــة وأمــا التفصيــل فقــد أنفــق موكلــي علــى ابنتــه‬\n    ‫يف بدايــة االمــر النــه كان بينــه وبــن طليقتــه اتفــاق أن ينفــق علــى أن‬\n    ‫ميكنــوه مــن الزيــاره فبعــد إخاللهــم بالشــرط لــم يســتلموا بعدهــا شــيئا‬\n    ‫فقــد رفضــوا اســتالم النفقــة وتســليم البنــت للزيــارة ثــم ابــرزت املدعيــة‬\n    ‫ورقــة الصلــح واالتفــاق ووجــد أنهــا تتضمــن االتفــاق بــن وكيــل املدعيــة‬\n    ‫اخيهــا ‪...‬احلاضــر وطليقهــا ‪...‬واإلتفــاق يتضمــن أن ينفــق املدعــى عليــه‬\n    ‫‪...‬علــى ابنتــه مببلــغ ألفــن وخمســمائه ريــال ســنويا ويحــق لــي أخــذ البنــت‬\n    ‫للزيــاره يف كل شــهر وبعــرض الورقــه علــى املدعى عليــه وكاله صادقه‬\n    ‫عليهــا وبســؤال املدعيــة عــن ســبب منعــه للمدعــى عليــه‪ ...‬مــن زيــارة ابنتــه‬\n    ‫ومنعــه مــن اســتالم النفقــة أجابــت أنــا لــم أمنعــه مــن ذلــك ولكنــه لــم‬\n    ‫يــأت ألخذهــا ولــم يــأت لتســليم النفقــة هكــذا أجابــت وبســؤال املدعــى‬\n    ‫عليــه وكالــة عــن بيناتــه يف منعــه لــه بالزيــارة واســتالم النفقــة أجــاب‬\n    ‫بأنــه ال ميلــك ســوى شــاهد واحــد يشــهد بذلــك اســمه ‪ ...‬ثــم جــرى ســؤال‬\n    ‫املدعيــة عــن نفقتهــا علــى إبنتهــا هــل كانــت بينــة الرجــوع علــى والدهــا‬\n    ‫فقالــت ال حتــى شــهر جمــادى الثانيــة مــن عــام ‪1432‬ه ـ ويف شــهر رجــب‬\n    ‫مــن نفــس العــام أخــذ البنــت ولــم يرجعهــا حتــى تاريخــه ثــم رفعــت اجللســة‬\n    ‫للكتابــة لهيئــة النظــر لتقديــر النفقــة الشــهرية للبنــت مــع مراعــاة راتــب‬\n    ‫والدهــا ويف جلســة أخــرى حضــرت املدعيــة بتعريــف أخيهــا ‪...‬املضبوطــة‬\n    ‫هويتهمــا ســابق ًا وحضــر حلضورهــا وكيــل املدعــى عليــه املضبوطــة‬\n    ‫هويتــه ســابق ًا وقــد عــادت املعاملــة مــن هيئــة النظــر وبرفقهــا القــرار‬\n    ‫املتضمــن تقديرهــم للنفقــة باالشــهر االخيــرة بســتمائة ريــال ســعودي عــن‬\n\n\n‫‪7‬‬\n\f‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعيــة‬     ‫كل شــهر فبنـ ً‬\n‫بإنفاقهــا علــى ابنتهــا بغيــر نيــة الرجــوع علــى والــد الفتــاة اال يف شــهر‬\n‫جمــادي الثانيــة مــن عــام ‪1432‬ه ـ حيــث انتقلــت الفتــاة لبيــت والدهــا‬\n‫يف الشــهر الــذي يليــه وملــا قــرره الفقهــاء مــن ان نفقــة االقــارب مــن أبــاء‬\n‫وأبنــاء وغيرهــم تســقط اذا انفــق غيــر مــن جتــب عليــه النفقــة عليهــم‬\n‫بغيــر نيــة الرجــوع جــاء يف كشــاف القنــاع ‪ ( : 161 / 13‬ولــو امتنــع زوج‬\n‫أو قريــب مــن نفقــة واجبــة بــأن تطلــب منــه النفقــة فيمتنــع فقــام بهــا غيــره‬\n‫رجــع عليــه منفــق بنيــة الرجــوع ) أ‪.‬ه ـ فقــد حكمــت بإلــزام املدعــى‬\n‫عليــه أصالــة ‪ ...‬أن يدفــع للمدعيــة مبلغ ـ ًا وقــدره ســتمائة ريــال ســعودي‬\n‫بهــذا حكمــت وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة عــدم‬\n‫قناعتهــا باحلكــم واســتعدت بتقــدمي الئحــة اعتراضيــة وجــرى افهامهــا‬\n‫باســتالم نســخة احلكــم يف هــذا اليــوم وتقــدمي الئحتهــا يف مــدة أقصاهــا‬\n‫ثالثــون يوم ـ ًا تبــدأ يف هــذا اليــوم وان حقهــا يف االعتــراض يســقط اذا‬\n‫انتهــت املــدة ولــم تتقــدم بالئحتهــا االعتراضيــة كمــا قــرر املدعــى عليــه‬\n‫وكالـ ًة القناعــة باحلكــم وذلــك بعــد أن مت التأكــد مــن وكالتــه وأنهــا‬\n‫تخولــه قبــول االحــكام وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/10‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف برقــم ‪ 34537146‬وتاريــخ‬\n‫‪1434/04/21‬ه ـ برفقهــا القــرار الصــادر مــن دائــرة األحوال الشــخصية‬\n‫برقم ‪ 34183460‬وتاريخ ‪1434/04/09‬هـ ونص احلاجة منه‪( :‬وبدراسة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة والالئحــة االعتراضيــة لوحــظ‬\n‫مــا يلــي ‪ :‬وجــد يف الالئحــة االعتراضيــة مــا يلفــت النظــر وذلــك يف‬\n\n\n                                                                                         ‫‪8‬‬\n\f    ‫الفقــرة األولــى والثالثــة فعلــى فضيلتــه اإلطــاع علــى مــا ذكــر بالالئحــة‬\n    ‫وإعــادة النظــر يف حكمــه فلمالحظــة مــا ذكــر وإحلــاق مــا يســتجد‬\n    ‫بالضبــط وملخصــة الصــك وســجله واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬دائــرة األحــوال الشــخصية واألوقــاف‬\n    ‫والوصايــا والقصــار وبيــوت املــال ‪ .‬قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n    ‫( لــه وجهــة نظــر ) قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n    ‫‪...‬ختمــه وتوقيعــه ) فأجيــب أصحــاب الفضيلــة عمــا الحظــوه بأنــي وبعــد‬\n    ‫مراجعــة مــا كتــب يف الالئحــة االعتراضيــة مــرة أخــرى وخاصــة الفقــرة‬\n    ‫األولــى والثالثــة منهــا لــم أجــد مــا يؤثــر فيمــا حكمــت لكونــي ناقشــت‬\n    ‫املدعيــة يف أثنــاء اجللســة التــي أخــذت فيهــا إقرارهــا بأنهــا انفقــت بغيــر‬\n    ‫نيــة الرجــوع وشــرحت لهــا املــراد عــدة مــرات ولــم أدون إقرارهــا إال بعــد‬\n    ‫فهمهــا التــام للمــراد كمــا أن إقامتهــا دعــوى ســابقة ال يلــزم منــه أن‬\n    ‫إنفاقهــا كان بنيــة الرجــوع فقــد يتقــدم الشــخص بدعــوى ويتركهــا‬\n    ‫وينــوي التبــرع بعــد ذلــك فيمــا انفــق لــذا فإنــي أفيــد أصحــاب الفضيلــة‬\n    ‫ـاق علــى مــا حكمــت بــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬  ‫بأنــي بـ ٍ‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/05/25‬ه ـ ‪.‬‬\n    ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n    ‫فلــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بنجــران والقائــم بعمــل املكتــب‬\n    ‫القضائــي الســادس فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n    ‫مبنطقــة عســير برقــم ‪ 341428648‬وتاريــخ ‪1434/08/2‬ه ـ برفقهــا‬\n    ‫القــرار الصــادر مــن دائــرة األحــوال الشــخصية برقــم ‪ 34277428‬وتاريخ‬\n    ‫‪1434/07/24‬ه ـ ونــص احلاجــة منــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطه‬\n    ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط‬\n\n\n‫‪9‬‬\n\f‫وصــك احلكــم بنــاء علــى قــرار الدائــرة رقــم ‪ 34183460‬وتاريــخ‬\n‫‪1434/4/9‬ه ـ تقــررت املوافقــة علــى احلكــم باألكثريــة بعــد اإلجــراء‬\n‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n‫املــال ‪ .‬قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف‪ ...‬ختمــه‬\n‫وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه وحتــى ال يخفــى جــرى حتريــره‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه وســلم‪.‬‬\n                                               ‫حــرر يف ‪ 1434/08/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية و األوقــاف والوصايــا والقصــار‬\n‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة لهــذه احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة بنجــران‬\n‫برقــم ‪ 341013690‬وتاريــخ ‪1434/6/4‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة الشيخ‪....../‬املســجل برقــم‪ 347261‬وتاريــخ ‪1434/1/10‬ه ـ‬\n‫اخلاصــة بدعــوى ‪...‬ضــد ‪...‬بشــأن نفقــة علــى الصفــة املوضحــة بالصــك‬\n‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون بباطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n‫وأحلقــه بالضبــط وصــك احلكــم بنــاء على قرار الدائــرة رقم ‪34183460‬‬\n‫وتاريــخ ‪1434/4/9‬ه ـ تقــررت املوافقــة علــى احلكــم باألكثريــة بعــد‬\n‫اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمد و آله وصحبه‬\n‫وســلم ‪.‬دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n                                                                          ‫املــال‪.‬‬\n\n\n\n                                                                                     ‫‪10‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":5,"source_page_end":10,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7cb949488b3c7f86b53952f64395dacbc6daedc02c27cf758dfc0e8cced794ab","normalized_text_hash":"99bc4229892fc9cd1f2d4140e039e5a38408070c995e9e0045d71c8ea1b9de37","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p5-347261"},{"id":"b14d6503-3cb3-527d-8022-4e203413b1a5","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -طلب نفقة األبناء عن املدة املاضية -من جتاوز من األبناء سن البلوغ فليس لوالدته املطالبه بنفقته إال بوكالة عنه -يشترط نية الرجوع ملن قام بالنفقة الواجبة على غيره.","document_number":"3377548","case_number":"32279617","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/2/13","year":"1434","subject":"نفقة -طلب نفقة األبناء عن املدة املاضية -من جتاوز من األبناء سن البلوغ فليس لوالدته املطالبه بنفقته إال بوكالة عنه -يشترط نية الرجوع ملن قام بالنفقة الواجبة على غيره.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/2/13 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3377548 :‬‬\n                        ‫َر ْق ُم الدعوى‪32279617 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 3450961‬تاريخه‪1434/3/20 :‬هـ‬\n\n\n\n     ‫نفقــة‪ -‬طلــب نفقــة األبنــاء عــن املــدة املاضيــة‪ -‬مــن جتــاوز مــن األبنــاء‬\n     ‫ســن البلــوغ فليــس لوالدتــه املطالبــه بنفقتــه إال بوكالة عنه‪ -‬يشــترط‬\n                      ‫نيــة الرجــوع ملــن قــام بالنفقــة الواجبــة علــى غيــره‪.‬‬\n\n\n\n\n     ‫قــال يف كشــاف القنــاع (ولــو امتنــع زوج أو قريــب مــن نفقــه واجبــة بــأن‬\n     ‫تطلــب منــه النفقــة فيمتنــع فقــام بهــا غيــره رجــع عليــه منفــق بنيــة‬\n                               ‫الرجــوع ألنــه قــام عنــه بواجــب كقضــاء دينــه)‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــة للمدعــى عليــه‬\n     ‫وأجنبــت منــه ثالثــة أبنــاء األول مولــود يف ‪1461/8/10‬ه ـ والثانــي مولــود‬\n     ‫يف ‪1491/10/2‬ه ـ والثالــث مولــود يف ‪1422/11/23‬هــ‪ ،‬وقــد جلــس‬\n     ‫االبــن األول والثانــي عنــد موكلتــه ســبعة أشــهر وعشــرة أيــام ولــم ينفــق‬\n     ‫املدعــى عليــه عليهمــا طيلــة هــذه الفتــرة‪ ،‬طلــب املدعــي وكالــة إلــزام‬\n     ‫املدعــى عليــه بدفــع نفقــة االبنــن املذكوريــن خــال فتــرة جلوســهما‬\n     ‫عنــد والدتهمــا وقدرهــا ألــف ريــال شــهري ًا لــكل واحــد منهمــا‪ ،‬أقــر‬\n     ‫املدعــى عليــه مبــا جــاء يف الدعــوى وذكــر بأنــه اتصــل بخــال األبنــاء‬\n     ‫ليقــوم بإحضارهــم إال أنــه قــال الدخــل لــي ثــم ذهــب إلــى الشــرطة يطلــب‬\n\n‫‪11‬‬\n\f‫تســليمهم ولــم يجــد جــدوى وكانــت والدتهــم تأمرهــم باجللــوس عندهــا‪،‬‬\n‫أنكــر املدعــي وكالــة مــا ذكــره املدعــى عليــه‪ ،‬قــرر املدعــى عليــه‬\n‫أنــه البينــه لديــه وطلــب ميــن املدعيــة أصالــة‪ ،‬حضــرت املدعيــة أصالــة‬\n‫وقــررت أنهــا لــم تامــر ابنائهــا بالبقــاء عندهــا ورفضــت أداء اليمــن‪ ،‬ورد‬\n‫قــرار هيئــة النظــر املتضمــن تقديــر نفقــة االبنــن املذكوريــن عــن املــدة‬\n‫املذكــورة وروعــي يف ذلــك االلتزامــات املترتبــة علــى والدهمــا وكذلــك‬\n‫روعــي أن االبنــن يدرســان باملرحلــة املتوســطة‪ ،‬صــدر احلكــم علــى‬\n‫املدعــى عليــه بــأن يدفــع للمدعيــة أصالــة نفقــة الســبعة أشــهر وعشــرة‬\n‫أيــام حســبما جــاء يف قــرار هيئــة النظــر‪ ،‬قنعــت املدعيــة باحلكــم ولــم‬\n‫يقنــع املدعــى عليــه‪ ،‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف‬\n‫مبالحظــات أهمهــا أن االبــن األول جتــاوز ســن البلــوغ وليــس لوالدتــه‬\n‫املطالبــة إال بوكالــة عنــه وأيضـ ًا النفقــة املطالــب بهــا عــن مــدة ماضيــة‬\n‫ولــم يســال فضيلتــه ملــاذا لــم تطالــب املدعيــة بالنفقــة يف وقتهــا وينبغــي‬\n‫مراعــاة مــا قــرره أهــل العلــم بشــأن ســقوط نفقــة القريــب مبضــي‬\n‫املدة‪،‬أجــاب فضيلــة القاضــي بــأن االبــن األكبــر وإن جتــاوز ســن البلــوغ‬\n‫إال أن املدعيــة والدتــه تطالــب بنفقــة ماضيــة أنفقتهــا وليســت مســتقبلة‪،‬‬\n‫كمــا جــرى ســؤال املدعيــة ملــاذا لــم تطالــب بالنفقــة مــن حــن حضــور‬\n‫األبنــاء لديهــا فقالــت إن املدعــى عليــه ابــن خالتهــا وكانــت تتحــرج مــن‬\n‫مطالبتــه حتــى عرضــت األمــر علــى والدتــه فقالــت مــن حقــك أن تطالبــي‬\n‫بالنفقــة‪ ،‬وســقوط نفقــة القريــب مبضــي املــدة وذلــك يف حــال عــدم نيــة‬\n‫املنفــق الرجــوع كمــا ذكــر ذلــك يف كشــاف القنــاع‪ ،‬صــدق احلكــم‬\n                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بينبــع‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بينبع‪/‬املســاعد برقــم ‪ 32279617‬وتاريــخ ‪ 1432/07/11‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 32868216‬وتاريــخ ‪ 1432/07/11‬ه ـ ففــي يــوم‬\n     ‫السبت املوافق‪ 1432/08/01‬هـ أفتتحت اجللسة الساعة ‪ 11 : 01‬وفيها‬\n     ‫حضــر املدعــي وكالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪...‬الوكيــل الشــرعي عــن املدعيــه ‪...‬مبوجــب الوكالــة رقــم ‪32159298‬‬\n     ‫وتاريــخ ‪1432/07/09‬ه ـ الصــادرة مــن كتابــة عــدل محافظــة ينبــع‬\n     ‫وحضــر حلضــوره املدعــى عليــه ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪...‬وقــرر املدعــي قائــا ان موكلتــي ســبق وان تزوجــت‬\n     ‫املدعــى عليــه واجنبــت منــه ثالثــه ابنــاء ‪...‬املولــود يف ‪1416/08/10‬هـ و‪...‬‬\n     ‫املولــود يف ‪1419/10/02‬ه ـ و‪ ...‬املولــود يف ‪1422/11/23‬ه ـ وقــد جلــس‬\n     ‫‪...‬و‪ ...‬عنــد موكلتــي مــن تاريــخ ‪1431/12/11‬هـ حتى ‪1432/07/20‬هـ‬\n     ‫ولــم ينفــق املدعــى عليــه عليهمــا طيلــة هــذه الفتــرة اطلــب احلكــم عليــه‬\n     ‫والزامــه بدفــع نفقتهمــا خــال فتــرة جلوســهما لــدى والدتهــم وقدرهــا‬\n     ‫الــف ريــال لــكل واحــد منهمــا شــهري ًا هــذه دعــواي وبســؤال املدعــى‬\n     ‫عليــه قــال ماذكــره املدعــي مــن زواجــي مبوكلتــه واجنبــت منــي ثالثــه‬\n     ‫ابنــاء ثــم طلقتهــا فصحيــح وامــا ماذكــر مــن جلــوس ابنــي ‪ ....‬و‪...‬عنــد‬\n     ‫والدتهــم مــن تاريــخ ‪1431/12/11‬ه ـ وحتــي تاريــخ ‪1432/07/20‬ه ـ‬\n     ‫فصحيــح ايض ـ ًا وقــد اتصلــت بخــال االبنــاء ‪...‬ليقــوم بإحضاراالبنــاء اال‬\n     ‫انــه قــال الدخــل لــي بهــم ثــم ذهبــت الــى الشــرطه لطلــب تســليمهم ولــم‬\n\n‫‪13‬‬\n\f‫أجــد جــدوى وكانــت والدتهــم تأمرهــم باجللــوس عندهــا هكــذا أجــاب‬\n‫فســألت املدعــي هــل جلوســهم يف بيــت والدتهــم كان بطلــب منهــا فقــال‬\n‫ال هكــذا اجــاب وحيــث تطلــب االمــر الكتابــه لهيئــة النظــر لتقديــر‬\n‫النفقــه لــكل واحــد منهمــا لــذا رفعــت اجللســة حلــن ورود االجابــه احلمــد‬\n‫هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبع‪/‬املســاعد برقــم ‪ 32279617‬وتاريخ‪1432/11/7‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32868216‬وتاريخ‪1432/7/11‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق ‪1432/11/18‬ه ـ أفتتحــت اجللســة الســاعة ‪ 11 : 57‬وفيهــا‬\n‫حضــر املدعــي وكالــة واملدعــى عليــه وجــرى ســؤال املدعــى عليــه‬\n‫هــل لديــك بينــة علــى أن والدتهــم تأمرهــم بالبقــاء عندهــا فقــال البينــه‬\n‫عنــدي وأطلــب ميــن والدتهــم وإلحضــار األم ألداء اليمــن رفعــت اجللســة‬\n‫ويف يــوم االربعــاء املوافــق ‪1432/11/21‬ه ـ أفتتحــت اجللســة الســاعة‬\n‫‪ 12 : 00‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه كمــا حضــرت‬\n‫املدعيــه اصالــة ‪...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫وبســؤالها عمــا ذكــره املدعــى عليــه مــن انهــا كانــت تأمرهــم بالبقــاء‬\n‫لديهــا اجابــت قائلــه ماذكــره املدعــى عليــه مــن اننــي آمرهــم بالبقــاء‬\n‫عنــدي غيــر صحيــح وبعــرض ذلــك علــى املدعــى عليــه قــال ماذكرتــه‬\n‫غيــر صحيــح وأطلــب ميينهــا وبعــرض ذلــك علــى املدعيــه رفضــت ذلــك‬\n‫وللتأمــل رفعــت اجللســة ويف يــوم االربعــاء املوافــق ‪1433/01/12‬ه ـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر املدعــي واملدعــى عليــه‬\n‫وقــد رأيــت الكتابــه للجنــة االصــاح حملاولــة االصــاح بــن الطرفــن‬\n‫وتخويفهمــا بــاهلل وحلــن ورود االفــادة رفعــت اجللســة ويف يــوم االثنــن‬\n\n\n                                                                                   ‫‪14‬‬\n\f     ‫املوافــق ‪1433/02/08‬ه ـ أفتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا‬\n     ‫حضــر املدعــي واملدعــى عليــه وجــرى االطــاع علــى قــرار هيئــة النظــر‬\n     ‫رقــم ‪ 66‬يف ‪1432/9/13‬ه ـ املرفــق باملعاملــة وهــذا نصــه ( احلمــد هلل‬\n     ‫وحــده وبعــد ويف يــوم الســبت املوافــق ‪1432/09/13‬ه ـ ويف متــام الســاعة‬\n     ‫الواحــدة واربعــون دقيقــه وبنــاء علــى خطــاب فضيلــة القاضــي ‪...‬رقــم‬\n     ‫‪ 321009019‬يف ‪1432/8/8‬ه ـ والــذي يطلــب فيــه حتديــد نفقــه وذلــك‬\n     ‫بنــاء علــى دعــوى املــرأة ‪ ...‬ضــد ‪...‬وذلــك البنيهــا ‪...‬و‪ ...‬عليــه فقــد حضــر‬\n     ‫املدعــى عليــه ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ولــم‬\n     ‫يحضــر الوكيــل الشــرعي للمدعيــة فقــد جــرى ســؤال املدعــى عليــه عــن‬\n     ‫راتبــه فأفــاد ان صــايف الراتــب هــو ســبعة اآلف وتســعمائة ريــال وأنــه‬\n     ‫يعــول والديــه ولديــه زوجــة وثالثــة أبنــاء آخريــن خــاف االثنــن محــل‬\n     ‫الدعــوى وبالنظــر يف حــال والــد االبنــن فقــد تقــرر هيئــة النظــر نفقــه‬\n     ‫شــهريه لــكل واحــد منهمــا ســبعمائة وخمســون ريــاال وأمــا بخصــوص‬\n     ‫شــهر ذو القعــده لعــام ‪1431‬ه ـ فيكــون مقــدار النفقــة الــف ريــال لــكل‬\n     ‫ابــن وقــد روعــي يف ذلــك اإللتزامــات املترتبــة علــى والــده كمــا روعــي‬\n     ‫أن االبنــن يدرســان باملرحلــة املتوســطه وبــاهلل التوفيــق وصلــي اهلل علــى‬\n     ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1432/9/13‬ه ـ ) عضــو‬\n     ‫هيئــة النظــر ‪ ...‬توقيعــه و ‪...‬توقيعــه املدعــى عليــه ‪...‬توقيعــه رئيــس قســم‬\n     ‫اخلبــراء ‪...‬توقيعــه وبنــاء علــى ماســبق مــن الدعــوى واالجابــه وملــا جــاء‬\n     ‫يف قــرار هيئــة النظــر مــن ان النفقــة الشــهريه لــكل واحــد مــن االبنــن‬\n     ‫ســبعمائه وخمســون ريــاال ومبــا ان االبنــن جلســا عنــد والدتهــم مــدة‬\n     ‫ســبعة اشــهر وتســعة ايــام لــذا فقــد حكمــت بــأن يدفــع املدعــى عليــه‬\n     ‫للمدعيــه اصالــة مبلــغ عشــرة اآلف وتســعمائه وخمســن ريــاال كاملــة‬\n\n\n‫‪15‬‬\n\f‫حــاال هــذا ماظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــي قــرر‬\n‫قناعتــه بــه وقــرر املدعــى عليــه اعتراضــه بالئحــه اعتراضيــه فأفهــم بــأن‬\n‫لــه مــده ثالثــن يومــا تبــدا مــن هــذا اليــوم فــإذا لــم يتقــدم خاللهــا بشــي‬\n‫فــان احلكــم يكــون مكتســبا للقطعيــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/02/8‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1433/08/14‬ه ـ‬\n‫افتتحــت اجللســة الســاعة احلاديــة عشــرة صباحــا وفيهــا حضــرت‬\n‫املدعيــة ‪ ...‬واملعــرف بهــا مــن قبــل أخيهــا ‪...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ ...‬واملدعــى عليــه ‪ ...‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باخلطــاب رقــم ‪ 33836283‬يف ‪1433/5/15‬ه ـ مالحظـ ًا عليهــا بالقــرار‬\n‫رقــم ‪ 33237413‬يف ‪1433/5/9‬ه ـ وهــذا نــص احلاجــة منــه ( وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر باألكثريــة إعادتهــا‬\n‫لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬ســمع فضيلتــه دعــوى ‪ ....‬عــن‬\n‫طريــق وكيلهــا تطالــب بنفقــة ابنيهــا ‪...‬و‪ ...‬تبــن أن ‪ ...‬قــد جتــاوز ســن‬\n‫البلــوغ وليــس لوالدتــه املطالبــة إال بوكالــة منــه ‪ -2 .‬النفقــة املطالــب‬\n‫بهــا عــن مــدة ماضيــة ولــم يســأل فضيلتــه ملــاذا لــم تطالــب بالنفقــة‬\n‫يف وقتهــا يومــا بيــوم أو شــهرا بشــهر حتــى اجتمعــت كل هــذه املــدة‬\n‫وينبغــي مراعــاة مــا قــرره أهــل العلــم بشــأن ســقوط نفقــة القريــب مبضــي‬\n‫املــدة ‪ -3 .‬ورد يف الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه‬\n‫مــا يســتحق النظــر واملناقشــة ومــن ذلــك وجــود دعــوى ســابقة وصلــح‬\n‫بشــأن احلضانــة والزيــارة ومــا ذكــره مــن حتريــض املدعيــة وابنهــا ‪..‬‬\n‫الــخ كمــا أنــه لــم يتــم اثبــات اســتالم الالئحــة االعتراضيــة بالضبــط‬\n‫واإلجابــة عليهــا حســب التعليمــات واهلل املوفــق وصلــى اهلل وســلم علــى‬\n\n\n                                                                                         ‫‪16‬‬\n\f     ‫نبينــا محمــد قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف د‪....‬‬\n     ‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه موافــق علــى احلكــم)‬\n     ‫ا ه ـ وعليــه أجيــب أصحــاب الفضيلــة عــن مالحظتهــم األولــى بــأن ‪...‬‬\n     ‫قــد جتــاوز ســن البلــوغ وليــس لوالدتــه املطالبــة إال بوكالــة منــه بــأن‬\n     ‫املدعيــة تطالــب بنفقــة ماضيــة وليســت مســتقبلة وعليــه أجيــب أصحــاب‬\n     ‫الفضيلــة علــى مالحظاتهــم الثانيــة بأنــه جــرى ســؤال املدعيــة ملــاذا لــم‬\n     ‫تطالــب بنفقــة ابنيهــا فقالــت أنــه بينــي وبــن املدعــى عليــه قرابــة وهــو‬\n     ‫ابــن خالتــي وكنــت أحتــرج مــن ذلــك وقــد عرضــت ذلــك علــى والــدة‬\n     ‫املدعــى عليــه فقالــت مــن حقــك أن تطالبــي بالنفقــة فتقدمــت بذلــك‬\n     ‫هكــذا أجابــت وأمــا مــا ذكــره أصحــاب الفضيلــة مــن ســقوط نفقــة‬\n     ‫القريــب مبضــي املــدة فإنــه يف حــال عــدم نيــة املنفــق بالرجــوع علــى مــن‬\n     ‫أنفــق قــال يف كشــاف القنــاع (ولــو امتنــع زوج أو قريــب مــن نفقــة واجبــة‬\n     ‫بــأن تطلــب منــه) النفقــة (فيمتنــع) فقــام بهــا غيــره (رجــع عليــه منفــق‬\n     ‫بنيــة الرجــوع ) إلنــه قــام عنــه بواجــب كقضــاء دينــة) وأمــا مالحظاتهــم‬\n     ‫الثالثــة فــإن احلضانــة لــأب والزيــارة لــأم حســب الصــك الصــادر منــي‬\n     ‫برقــم ‪ 4/28‬يف ‪1431/7/24‬ه ـ وأمــا حتريــض املدعيــة أبنائهــا علــى‬\n     ‫والدهــم فســألتها عــن ذلــك فقالــت إننــي لــم أحرضهــم علــى والدهــم‬\n     ‫وأبنائــي يأتــون إلــي وقــد أعدتهــم إلــى والدهــم أكثــر مــن مــرة ولكــن‬\n     ‫يرفضــون البقــاء عنــد والدهــم إلن زوجتــه تضربهــم وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــال إن زوجتــي ال تضربهــم ولكــن تزجرهــم لعــدم أداء‬\n     ‫واجباتهــم املدرســية وبنــاء علــى مــا ســبق لــم يظهــر لــي ســوى مــا حكمــت‬\n     ‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪ 1433/08/14‬ه ـ‬\n\n\n‫‪17‬‬\n\f‫ويف يــوم الثالثــاء املوافــق‪ 1433/10/24‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪09:00‬وفيهــا حضــر املدعــي ‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم‪...‬‬\n‫الوكيــل الشــرعي عــن اختــه ‪ ...‬مبوجــب الوكالــة رقــم ‪33434273‬‬\n‫وتاريــخ ‪1433/10/22‬ه ـ والصــادرة مــن كتابــة عــدل ينبــع واملخــول لــه‬\n‫فيهــا املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ ...‬كمــا حضــر حلضــوره أبنــاء املتداعــن وهــم‬\n‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬واملضــاف بســجل‬\n‫والــده ‪ ...‬ســعودي اجلنســية بالســجل رقــم ‪ ...‬واملضــاف بســجل والــده و‪...‬‬\n‫ســعودي بالســجل رقــم ‪...‬واملضــاف بســجل والــده وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف مالحظــا عليهــا بالقــرار رقــم ‪33400757‬‬\n‫وتاريــخ ‪1433/09/03‬ه ـ وهــذا نــص احلاجــة منــه ( وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا‬\n‫لفضيلــة حاكمهــا ملالحظــة ‪ :‬ان إجابــة فضيلتــه غيــر كافيــه فالصــك‬\n‫الســابق محكــوم فيــه باحلضانــة لــأب والزيــارة لــأم فكيــف تطالــب‬\n‫بالنفقــه واحلضانــة لــأب كمــا انهــا لــم تطالــب بالنفقــة اال بتاريــخ‬\n‫‪1432/07/11‬ه ـ حســب صحيفــة الدعــوى فكيــف يحكــم لهــا‬\n‫قبــل هــذا التاريــخ وليــس لهــا حــق اال يف الزيــارة واهلل املوفــق ) قــاض‬\n‫اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي ‪ ...‬ســبقت موافقتــي علــى احلكــم‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه وعليــه أجيــب أصحــاب‬\n‫الفضيلــة عــن مالحظتهــم األولــى بأنــه جــرى ســؤال األبنــاء احلاضريــن‬\n‫ملــاذا لــم جتلســوا يف بيــت والدكــم فأجابــوا بــأن ذهبنــا لبيــت والدنــا‬\n‫اكثــر مــن مــرة وطردنــا مــن البيــت وزوجــة والدنــا تضربنــا فلهــذا‬\n‫ذهبنــا لبيــت والدتنــا هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n\n\n                                                                                  ‫‪18‬‬\n\f     ‫قــال اننــي لــم اضربهــم وقــد ذهبــت الــى الشــرطة الجــل اســتالم ابنائــي‬\n     ‫فرفــض خالهــم ‪ ...‬حضــور والدتهــم للشــرطة الجــل تســليم االبنــاء الــي‬\n     ‫وبعــد ثالثــه ايــام تقدمــت املدعيــه بشــكوى لــدى شــرطة البلــد بأننــي‬\n     ‫مســيئ لالبنــاء واننــي اضربهــم كمــا أضــاف املدعــي بــأن والدهــم قــد‬\n     ‫هــدد ابنــه ‪...‬بالســاح وقــال لــي واهلل ألجيبــك هكــذا قــال وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه قــال ماذكــره املدعــي مــن تهديــد ابنــي بالســاح غيــر‬\n     ‫صحيــح وامــا ماذكــر مــن قولــي بأنــي اجيبــك صحيــح وامــا مالحظتهــم‬\n     ‫الثانيــة فانــه ســبق اجلــواب عنهــا ولهــذا لــم يظهــر لــي ســوى ماحكمــت‬\n     ‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                    ‫وســلم ‪ .‬حــرر يف ‪ 1433/10/24‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n     ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n     ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس محكمــة‬\n     ‫ينبــع العامــة املســاعد رقــم ‪ 331721171‬وتاريــخ ‪1434/ 1/12‬ه ـ املرفق‬\n     ‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪... /‬القاضــي باحملكمــة العامــة‬\n     ‫بينبــع برقــم ‪ 3377548‬وتاريــخ ‪1433/ 2/13‬ه ـ املتضمــن دعــوى املــرأة‬\n     ‫‪...‬ضــد ‪ ...‬يف نفقــة أوالدهــا ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجابــه علــى القــرار ‪،‬‬\n     ‫واهلل املوفــق ‪ .‬وصلــى اهلل عل ـ ـ ــى نبينــا محمــد وعلـ ـ ــى آلـ ـ ـ ــه وصحب ـ ـ ــه‬\n                                                                                        ‫وســلم‪.‬‬\n\n\n\n\n‫‪19‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":11,"source_page_end":19,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3845ba1e926ba0d8fff56deda372a1bdbed06f2c6b8f4dd9f63811dc73cd3f2d","normalized_text_hash":"6e04f8e1bd153f995047f0528f168be7ee54d81c0d21970f5b6c26e83bd99617","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p11-3377548"},{"id":"58dafee4-b703-56a9-ba80-d858e81a5690","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة وأوالد -املطالبة بالنفقة املاضية واملستقبلية -الدفع بعدم استحقاق الزوجة للنفقة لنشوزها -التنازل عن النفقة بشرط الطاق واحلضانة -تقدير النفقة من قبل قسم اخلبراء -النفقة ال تسقط بالتقادم -حلف الزوجة اليمن على عدم نفقة الزوج -النفقة بنية الرجوع -اإللزام بالنفقة املاضية","document_number":"3396987","case_number":"3326768","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/28","year":"1434","subject":"نفقة -نفقة زوجة وأوالد -املطالبة بالنفقة املاضية واملستقبلية -الدفع بعدم استحقاق الزوجة للنفقة لنشوزها -التنازل عن النفقة بشرط الطاق واحلضانة -تقدير النفقة من قبل قسم اخلبراء -النفقة ال تسقط بالتقادم -حلف الزوجة اليمن على عدم نفقة الزوج -النفقة بنية الرجوع -اإللزام بالنفقة املاضية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1433/8/28 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪3396987 :‬‬\n                     ‫َر ْق ُم الدعوى‪3326768 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 345811‬تاريخه‪1434/1/7 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة وأوالد ‪ -‬املطالبــة بالنفقــة املاضيــة واملســتقبلية‬\n‫‪ -‬الدفــع بعــدم اســتحقاق الزوجــة للنفقــة لنشــوزها ‪ -‬التنــازل عــن‬\n‫النفقــة بشــرط الطــاق واحلضانــة ‪ -‬تقديــر النفقــة مــن قبــل قســم‬\n‫اخلبــراء ‪ -‬النفقــة ال تســقط بالتقــادم ‪ -‬حلــف الزوجــة اليمــن علــى‬\n‫عــدم نفقــة الــزوج ‪ -‬النفقــة بنيــة الرجــوع ‪ -‬اإللــزام بالنفقــة املاضيــة‬\n                                                              ‫واملســتقبلية ‪.‬‬\n\n\n\n\n                                             ‫‪ -1‬قاعدة ‪ :‬من ترك دعواه ترك‬\n                                                  ‫‪ -2‬قاعدة ‪ :‬العادة محكمة‬\n                               ‫‪ -3‬قاعدة ‪ :‬املعروف عرف ًا كاملشروط شرط ًا ‪.‬‬\n‫‪ -4‬قــال شــيخ اإلســام يف الفتــاوى (‪( : )134/34‬إذا كان االبــن يف‬\n‫حضانــة أمــه فأنفقــت عليــه تنــوى بذلــك الرجــوع علــى األب فلهــا أن‬\n‫ترجــع علــى األب يف أظهــر قولــي العلمــاء وهــو مذهــب مالــك واحمــد‬\n                          ‫يف ظاهــر مذهبــه الــذي عليــه قدمــاء أصاحبــه)‪.‬‬\n‫‪ -5‬قــال ابــن قدامــة يف الــكايف (‪( : )97/5‬وإذا وجــد اليمــن املوجــب‬\n‫للنفقــة فلــم ينفــق حتــى مضــت مــدة صــارت النفقــة دينـ ًا يف ذمته ســواء‬\n‫تركهــا لعــذر أو غيــره حلديــث عمــر رضــي اهلل عنــه وألنــه مــال يجــب‬\n   ‫علــى ســبيل البــدل يف عقــد معاوضــة فلــم يســقط مبضــي الزمــن) ‪.‬‬\n\n                                                                                  ‫‪20‬‬\n\f     ‫‪ -6‬قــال إبراهيــم بــن ضويــان يف منــار الســبيل (‪( : )1046/3‬مــن غــاب‬\n     ‫عــن زوجتــه مــدة ولــم ينفــق عليهــا لزمتــه نفقــة الزمــن املاضــي) ‪ .‬وقــال‬\n     ‫يف موضــع آخــر (‪( : )1052/2‬حيــث امتنــع منهــا الــزوج أو قريــب وأنفــق‬\n             ‫أجنبــي بنيــة الرجــوع رجــع ألنــه قــام عنــه بواجــب قضــاء دينــه)‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة علــى زوجهــا املدعــى عليــه بأنهــا عنــد أهلهــا مــن تاريــخ‬\n     ‫‪1427/6/30‬ه ـ وإنهــا أجنبــت بنتـ ًا بتاريــخ ‪1427/7/27‬ه ـ وأن املدعــى‬\n     ‫عليــه لــم ينفــق عليهــا وال علــى ابنتهــا طيلــة هــذه املــدة‪ ،‬طلبــت املدعيــة‬\n     ‫إلــزام املدعــى عليــه بدفــع نفقتهــا ونفقــة ابنتهــا عن املــدة املاضية وحتديد‬\n     ‫نفقــة مســتقبلية‪ ،‬صــادق املدعــى عليــه علــى الدعــوى ودفــع بــأن املدعيــة‬\n     ‫خرجــت مــن البيــت بغيــر إذنــه‪ ،‬قــرر املدعــى عليــه بأنــه دفــع البنتــه عنــد‬\n     ‫والدتهــا ألف ـ ًا وخمســمائة ريــال‪ ،‬قــرر املدعــى عليــه بأنــه ال مانــع لديــه‬\n     ‫مــن النفقــة علــى ابنتــه دون املدعيــة‪ ،‬ذكــرت املدعيــة بأنهــا لــم تخــرج‬\n     ‫مــن بيــت املدعــى عليــه بغيــر إذنــه وهــو الــذي أوصلهــا لبيــت أهلهــا‪ ،‬مت‬\n     ‫عــرض الصلــح بــن الطرفــن فتعــذر ذلــك‪ ،‬رأت جلنــة الصلــح حتديــد‬\n     ‫نفقــة البنــت خمســمائة ريــال شــهري ًا عــن النفقــة املاضيــة واملســتقبلية‬\n     ‫وتنازلــت املدعيــة عــن نفقتهــا حســب احملضــر املرفــق‪ ،‬قــررت املدعيــة ان‬\n     ‫تنازلهــا عــن نفقتهــا مشــروط بطالقهــا وحضانتهــا البنتهــا وأن املدعــى‬\n     ‫عليــه رفــض ذلــك‪ ،‬قــرر املدعــى عليــه عــدم موافقتــه علــى مــا ذكرتــه‬\n     ‫املدعيــة مــن تنازلهــا عــن النفقــة بشــرط الطــاق واحلضانــة‪ ،‬جــرى تقدير‬\n     ‫نفقــة املدعيــة مــن قبــل قســم اخلبــراء‪ ،‬قــررت املدعيــة ان مجمــوع مــا‬\n     ‫اســتلمته مــن املدعــى عليــه ثالثــة اآلف ريــال‪ ،‬قــرر املدعــى عليــه انــه ال‬\n‫‪21‬‬\n\f‫بينــة لديــه علــى أن املدعيــة هــي التــي خرجــت مــن بيتــه بغيــر إذنــه‪ ،‬جــرى‬\n‫إفهــام املدعــى عليــه بــأن لــه ميــن املدعيــة علــى أنهــا لــم تخــرج بغيــر إذنــه‬\n‫وأنهــا لــم ترفــض الرجــوع إليــه إال بتاريــخ ‪1433/6/16‬ه ـ وكانــت قبــل‬\n‫ذلــك تريــد الرجــوع وأنهــا كانــت تنــوى الرجــوع عليــه بالنفقــة‪ ،‬فقــرر‬\n‫انــه ال يطلــب ميينهــا‪ ،‬يف جلســة أخــرى حضــرت املدعيــة برفقــة والدهــا‬\n‫وحلفــت اليمــن املطلوبــة‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n‫نفقــة املدعيــة مــن تاريــخ ‪1427/6/30‬ه ـ حتــى تاريــخ ‪1433/6/16‬هــ‪،‬‬\n‫إلــزام املدعــى عليــه بدفــع نفقــة ابنتــه عــن املــدة املاضيــة ونفقــة مســتقبلية‬\n‫شــهري ًا قدرهــا خمســمائة ريــال‪ ،‬قنعــت املدعيــة باحلكــم‪ ،‬قــدم املدعــى‬\n    ‫عليــه الئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائف‪/‬املكلــف برقــم ‪ 3326768‬وتاريــخ ‪ 1433/01/10‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3366040‬وتاريــخ ‪ 1433/01/10‬ه ـ واملتعلقــة‬\n‫بدعــوى ‪ ...‬ضــد ‪ ...‬يف دعــوى بنفقــة ويف يــوم األحــد ‪1433/03/27‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة ‪09 : 11‬صباحــا وفيهــا حضــرت املــرأة‬\n‫املدعيــة ‪ ...‬حتمــل رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪ ...‬يحمــل بطاقــة‬\n‫الهويــة الوطنيــة رقــم ‪ ...‬وحضــر حلضورهــا املدعــى عليــه ‪ ...‬يحمــل بطاقــة‬\n‫الهويــة الوطنيــة رقــم ‪ ...‬وادعــت املدعيــة قائلــة يف دعواهــا ان املدعــى‬\n‫عليــه هــذا احلاضــر زوجــي تزوجنــي بالعقــد الصحيــح ودخــل بــي يف‬\n‫‪1425/9/25‬ه ـ واجنبــت لــه علــى فــراش الزوجيــة االبنــة ‪ ...‬وهــي مــن‬\n                                                                                            ‫‪22‬‬\n\f     ‫مواليــد‪ .../7/27‬ومــن تاريــخ ‪1427/6/30‬ه ـ وحتــى هــذا اليــوم وانــا‬\n     ‫عنــد أهلــي وحتــت حضانتــي ابنتــي ‪...‬ولــم ينفــق علــي املدعــى عليــه وال‬\n     ‫علــى ابنتــه طيلــة هــذه املــدة لــذا اطلــب الــزام املدعــى عليــه بتقديــر نفقــه‬\n     ‫ماضيــة ومســتقبلية لــي والبنتــه هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n     ‫دعــوى املدعيــة أجــاب قائــا كل مــا ذكرتــه املــرأة املدعيــة مــن أنهــا‬\n     ‫زوجتــي تزوجتهــا بالعقــد الصحيــح ودخلــت بهــا يف ‪1425/9/25‬ه ـ‬\n     ‫واجنبــت لــي علــى فــراش الزوجيــة االبنــة ‪ ...‬وهــي مــن مواليــد ‪.../7/27‬‬\n     ‫فهــذا صحيــح وقــد خرجــت املدعيــة مــن منزلــي وبــدون اذنــي يف‬\n     ‫‪1427/6/30‬ه ـ وقــد دفعــت البنتــي عنــد والدتهــا مبلــغ الــف وخمســمائة‬\n     ‫ريــال وال مانــع لــدي مــن االنفــاق علــى ابنتــي وتقديــر النفقــة الشــرعية‬\n     ‫أمــا بالنســبة للمدعيــة فــا نفقــة لهــا عنــدي هكــذا أجــاب وبعــرض ذلــك‬\n     ‫علــى املــرأة املدعيــة قالــت قــد دفــع لــي مبلــغ الــف ريــال فقــط عنــد والدة‬\n     ‫ابنتــي ولــم أخــرج مــن منزلــه بــدون إذنــه وهــو الــذي قــام بإيصالــي الــى‬\n     ‫أهلــي هكــذا قــررت وبــن أخــذ ورد ومحاولــة االصــاح بــن الطرفــن‬\n     ‫إال اننــي لــم أتوصــل الــى نتيجــة فجــرى ســؤال املدعــى عليــه هــل لديــك‬\n     ‫البينــة علــى أنــك ســلمتها مبلــغ ألــف وخمســمائة ريــال وكذلــك البينــة‬\n     ‫أنهــا هــي التــي خرجــت فقــال ال بينــة لــدي اال اهلل عــز وجــل فعليــه فقــد‬\n     ‫مت االتصــال علــى جلنــة االصــاح وقــد مت حتديــد موعــد يف هــذا اليــوم‬\n     ‫واملوعــد يف مكتبنــا يف يــوم الثالثــاء ‪1433/6/17‬ه ـ الســاعة التاســعة‬\n     ‫والنصــف وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/03/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1433/06/17‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪10 : 59‬وفيهــا حضــرت املــرأة املدعيــة ‪...‬‬\n\n\n‫‪23‬‬\n\f‫واملعــرف بهــا مــن قبــل والدهــا ‪ ...‬املدونــة هويتهمــا ســابقا وحضــر‬\n‫حلضورهــا املدعــى عليــه ‪...‬املثبتــة هويتــه ســابقا وقــد عــادت إلينــا املعاملــة‬\n‫من مكتب الصلح بالقرار رقم ‪/135‬ص يف ‪1433/3/28‬هـ واملتضمن‬\n‫مــا نصــه( وبعــرض الصلــح علــى الطرفــن وقــد تعــذر ذلــك وتــرى اللجنــة‬\n‫أن تكــون نفقــة الطفلــة املاضيــة خمســمائة ريــال واملســتقبلية خمســمائة‬\n‫ريــال بنــاء علــى إقــرار والــد الطفلــة املرفــق باملعاملة بأن راتبــه ثالثة آالف‬\n‫ريــال أمــا مــا يخــص نفقــة املدعيــة فتجــدون برفــق صــورة قــرار الصلــح‬\n‫املرفــق برقــم ‪/131‬ص يف ‪1433/3/27‬ه ـ املتضمــن تنازلهــا عــن نفقتها‪.‬‬\n‫املدعيــة بصمتهــا املدعــى عليــه بصمتــه اعضــاء جلنــة الصلــح ‪ ...‬توقيعــه‬\n‫‪ ...‬توقيعــه ‪ ...‬توقيعــه رئيــس قســم االصــاح ‪...‬توقيعه)ا‪.‬ه ـ وبعــرض هــذا‬\n‫القــرار علــى املــرأة املدعيــة قالــت ال أقبــل بهــذا واطلــب نفقتــي حيــث ان‬\n‫تنازلــي مشــروط مبوجــب طالقــي وان تكــون البنــت يف حضانتــي وقــد‬\n‫رفــض املدعــى عليــه ذلــك كمــا يتضــح مــن الدعــوى الســابقة هكــذا‬\n‫قــررت وبعرضــه علــى املدعــى عليــه قــال ال أقبــل مبــا ذكــر يف قــرار جلنــة‬\n‫الصلــح حيــث أننــي ال أســتطيع دفــع ذلــك أمــا مــا ذكرتــه مــن أن تنــازل‬\n‫املــرأة الســابق مبقابــل الطــاق وكذلــك أن تكــون احلاضنــة لديهــا فــا‬\n‫أوافــق علــى ذلــك وأطلــب حضانــة ابنتــي هكــذا قــرر فجرى ســؤال املرأة‬\n‫املدعيــة هــل أنتــي مســتعدة بالرجــوع إلــى املدعــى عليــه فقالــت بعــد هــذا‬\n‫اليــوم لــن أرجــع إلــى زوجــي وغيــر مســتعده بذلــك هكــذا قــررت فجــرى‬\n‫ســؤال املدعــى عليــه هــل ترغــب بزوجتــك فقــال لــم أخرجهــا مــن منزلهــا‬\n‫والــذي أخرجهــا هــو الــذي يعيدهــا وال أقبــل بيمــن املــرأة املدعية هكذا‬\n‫قــرر فجــرى ســؤال املــرأة املدعيــة هــل أنتــي مســتعده ببــذل اليمــن علــى‬\n‫ان املدعــى عليــه لــم يدفــع ســوى مبلــغ ألــف ريــال وهــل أنتــي مســتعده‬\n\n\n                                                                                         ‫‪24‬‬\n\f     ‫كذلــك علــى انــه كانــت نيتــك الرجــوع علــى زوجــك مبــا دفعتــي وان‬\n     ‫املدعــى عليــه هــو الــذي قــام بإخراجــك فقالــت نعــم وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــال ال أقبــل بيمــن املــرأة املدعيــة هكــذا قــرر هــذا كمــا‬\n     ‫جــرى االتصــال علــى جلنــة الصلــح لتقديــر نفقــة الزوجــة وقــد مت حتديــد‬\n     ‫موعــد يف يــوم األحــد الســاعة ‪1433/6/22‬ه ـ الســاعة ‪10.00‬صباحــا‬\n     ‫واملوعــد يف مكتبنــا يف يــوم البــت ‪1433/7/5‬ه ـ الســاعة ‪ 11.00‬وحــرر‬\n                        ‫يف ‪1433/6/17‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت ‪ 1433/07/‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪11.00‬وفيهــا حضــرت املــرأة املدعيــة ‪...‬واملعــرف بهــا مــن قبــل‬\n     ‫‪ ...‬املدونــة هويتهمــا ســابقا وحضــر حلضورهــا املدعــى عليــه ‪ ...‬واملدونــه‬\n     ‫هويتــه ســابقا وقــد ورد إلينــا قــرار مــن مكتــب الصلــح بهــذه احملكمــة‬\n     ‫برقــم ‪/267‬ص يف ‪1433/6/23‬ه ـ واملتضمــن مــا نصــه (وبعرض الصلح‬\n     ‫بينهمــا فقــد تعــذر الصلــح وتــرى اللجنــة أن تكــون نفقــة الزوجــة املاضيــة‬\n     ‫خمســمائة ريــال ونفقــة الطفلــة ‪...‬املاضيــة واملســتقبلية خمســمائة ريــال‬\n     ‫أعضــاء اللجنــة ‪... ....‬رئيــس قســم الصلــح ‪...‬توقيعهــم ) أ‪ .‬ه ـ وبعــرض ذلك‬\n     ‫علــى املدعــى عليــه قــال لســت موافــق علــى ذلــك هكــذا قــرر وبعرضــه‬\n     ‫علــى املــرأة املدعيــة قالــت كل مــا جــاء فيــه صحيــح هكــذا قــررت‬\n     ‫وبــن أخــذ ورد ومحاولــة اإلصــاح بــن الطرفــن اال أننــي لــم أتوصــل‬\n     ‫إلــى نتيجــة فجــرى ســؤال املدعــى عليــه هــل لديــك البينــة علــى صحــة‬\n     ‫دفعــك الــذي دفعــت بــه مــن أن املــرأة هــي التــي خرجــت فقــال ال بينــة لــدي‬\n     ‫إال اهلل عــز وجــل الــذي يعلــم الســر واخفــى هكــذا قــرر فجــرى ســؤاله‬\n     ‫هــل تقبــل بيمــن املدعيــة علــى اآلتــي أوال علــى أنهــا لــم تخــرج بغيــر إذنــك‬\n     ‫ثانيــا انهــا لــم ترفــض الرجــوع علــى الطــاق اال يف تاريــخ ‪1433/6/16‬ه ـ‬\n\n\n‫‪25‬‬\n\f‫وكان قبــل ذلــك تريــد الرجــوع ثالثــا انهــا كانــت تنــوي بالنفقــة الرجــوع‬\n‫إليــه رابعــا أن املبلــغ الــذي دفعتــه هــو ألــف ريــال فقــال ال أقبــل بيمينهــا‬\n‫بــأي شــيء بخصــوص اســتالمها هكــذا قــرر فجــرى ســؤال املــرأة‬\n‫املدعيــة هــل أنتــي مســتعدة ببــذل اليمــن علــى االمــور األربعــة التــي جــرى‬\n‫ذكرهــا آنفــا أطلــب املهلــة للرجــوع إلــى حســاباتي هكــذا قــررت ثــم‬\n‫رفعــت اجللســة يف الســاعة ‪ 12.00‬وحتــى يــوم االربعــاء ‪1433/8/28‬ه ـ‬\n‫الســاعة ‪ 8.30‬وحــرر يف ‪1433/7/5‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                 ‫محمــد صلــى اهلل عليــه وســلم‪.‬‬\n‫احلمــد هلل وحــده ويف يــوم االربعــاء افتتحــت اجللســة الســاعة ‪ 9.00‬وفيهــا‬\n‫حضــرت املــرأة املدعيــة ‪...‬واملعــرف بهــا والدهــا ‪...‬املدونــة هويتهمــا‬\n‫ســابقا ولــم يحضــر املدعــى عليــه ‪...‬وقــد تبلــغ مبوعــد اجللســة يف اجللســة‬\n‫املاضيــة فعليــه وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n‫الشــرعية فقــد قــررت الســير يف دعــوى املــرأة املدعيــة يف غيــاب املدعــى‬\n‫عيــه فجــرى ســؤال املــرأة املدعيــة هــل أحضــرت اجلــواب الــذي طلبتــي‬\n‫املهلــة مــن اجلــه فقالــت نعــم ثــم قــررت قائلــة أنــه بالرجــوع إلــى حســاباتي‬\n‫وكذلــك الرجــوع إلــى اخوتــي ووالــدي لــم نســتلم مــن املدعــى عليه ســوى‬\n‫مبلــغ ثالثــة آالف ريــال وعنــد إنفاقــي علــى نفســي وعلــى ابنتــي كنــت‬\n‫انــوي الرجــوع علــى املدعــى عليــه ولــم أمنعــه مــن نفســي حتــى تاريــخ‬\n‫‪1433/6/16‬ه ـ وأنــا مســتعده ببــذل اليمــن متــى مــا طلبــت منــي واقصــر‬\n‫دعــواي علــى املطالبــة بنفقتــي حتــى تاريــخ ‪1433/6/16‬ه ـ هكــذا‬\n‫قــررت بحضــرة وشــهادة والدهــا فجــرى ســؤالها هــل أنتــي مســتعده ببــذل‬\n‫اليمــن علــى صحــة دعــواك فقالــت نعــم فجــرى نصحهــا وتخويفهــا بــاهلل‬\n‫عــز وجــل مــن مغبــة هــذه اليمــن إال أنهــا أصــرت فأذنــت لهــا فحلفــت‬\n\n\n                                                                                         ‫‪26‬‬\n\f     ‫قائــا واهلل العظيــم الــذي ال إلــه إال هــو املهلــك املــدرك بــأن املدعــى عليــه‬\n     ‫الغائــب عــن املجلــس الشــرعي ‪ ...‬وبتاريــخ ‪1427/6/30‬ه ـ أحضرنــي‬\n     ‫زوجــي إلــى منــزل أهلــي برضــاه وبإذنــه ومــن ذلــك التاريــخ وحتــى تاريــخ‬\n     ‫‪1433/6/16‬ه ـ لــم أمنعــه مــن نفســي وال مانــع لــدي مــن الرجــوع إليــه‬\n     ‫حتــى تاريــخ ‪1433/6/16‬ه ـ ولــم ينفــق املدعــى عليــه ال علــي وال علــى‬\n     ‫ابنتــه ســوى مبلــغ ثالثــة آالف ريــال وال أعلــم أن والــدي وال أخوتــي قــد‬\n     ‫اســتلموا غيــر هــذا املبلــغ وكنــت أنــوي عنــد اإلنفــاق الرجــوع إليــه واهلل‬\n     ‫العظيــم هكــذا حلفــت فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وبنــاء‬\n     ‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ومبــا ان‬\n     ‫املدعــى عليــه لــم يقــدم عــذرا إليضــاح ســبب غيابــه وملصادقــة املدعــى‬\n     ‫عليــه بــأن زوجتــه مــن ‪1427/6/30‬ه ـ ليســت لديــه وأن ابنتــه مــن والدتهــا‬\n     ‫وحتــى هــذا اليــوم لــم ينفــق عليهمــا ســوى املبلــغ الــذي ذكــر وقــد قــرر‬\n     ‫العلمــاء قاعــده مــن تــرك دعــواه تــرك ومبــا أنــه قــد دفــع بــأن زوجتــه‬\n     ‫قــد خرجــت منزلــه بــدون اذنــه وانهــا امتنعــت مــن الرجــوع إليــه وإلقــراره‬\n     ‫أال بينــة لديــه ســوى اهلل عــز وجــل ومبــا أن املدعــى عليهــا قــد قصــرت‬\n                                                ‫نفقتهــا حتــى تاريــخ ‪1433/6/16‬ه ـ‬\n     ‫وال عــذر ملــن أقــر ولقــرار جلنــة الصلــح واملــدون آنفــا وقــد قــرر العلمــاء‬\n     ‫قاعــده شــرعية العــادة محكمــة واملعــروف عرفــا كاملشــروط شــرطا‬\n     ‫وقــد ذكــر شــيخ اإلســام ابــن تيمــه يف مجمــوع الفتــاوى ‪134/34‬‬\n     ‫مــا نصــه (اذا كان االبــن يف حضانــة أمــه فأنفقــت عليــه تنــوي بذلــك‬\n     ‫الرجــوع علــى األب فلهــا أن ترجــع علــى األب يف أظهــر قولــي العلمــاء وهــو‬\n     ‫مذهــب مالــك وأحمــد يف ظاهــر مذهبــه الــذي عليــه قدمــاء أصحابــه)‬\n     ‫أ‪.‬ه ـ وقــد ذكــر ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه الــكايف ‪97/5‬‬\n\n\n‫‪27‬‬\n\f‫مــا نصــه( واذا وجــد اليمــن املوجــب للنفقــة فلــم ينفــق حتــى مضــت مــدة‬\n‫صــارت النفقــة دينــا يف ذمتــه ســواء تركهــا لعــذر أو غيــره حلديــث عمــر‬\n‫رضــي اهلل عنــه وألنــه مــال يجــب علــى ســبيل البــدل يف عقــد معاوضة فلم‬\n‫يســقط مبضــي الزمــن) وقــد ذكــر إبراهيــم ابــن ضويــان رحمــه تعالــى‬\n‫يف كتابــه منــار الســبيل ‪ 1046/3‬مــا نصــه ( ومــن غــاب عــن زوجتــه مــدة‬\n‫ولــم ينفــق عليهــا لزمتــه نفقــة الزمــن املاضــي) أ‪.‬ه ـ وقــد ذكــر رحمــه‬\n‫تعالــى يف موضــع آخــر صحيفــة ‪ 1052‬مــا نصــه (حيــث امتنــع منهــا الــزوج‬\n‫أو قريــب وأنفــق أجنبــي بنيــة الرجــوع رجــع ألنــه قــام عنــه بواجــب قضــاء‬\n‫دينــه )أ‪.‬ه ـ وكالمــه هــذا يف نفقــة الصغيــر كمــا ذكر ذلــك يف التنقيح‬\n‫املشــبع‪ 286‬وكذلــك إقــرار املــرأة املدعيــة باقتصارهــا علــى النفقــة‬\n‫اخلاصــة بهــا حتــى ‪1433/6/16‬ه ـ وكذلــك لــم تســتلم مــن نفقهــا ونفقــة‬\n‫ابنتهــا ســوى مبلــغ ثالثــة آالف ريــال ومبــا أنهــا قــد بذلــت اليمــن جلميــع‬\n‫ذلــك فقــد ألزمــت باآلتــي أوال بــأن يدفــع املدعــى عليــه ‪...‬نفقــة املدعيــة‬\n‫للســنوات املاضيــة وهــي واحــد وســبعون شــهرا ومجموعهــا مبلــغ خمســة‬\n‫وثالثــن ألفــا وخمســمائة ريــال وبعــد املقاصــاه وخصــم مبلــغ ثالثــة آالف‬\n‫ريــال فيصبــح املبلــغ مبلــغ اثنــن وثالثــن ألفــا وخمســمائة ريــال ثانيــا بــأن‬\n‫يدفــع املدعــى عليــه للمدعيــة نفقــة االبنــة ‪...‬مــن تاريــخ ‪1427/7/27‬ه ـ‬\n‫وحتــى تاريــخ ‪1433/8/25‬ه ـ ومجموعهــا مبلــغ ســتة وثالثــن ألفــا‬\n‫وخمســمائة ريــال ثالثــا فقــد ألزمــت املدعــى عليــه بــأن يدفــع للمدعيــة‬\n‫نفقــة االبنــة ‪ ...‬املســتقبلية وهــي مبلــغ خمســمائة ريــال اعتبــار مــن تاريــخ‬\n‫‪1433/9/25‬ه ـ وبــه حكمــت وبعرضــه عليهــا قنعــت بــه وأفهمتهــا بــأن‬\n‫هــذا احلكــم حكــم حضــوري خاضــع لالســتئناف حســب التعليمــات‬\n            ‫وحــرر يف ‪1433/8/28‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n\n\n                                                                                        ‫‪28‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن ‪1434/2/18‬ه ـ افتتحــت‬\n     ‫اجللســة يف الســاعة الثامنــة والنصــف وقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف مبكــة املكرمــة بالقــرار رقــم ‪ 345811‬يف ‪1434/1/7‬ه ـ‬\n     ‫واملتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم قاضــي اســتئناف ‪...‬ختمــه‬\n     ‫وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه‬\n     ‫وتوقيعــه وقــد تركــت طيلــت هــذه الفتــره لــم يهمــش عليهــا حيــث كان‬\n     ‫لــدي برنامــج يف القضــاء اجلزائــي ملــدة ثمانيــة اســابيع اعتبــار ًا مــن‬\n     ‫تاريــخ ‪1433/12/18‬ه ـ وذلــك مبوجــب خطــاب وكيــل الــوزارة برقــم‬\n     ‫‪ 1923396‬يف ‪1433/11/1‬ه ـ وحــرر يف ‪14334/2/18‬ه ـ وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن‬\n     ‫قضاة الدائرة األولى لألحوال الشــخصية واألوقاف والوصايا والقصار‬\n     ‫وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكــة املكرمة جرى منا‬\n     ‫االطــاع علــى الصــك رقــم ‪ 33396987‬وتاريــخ ‪1433/8/28‬ه ـ الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة العامــة بالطائــف الشــيخ ‪ ...‬املتضمــن‬\n     ‫دعــوى ‪ ...‬ضــد ‪ ...‬يف نفقــة وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪29‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":20,"source_page_end":29,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6959507b8b7c4e4197a99347228edef5ba098112e0185cd9634d88bd1fc1dd2c","normalized_text_hash":"14696530726e7f5b65a173d745a4216e1851558a6cce9e166befe659f3a7f903","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p20-3396987"},{"id":"fc813a86-80a8-5723-a0b3-8c00ececf942","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة مدة محددة -نفقة بنت املاضية و املستقبلية -إدخال والد الزوجة لتقرير نفقته على البنت من عدمه -القول قول الزوجة يف عدم النشوز مع ميينها -ال تقبل شهادة عمودي النسب بعضهم لبعض -من صح إقراره يف شيء قبلت ميينه على إنكاره -احلكم بنفقة املدعية وابنتها املدة املذكورة.","document_number":"3418724","case_number":"33176903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف عقدت اجللسة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"نفقة -نفقة زوجة مدة محددة -نفقة بنت املاضية و املستقبلية -إدخال والد الزوجة لتقرير نفقته على البنت من عدمه -القول قول الزوجة يف عدم النشوز مع ميينها -ال تقبل شهادة عمودي النسب بعضهم لبعض -من صح إقراره يف شيء قبلت ميينه على إنكاره -احلكم بنفقة املدعية وابنتها املدة املذكورة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3418724 :‬‬\n                   ‫َر ْق ُم الدعوى‪33176903 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 3455386‬تاريخه‪1434/3/4 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة مــدة محــددة ‪ -‬نفقــة بنــت املاضيــة و املســتقبلية‬\n‫‪ -‬إدخــال والــد الزوجــة لتقريــر نفقتــه علــى البنــت مــن عدمــه ‪ -‬القــول‬\n‫قــول الزوجــة يف عــدم النشــوز مــع ميينهــا ‪ -‬ال تقبــل شــهادة عمــودي‬\n‫النســب بعضهــم لبعــض ‪ -‬مــن صــح إقــراره يف شــيء قبلــت ميينــه علــى‬\n               ‫إنــكاره ‪ -‬احلكــم بنفقــة املدعيــة وابنتهــا املــدة املذكــورة‪.‬‬\n\n\n\n\n                              ‫‪ -1‬قوله تعالى « لينفق ذو سعة من سعته»‬\n          ‫‪ -2‬قوله تعالى « وعلى املولود له رزقهن وكسوتهن باملعروف»‬\n‫‪ -3‬قــال يف كشــاف القنــاع « وال تقبــل شــهادة عمــودي النســب بعضهــم‬\n                                                          ‫لبعــض» ‪. 313/15‬‬\n‫‪ -4‬قــال يف كشــاف القنــاع ( وإن اختلــف الزوجــان يف نشــوزها بعــد‬\n‫االعتــراف بالتســليم أو اختلفــا يف االتفــاق عليهــا أو يف تســليم النفقــة‬\n        ‫إليهــا فالقــول قولهــا ألن األصــل عــدم ذلــك ) ‪142-141/13‬ه ـ‬\n                    ‫‪ -5‬من صح إقراره يف شيء قبلت ميينه على إنكاره ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــة للمدعــى عليــه ورزق‬\n‫منهــا بأربعــة أوالد واصغرهــم بنت ـ ًا عمرهــا تســعة أعــوام وقــد مت فســخ‬\n\n                                                                                    ‫‪30‬‬\n\f     ‫نــكاح موكلتــه مــن املدعــى عليــه يف ‪1431/6/25‬ه ـ كمــا أن البنــت‬\n     ‫كانــت يف حضانــة والدتهــا واملدعــى وكالــة يطالــب بنفقــة موكلتــه‬\n     ‫مــن تاريــخ ‪1426/8/17‬ه ـ وحتــى تاريــخ فســخ نكاحهــا ونفقــة ابنتــه‬\n     ‫التــي كانــت يف حضانــة والدتهــا مــن ‪ 1426/8/17‬ه ـ وحتــى اســتالمها‬\n     ‫مــن قبــل والدهــا يف ‪1433/4/4‬هــ‪ ،‬أجــاب املدعــى عليــه باملصادقــة‬\n     ‫علــى الدعــوى ودفــع بــأن املدعيــة أصالــة ال تســتحق النفقــة عليهــا ألنهــا‬\n     ‫كانــت ناشــز ًا وكذلــك والدهــا اســتعد بنفقتهــا ونفقــة ابنتهــا ولــذا‬\n     ‫فإنــه غيــر ملــزم بهــذه املطالبــة‪ ،‬حضــر والــد املدعيــة أصالــة وانكــر‬\n     ‫دفــع املدعــى عليــه‪ ،‬قــرر املدعــى عليــه إن بينتــه علــى نشــوز املدعيــة هــم‬\n     ‫أوالده‪ ،‬طلــب املدعــى عليــه ميــن املدعيــة ووالدهــا‪ ،‬حلفــت املدعيــة علــى‬\n     ‫إنهــا لــم تكــن ناشــز ًا وحلــف والدهــا علــى نفــى دفــع املدعــى عليــه‪ ،‬ثــم‬\n     ‫تقــدر نفقــة املدعيــة املاضيــة مبلغــا قــدره أربعمائــة ريــال والبنــت ثالثمائــة‬\n     ‫ريــال مــن قبــل هيئــة النظــر‪ ،‬قــرر ناظــر القضيــة لألســباب املرصــودة‬\n     ‫يف نــص القضيــة ولقولــه تعالــى ((لينفــق ذو ســعه مــن ســعته)) احلكــم‬\n     ‫علــى املدعــى عليــه بتســليم املدعيــة نفقتهــا ونفقــة ابنتهــا مبلغــا قــدره‬\n     ‫ســبعة وأربعــون ألفـ ًا ومائــة وســته وســتون ريــاالً‪ ،‬قــررت املدعيــة ووالدهــا‬\n     ‫القناعــة وقــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة‬\n                                             ‫االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ .....‬القاضــي باحملكمــة العامــة بالطائــف عقــدت اجللســة للنظــر يف‬\n     ‫دعــوى ضــد بطلــب النفقــة املقيــدة برقــم ‪ 33465116‬يف ‪1433/3/12‬هـ‬\n\n‫‪31‬‬\n\f‫واحملالــة لــي مــن فضيلــة الرئيــس برقــم ‪ 33176903‬يف ‪1433/3/12‬ه ـ‬\n‫وفيهــا حضــر ‪ .....‬فلســطيني اجلنســية برخصــة إقامــة رقــم ‪ .....‬بصفتــه‬\n‫ا عــن املدعيــه مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬                 ‫وكي ـ ً‬\n‫الثانيــة بالطائــف رقــم ‪ 11812‬يف ‪1433/2/27‬ه ـ والتــي تخولــه إقامــة‬\n‫وســماع الدعــاوى واملطالبــات املقامــة مــن موكلتــه ضــد املدعــى‬\n‫عليــه واملدافعــة واملرافعــة وحضــور اجللســات وتقــدمي البينــات واالقــرار‬\n‫واالنــكار واملطالبــة بنفقــة ابنتهــا وادعــى علــى احلاضــر معــه املدونــة‬\n‫ا يف دعــواه إن املدعــى عليــه كان زوج ـ ًا ملوكلتــي‬         ‫هويتــه ســابق ًا قائ ـ ً‬\n‫وقــد مت فســخ نكاحهــا بتاريــخ ‪1431/6/25‬ه ـ بعــد أن أجنبــت منــه‬\n‫علــى فــراش الزوجيــة أربعــة أوالد األول وعمرهــا ســتة عشــر عام ـ ًا‬\n‫والثانــي وعمــره أربعــة عشــر عام ـ ًا والثالــث وعمــره أحــد عشــر عام ـ ًا‬\n‫والرابــع وعمرهــا تســعة أعــوام ولــم ينفــق علــى موكلتــي مــن تاريــخ‬\n‫‪1426/8/17‬ه ـ حتــى تاريــخ فســخ النــكاح يف ‪1431/6/25‬ه ـ كما لم‬\n‫ينفــق علــى ابنتهــا مــن تاريــخ ‪1426/8/17‬ه ـ وحتــى تاريــخ اســتالمه لهــا‬\n‫يف تاريــخ ‪1433/4/4‬ه ـ لــذا أطلــب ســؤاله وإلزامــه بدفــع نفقة موكلتي‬\n‫وابنتهــا مــن املدعــى عليــه خــال املــدة املذكــورة بعــد تقديرهــا هــذه‬\n‫دعــواي وبعرضهــا علــى املدعــى عليــه اســتعد باإلجابــة عليهــا يف اجللســة‬\n‫القادمــة ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة كمــا حضــر‬\n‫املدعــى عليــه وبســؤال املدعــى عليــه عــن جوابــه علــى الدعــوى أجــاب‬\n‫ا مــا ذكــره املدعــي وكالــة يف دعــواه مــن الــزواج وفســخ النــكاح‬             ‫قائـ ً‬\n‫واألوالد وأعمارهــم كلــه صحيــح وكذلــك مــا ذكــر مــن عــدم نفقتــي‬\n‫علــى املدعيــة أصالــة وابنتــي خــال املــدة التــي ذكرهــا املدعــي وكالــة‬\n‫صحيــح ولكــن ال جتــب علـ ّـي نفقــة املدعيــة وال نفقــة ابنتنــا ألن املدعيــة‬\n\n\n                                                                                             ‫‪32‬‬\n\f     ‫تعتبــر ناشــز ًا فقــد خرجــت مــن بيتــي طــوال املــدة املذكــورة بــدون علمــي‬\n     ‫ورضــاي وقــد حجــزت البنــت عنــي فلــم اســتطع خــال تلــك املــدة رؤيتهــا‬\n     ‫وزيارتهــا كمــا أن والــد املدعيــة قــد اســتعد بنفقــة املدعيــة وبنفقــة ابنتــي‬\n     ‫وقــد حلــف علــى ذلــك واملدعيــة وابنتنــا كانــت عنــده هكــذا أجــاب‬\n     ‫وبعــرض جوابــه علــى املدعــي وكالــة قــال موكلتــي لــم تكــن ناشــز َا بــل‬\n     ‫املدعــى عليــه هــو الــذي تركهــا ويــدل علــى ذلــك صــك فســخ النــكاح‬\n     ‫وأبــرز صــك ًا صــادر ًا مــن احملكمــة العامــة بجــدة برقــم ‪ 8/200/99‬يف‬\n     ‫‪1430/5/21‬ه ـ وقــال بأنــه صــك فســخ النــكاح وأمــا والــد موكلتــي‬\n     ‫فلــم يســتعد بنفقــة موكلتــي وابنتهــا هكــذا أجــاب لــذا رفعــت اجللســة‬\n     ‫إلدخــال والــد املدعيــة ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n     ‫واملدعــى عليــه كمــا حضــر والــد املدعيــة حامــل رخصــة إقامــة رقــم‬\n     ‫وبســؤال والــد املدعيــة عــن مــا ذكــره املدعــى عليــه يف اجللســة الســابقة‬\n     ‫مــن أنــه اســتعد بنفقــة ابنــة املدعــى عليــه وأنــه حلــف علــى ذلــك واملدعيــة‬\n     ‫وابنتــه كانــت عنــده أجــاب والدهــا بــأن مــا ذكــره املدعــى عليــه غيــر‬\n     ‫صحيــح وإمنــا الصحيــح أنــه حــن جاءتنــي بنتــي ومعهــا طفلتهــا قلــت‬\n     ‫لــه بعدهــا بيومــن يــا إذا طلقــت بنتــي وأرســلت ورقتهــا فأنــا أتكفــل‬\n     ‫بتربيــة البنــت وســأنفق عليهــا ولكنــه لــم يقــم بذلــك ولــم يطلــق ابنتــي‬\n     ‫وإمنــا اضطرنــي لتقــدمي الدعــاوى والذهــاب إلــى املنطقــة الشــرقية وتقــدمي‬\n     ‫دعــوى هنــاك وحصــل بيننــا مرافعــات انتهــت بفســخ نــكاح ابنتــي منــه‬\n     ‫ـف بالشــرط الــذي اشــترطته‬      ‫وحيــث إنــه لــم يقــم بتطليــق ابنتــي ولــم يـ ِ‬\n     ‫عليــه فإنــي لــم أتكفــل بالنفقــة ونطالبــه بنفقــة البنــت املاضيــة ونفقــة‬\n     ‫الزوجــة مــن تاريــخ خروجهــا وحتــى تاريــخ فســخ نكاحهــا وبعــرض‬\n     ‫جوابــه علــى املدعــى عليــه قــال إن والدهــا تكفــل بالنفقــة علــى البنــت‬\n\n\n‫‪33‬‬\n\f‫ولــم يشــترط علــي تطليــق ابنتــه وأمــا نفقــة الزوجــة فقــد كانــت ناشــز ًا‬\n‫وال أوافــق علــى إعطائهــا النفقــة فــكل قولــه غيــر صحيــح فجرى ســؤاله‬\n‫ألــك بينــة علــى أن والــد املــرأة تكفــل بالنفقــة مــن غيــر قيــد وال شــرط‬\n‫فأجــاب ليــس لــدي بينــة علــى ذلــك وأطلــب ميــن والدهــا علــى أنــه اشــترط‬\n‫أن أطلــق ابنتــه وأوصــل لــه ورقــة طالقهــا حتــى ينفــق علــى ابنتــي هكــذا‬\n‫قــال وبعــرض ذلــك علــى والــد املدعيــة اســتعد بــأداء اليمــن يف اجللســة‬\n‫القادمــة فأفهــم بــأن عليــه حضــور اجللســة القادمــة وإحضــار املدعيــة ثــم‬\n‫عقــدت اجللســة وفيهــا حضــرت املدعيــة أصالــة ‪ .....‬فلســطينية اجلنســية‬\n‫مبوجــب رخصــة إقامــة رقــم ‪ .....‬املعــرف بهــا مــن قبــل والدهــا احلاضــر‬\n‫ووكيلهــا كمــا حضــر املدعــى عليــه ويف هــذه اجللســة جــرى ســؤال‬\n‫املدعــى عليــه هــل لديــه بينــة علــى أن املدعيــة أصالــة كانــت ناشــز ًا‬\n‫فقــال شــهادة أوالدي أو ميينهــا فجــرى إفهامــه بــأن شــهادة أوالده ال تقبــل‬\n‫لوجــود املانــع فقــال أريــد ميينهــا علــى أنهــا لــم تكــن ناشــز ًا وميــن والدهــا‬\n‫علــى عــدم اســتعداده بدفــع نفقــة املدعيــة ونفقــة ابنتنــا هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعيــة ووالدهــا اســتعدا بحلــف اليمــن فأذنــت‬\n‫ا واهلل العظيــم أننــي لــم‬ ‫لهمــا بعــد وعظهمــا فحلــف والــد املدعيــة قائ ـ ً‬\n‫ألتــزم للمدعــى عليــه بنفقــة ابنتــي وابنتهــا إال إذا أحضــر ورقــة طالقهــا‬\n‫وأنــه لــم يحضــر ورقــة طالقهــا واهلل العظيــم وحلفــت املدعيــة قائلــة واهلل‬\n‫العظيــم أننــي لــم أنشــز عــن طاعــة زوجــي وأنــه هــو الــذي تركنــي بنفســه‬\n‫واهلل العظيــم هكــذا حلفــا هــذا وقــد جــرى اإلطــاع علــى صــورة الصــك‬\n‫الــذي ســبق وأن أحضرهــا املدعــي وكالــة وأشــير إليــه ســابق ًا فوجــد‬\n‫مضمونهــا دعــوى املدعيــة ضــد املدعــى عليــه بطلــب فســخ نكاحهــا منــه‬\n‫وقــد نظرهــا فضيلــة مصــدره غيابي ـ ًا لعــدم العثــور علــى املدعــى عليــه‬\n\n\n                                                                                            ‫‪34‬‬\n\f     ‫وفســخ نــكاح املدعيــة بنــاء علــى شــهادة شــاهدي املدعيــة بــأن املدعــى‬\n     ‫عليــه غيــر منفــق وجــاء يف شــهادتهما أن املدعــى عليــه تــرك زوجتــه منــذ‬\n     ‫ثــاث ســنوات عنــد أهلهــا أ ‪ .‬ه ـ كمــا ســبق مخاطبــة مكتــب الصلــح‬\n     ‫بهــذه احملكمــة حملاولــة الصلــح أو تقديــر النفقــة فــورد قــرار املكتــب‬\n     ‫رقــم ‪/151‬ص يف ‪1433/4/11‬ه ـ املرفــق مــع املعاملــة وفيــه (وبعــرض‬\n     ‫الصلــح علــى الطرفــن وتقريــب وجهــات النظــر تعــذر الصلــح بينهمــا‬\n     ‫عليــه تــرى اللجنــة بعــد رأي فضيلتكــم أن تكــون النفقــة املاضيــة‬\n     ‫للزوجــة أربعمائــة ريــال وأن تكــون النفقــة املاضيــة للطفلــة ثالثمائــة‬\n     ‫ريــال وبــاهلل التوفيــق) أ‪.‬ه ـ وبعــرض هــذا القــرار علــى الطرفــن لــم تبــدي‬\n     ‫املدعيــة جتاهــه شــيء وأمــا املدعــى عليــه فقــال بــأن هــذا التقديــر عندمــا‬\n     ‫كان راتبــي ثالثــة أالف وأنــا أحتــج عليــه وبســؤال الطرفــن هــل لديهمــا‬\n     ‫إضافــة قالــت املدعيــة ليــس لــدي إضافــة وأمــا املدعــى عليــه فقــال بأنــه‬\n     ‫تقــادم العهــد بالنفقــة والنفقــة إلحيــاء النفــس ووالدهــا ميســور احلــال‬\n     ‫هكــذا أضــاف فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وكالــة بطلــب‬\n     ‫نفقــة املدعيــة مــن تاريــخ ‪1426/8/17‬ه ـ حتــى تاريــخ فســخ النــكاح يف‬\n     ‫‪1431/6/25‬ه ـ ونفقــة ابنتهــا مــن تاريــخ ‪1426/8/17‬ه ـ وحتــى تاريــخ‬\n     ‫‪1433/4/4‬ه ـ ومــا ورد يف إجابــة املدعــى عليــه ومصادقتــه علــى عــدم‬\n     ‫نفقتــه علــى املدعيــة وابنتهمــا خــال تلــك املــدة ودفعــه بــأن املدعيــة‬\n     ‫كانــت ناشــز ًا وأن والدهــا اســتعد بنفقتهــا ونفقــة ابنتهمــا وإلنــكار‬\n     ‫املدعــي وكالــة مــا دفــع بــه املدعــى عليــه وملــا ورد يف إجابــة والــد املدعيــة‬\n     ‫الــذي مت إدخالــه مــن أنــه لــم يلتــزم بالنفقــة إال إذا طلــق املدعــى عليــه‬\n     ‫ابنتــه وأنــه لــم يطلقهــا ويفــي بهــذا الشــرط وإلنــكار املدعــى عليــه وجــود‬\n     ‫هــذا الشــرط وملــا قــرره مــن عــدم وجــود بينــة لديــه علــى اســتعداد والــد‬\n\n\n‫‪35‬‬\n\f‫املدعيــة بالنفقــة وعلــى نشــوز املدعيــة إال شــهادة أوالده علــى النشــوز‬\n‫وشــهادة الولــد لوالــده ال تقبــل لوجــود مانــع وهــو قرابــة الــوالدة قــال يف‬\n‫الكشــاف ((وال تقبــل شــهادة عمــودي النســب بعضهــم لبعــض)) أ ‪ .‬ه ـ‬\n‫‪313/15‬ولطلــب املدعــى عليــه ميــن املدعيــة ووالدهــا علــى نفــي مــا دفــع‬\n‫بــه وحللفهمــا علــى نفــي ذلــك بعــد اإلذن لهمــا وألن القــول قــول املــرأة يف‬\n‫عدم نشــوزها قال يف الكشــاف (( وإن اختلفا أي الزوجان يف نشــوزها‬\n‫بعــد االعتــراف بالتســليم أو اختلفــا يف اإلنفــاق عليهــا أو يف تســليم النفقة‬\n‫إليهــا فالقــول قولهــا ألن األصــل عــدم ذلــك)) أ ‪ .‬ه ـ ‪ 142-141/13‬وألن‬\n‫ميــن والــد املدعيــة وإن لــم يكــن مدعــى عليــه مقبولــة ألن مــن صــح‬\n‫إقــراره يف شــيء قبلــت ميينــه علــى إنــكاره وملــا ورد يف قــرار مكتــب‬\n‫الصلــح مــن تقديــر نفقــة املدعيــة بأربعمائــة ريــال وابنتهمــا بثالثمائــة‬\n‫ريــال شــهري ًا وألن كامــل املــدة التــي لــم ينفــق فيهــا علــى املدعيــة هــي‬\n‫ســبعة وخمســون شــهر ًا وثالثــة وعشــرون يومـ ًا وإجمالــي نفقــة هــذه املــدة‬\n‫حســب التقديــر املشــار إليــه ثالثــة وعشــرون ألفـ ًا وثالثمائة وســتة رياالت‬\n‫وكامــل املــدة التــي لــم ينفــق فيهــا علــى ابنتهمــا هــي تســعة وســبعون‬\n‫شــهر ًا وســبعة عشــر يومـ ًا وإجمالــي نفقــة هــذه املــدة حســب التقديــر هــو‬\n‫ثالثــة وعشــرون ألــف ومائــة وثالثــون ريــا ًال لذلــك كلــه ولقولــه ســبحانه‬\n‫وتعالــى (لينفــق ذو ســعة مــن ســعته) وقولــه ســبحانه (وعلــى املولــود لــه‬\n‫رزقهــن وكســوتهن باملعــروف) فقــد حكمــت علــى املدعــى عليــه بدفــع‬\n‫ســبعة وأربعــن ألف ـ ًا ومائــة وســتة وســتني ريــا ًال للمدعيــة أصالــة نفقتهــا‬\n‫وابنتهــا للمــدة املذكــورة بعاليــه وبإعــان احلكــم علــى الطرفــن قــررت‬\n‫املدعيــة ووالدهــا القناعــة وأمــا املدعــى عليــه فقــرر عدمهــا فجــرى‬\n‫إفهامــه باالنتظــار بعــد إغــاق اجللســة الســتالم نســخة مــن صــك احلكــم‬\n\n\n                                                                                       ‫‪36‬‬\n\f     ‫وتقــدمي مــا لديــه خــال ثالثــن يوم ـ ًا مــن تاريــخ اليــوم وبــاهلل التوفيــق‬\n     ‫حــرر يف ‪1434/1/20‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه أجمعــن ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي الســاعة لعاشــرة مــن هــذا اليــوم االثنــن‬\n     ‫املوافــق ‪1434/3/23‬ه ـ عقــدت اجللســة وقــد عــادت املعاملــة مــن‬\n     ‫محكمــة االســتئناف بخطــاب فضيلــة رئيســها رقــم ‪ 34486688‬يف‬\n     ‫‪1434/3/14‬ه ـ وقــد ظهــر صــك احلكــم بقــرار الدائــرة الثانيــة لألحوال‬\n     ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة رقــم ‪ 3455386‬يف ‪1434/3/4‬ه ـ‬\n     ‫ونصــه (( احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n     ‫‪ 3418724‬يف ‪1434/1/20‬ه ـ الصــادر مــن فضيلــة الشــيخ وأصدرنــا‬\n     ‫القــرار رقــم ‪ 3455386‬وتاريــخ ‪1434/3/4‬ه ـ املتضمــن املوافقــة علــى‬\n     ‫احلكــم واهلل املوفــق)) أ‪.‬ه ـ قاضــي اســتئناف ختمــه وتوقيعــه قاضــي‬\n     ‫اســتئناف د‪ .....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه لــذا‬\n     ‫جــرى إحلاقــه وبــاهلل التوفيــق حــرر يف ‪1434/3/23‬ه ـ وصلــى اهلل وســلم‬\n                               ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n     ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n     ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n     ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة‬\n     ‫املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي‬\n     ‫باحملكمــة العامــة بالطائــف برقــم ‪ 3418724‬وتاريــخ ‪1434/01/20‬ه ـ‬\n     ‫املتضمــن دعــوى‪ .....‬ضــد‪ .....‬يف نفقــة وبدراســة الصــك وصــورة ضبطــه‬\n     ‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                           ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n‫‪37‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":30,"source_page_end":37,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"666b9f3e39bfa585453cf800ed77f545c7fb3d65d5d3c73efba5f46109eb06c2","normalized_text_hash":"08448a791abda952bb26761c14b10fc02f6f63190a1db65067a77a6fb3833721","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p30-3418724"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a08720c7-d034-5d83-86c1-a48918911ba8","document_type":"judgment","category":"judicial","subcategory":"general","title":"زيارة -املطالبة بزيارة أب البنته -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب تقدير قسم اخلبراء.","document_number":"3413376","case_number":"49266","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"زيارة -املطالبة بزيارة أب البنته -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب تقدير قسم اخلبراء.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3413376 :‬‬\n                            ‫َر ْق ُم الدعوى‪49266 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34283175‬تاريخه‪1434/7/30:‬هـ‬\n\n\n      ‫زيــارة ‪ -‬املطالبــة بزيــارة أب البنتــه ‪ -‬حتديــد الزيــارة ووقتهــا عــن طريــق‬\n                       ‫قســم اخلبــراء ‪ -‬احلكــم مبوجــب تقديــر قســم اخلبــراء‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــال اهلل تعالــى‪( :‬وقضــى ربــك أال تعبــدوا إال إيــاه وبالوالديــن‬\n                                                                    ‫إحســان ًا )‪.‬‬\n                                     ‫‪ -2‬املادة ‪ 122‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n      ‫أقــام رجــل دعــوى علــى مطلقتــه يطالــب بتمكــن ابنتــه املولــودة يف‬\n      ‫‪1421/1/1‬ه ـ مــن زيارتــه واملبيــت عنــده ومنــع املدعــى عليهــا مــن منــع‬\n      ‫ابنتــه مــن االتصــال بــه يف أي وقــت‪ -‬وافقــت املدعــى عليهــا علــى طلــب‬\n      ‫املدعــي متكــن ابنتــه مــن زيارتــه علــى أن تكــون الزيــارة يف منزلهــا ألن‬\n      ‫ابنتهــا ترفــض بشــدة أن تذهــب إلــى بيــت والدهــا ملــا جتــده مــن اضطهــاد‬\n      ‫واعتــداءات متكــررة مــن قبــل زوجــة أبيهــا ووالدتــه ‪ -‬قــررت احملكمــة‬\n      ‫الكتابــة لقســم اخلبــراء لتحديــد مــدة الزيــارة ومكانهــا فــورد اجلــواب‬\n      ‫مــن قســم اخلبــراء أن تكــون الزيــارة يومــا مــن كل أســبوع وبعــرض ذلــك‬\n      ‫علــى الطرفــن رفضــا قــرار مكتــب الصلــح ‪ -‬حكمــت احملكمــة مبــا‬\n      ‫جــاء يف قــرار قســم اخلبــراء علــى أن يقــوم املدعــي بأخــذ ابنتــه لزيارتــه‬\n        ‫وإعادتهــا ملنــزل والدتهــا ‪ -‬اعترضــت املدعــى عليهــا ‪ -‬صــدق احلكــم‪.‬‬\n‫‪305‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي (‪ ).....‬يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامة‪/‬املســاعد وتاريــخ ‪1431/11/19‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n‫‪1431/11/19‬ه ـ واملعــادة مــن حفــظ احملكمــة لعــدم املراجعــة يف‬\n‫‪1431/4/14‬ه ـ ففــي يــوم الســبت املوافق‪1433/08/03‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية وادعــى علــى احلاضــر معــه‬\n‫(‪ ).....‬ســعودي اجلنســية مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بالريــاض برقــم (‪ ).....‬يف ‪1430/2/8‬ه ـ جلــد ‪ 17523‬والتــي‬\n‫تخولهــا لنيابــة عنهــا يف كل دعــوى تقــام منــه أو ضــده ولهــم يف ذلــك حــق‬\n‫املطالبــة واملرافعــة واملدافعــة وقبــول الصلــح والتنازل واإلقــرار واإلنكار‬\n‫وقبــول اليمــن وردهــا وقبــول األحــكام واالعتــراض عليهــا وطلــب‬\n‫ا يف دعــواه‪ :‬إن‬ ‫متييزهــا واســتالم وتســليم املســتندات والصكــوك‪ .‬قائـ ً‬\n‫املدعــى عليهــا كانــت زوجــة لــي وقــد طلقتهــا وقــد بانــت منــي منــذ ســبع‬\n‫ســنوات وقــد أجنبــت لــي علــى فــراش الزوجيــة بنتــا اســمها (‪ ).....‬املولــودة‬\n‫يف ‪1421/1/1‬ه ـ وقــد طلبــت منهــا عــدة مــرات زيــارة ابنتــي لــي فرفضت‬\n‫وقــد بذلــت وأرســلت مــن يســعى للصلــح دون اللجــوء للمحاكــم لكــن‬\n‫ذلــك لــم يــأت بفائــدة أطلــب احلكــم علــى املدعــى عليهــا والــدة ابنتــي بــأن‬\n‫تزورنــي ابنتــي كل يــوم مــن الســاعة الواحــدة ظهــر ًا وحتــى الســاعة‬\n‫الرابعــة عصــر ًا وأســبوعي ًا مــن عصــر يــوم األربعــاء إلــى عصــر يــوم اجلمعة‬\n‫وتبيــت عنــدي ليلــة األربعــاء وليلــة اخلميــس ونصــف اإلجــازة الصيفيــة ويف‬\n‫شــهر رمضــان مــن منتصفــه وحتــى ثالــث يــوم بعــد عيــد الفطــر تكــون‬\n\n                                                                                        ‫‪306‬‬\n\f      ‫عنــدي كمــا أطلــب عــدم منعهــا مــن أن تتصــل بــي أو أتصــل بهــا يف أي‬\n      ‫وقــت هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‪ :‬أطلــب‬\n      ‫مهلــة إلــى اجللســة القادمــة ويف جلســة أخــرى بتاريــخ ‪1433/09/19‬ه ـ‬\n      ‫حضــر وكيــل املدعــي وحضــر وكيــل املدعــى عليهــا ولــم حتضــر بنــت‬\n      ‫املدعــي (‪ ).....‬وبســؤال املدعــى عليــه وكالــة عــن جوابــه علــى دعــوى‬\n      ‫املدعــي وعــن ســبب عــدم حضــور بنــت املدعــي (‪ ).....‬أجــاب إنــه ســبق‬\n      ‫للمدعــي أصالــة التقــدم بدعــوى مماثلة وقيدت الدعــوى برقم‪3034131‬‬\n      ‫اطلــب ضــم أوراق هــذه القضيــة لســابقتها وأمــا بالنســبة إلــى املوضــوع‬\n      ‫أعــاه فإنــه يشــرفني أن أتقــدم لفضيلتكــم بالوكالــة عــن موكلتــي‬\n      ‫بردنــا علــى مــا جــاء يف دعــوى املدعــي وذلــك علــى النحــو التالــي‪ :‬أو ًال ‪:‬‬\n      ‫فيمــا يتعلــق مبــا ذكــره املدعــي أنــه كان زوج ـ ًا ملوكلتــي وقــد طلقهــا‬\n      ‫وقــد بانــت منــه منــذ ســبع ســنوات وأنهــا أجنبــت لــه علــى فــراش الزوجيــة‬\n      ‫البنــت (‪ ).....‬املولــودة بتاريــخ ‪1421/1/1‬ه ـ فــإن ذلــك صحيــح‪ .‬ثاني ًا ‪ :‬أما‬\n      ‫بخصــوص مــا ذكــره املدعــي مــن أنــه طلــب عــدة مــرات زيــارة ابنتــه لــه‬\n      ‫فرفضــت والدتهــا وأنــه أرســل مــن يســعى للصلــح دون اللجــوء للمحاكــم‬\n      ‫فــإن مــا ذكــره املدعــي غيــر صحيــح ‪ ،‬والصحيــح أن موكلتــي ال متانــع‬\n      ‫مــن زيــارة املدعــي البنتــه وهــي حريصــة كل احلــرص علــى أن ال تنقطــع‬\n      ‫صلــة ابنتهــا بوالدهــا ولكــن املدعــي ومــن بعد أن صدر حكم ســلفكم‬\n      ‫الشــيخ (‪ ).....‬بــرد دعــواه املتعلقــة بحضانــة ابنتــه قطــع صلتــه بابنتــه ولــم‬\n      ‫يعــد يزورهــا أو يتصــل كونهــا اختــارت البقــاء عنــد والدتهــا‪ .‬ثالثـاً‪ :‬لقــد‬\n      ‫ذكــر املدعــي أنــه قــد أرســل مــن يســعى للصلــح دون اللجــوء للقضــاء‬\n      ‫فــإن املدعــي قــد أرســل شــخص ًا مجهــول الهويــة يطلــب منهــا تســليم‬\n      ‫ابنتهــا لوالدهــا فطلبــت منــه موكلتــي التعريــف بنفســه وقامــت بإعطائه‬\n\n\n‫‪307‬‬\n\f‫رقــم هاتــف شــقيقها ولكنــه لــم يتواصــل معــه رابع ـ ًا ‪ :‬بخصــوص مــا‬\n‫طلبــه املدعــي مــن أن تــزوره ابنتــه يف منزلــه مــن الســاعة الواحــدة ظهــر ًا‬\n‫وحتــى الســاعة الرابعــة عصــر ًا طــوال أيــام األســبوع وتبيــت عنــده يــوم‬\n‫األربعــاء واخلميــس إلــى عصــر يــوم اجلمعــة باإلضافــة إلــى زيارتهــا لــه مــن‬\n‫منتصــف شــهر رمضــان وحتــى ثالــث أيــام عيــد الفطــر وعليــه فإننــا‬\n‫جنيــب علــى ذلــك بــأن موكلتــي ال متانــع مــن زيــارة املدعــي البنتــه يف‬\n‫منزلهــا كــون أن ابنتهــا ترفــض وبشــدة أن تذهــب إلــى بيــت والدهــا ملــا‬\n‫جتــده مــن اضطهــاد واعتــداءات متكــررة مــن قبــل زوجــة أبيهــا ووالدتــه‬\n‫وخوفهــا مــن حرمانهــا مــن العــودة لوالدتهــا بعــد انتهــاء فترة زيــارة والدها‬\n‫وقــد تعرضــت ابنــة موكلتــي العتــداء مــن قبــل والــدة املدعــي قامــت‬\n‫بضربهــا أمــام زميالتهــا يف املدرســة وحاولــت أخذهــا بالقــوة‪ ،‬وقــد مت‬\n‫إحالــة املوضــوع إلــى مركــز شــرطة العليــا والتــي بدورهــا أحالــت كامل‬\n‫ملــف التحقيــق إلــى ســلفكم الشــيخ بتاريــخ ‪1430/05/25‬ه ـ خامسـ ًا ‪:‬‬\n‫أمــا فيمــا يخــص طلــب فضيلتكــم إحضــار ابنــة موكلتــي جللســة هــذا‬\n‫اليــوم فــإن ابنــة موكلتــي قــد حضــرت إلــى مكتــب فضيلتكــم مرتــن‬\n‫قبــل املوعــد احملــدد لهــذه اجللســة وطلبــت مقابلتكــم ولــم تتمكــن مــن‬\n‫ذلــك‪ ،‬وقــد زاد رفضهــا للحضــور يف هــذه اجللســة لعلمهــا حضــور زوجــة‬\n‫املدعــي للجلســة املاضيــة أمــام فضيلتكــم وهــي ليســت طرف ـ ًا يف‬\n‫الدعــوى ‪ .‬صاحــب الفضيلــة يتضــح لفضيلتكــم مــن خــال مــا ســبق‬\n‫عــدم صحــة مــا ذكــره املدعــي يف دعــواه مــن منعــه مــن رؤيــة ابنتــه‬\n‫ولكــن هنالــك ظــروف حتتــم مراعــاة مصلحــة هــذه الطفلــة وعــدم‬\n‫الضغــط عليهــا خصوصـ ًا بعــد تعرضهــا العتداءات موضحــة يف محاضر‬\n‫رســمية وقــد أدت هــذه االعتــداءات إلخضاعهــا لعالج نفســي يف مراكز‬\n\n\n                                                                                       ‫‪308‬‬\n\f      ‫متخصصــة‪ ،‬وحيــث إن موكلتــي ال متانــع مــن زيــارة املدعــي البنتــه يف‬\n      ‫منزلهــا فإننــا نرجــو مــن فضيلتكــم النظــر بعــن االعتبــار مــا عانتــه هــذه‬\n      ‫الطفلــة طــوال الفتــرات املاضيــة ‪ ،‬وبســؤال وكيــل املدعــي عــن مــا‬\n      ‫ذكــره وكيــل املدعــى عليهــا أجــاب غيــر صحيــح مــا ذكــره وكيــل‬\n      ‫املدعــى عليهــا يف رد دعــوى موكلــي والصحيــح مــا ذكرنــاه ســابق ًا‬\n      ‫وموكلــي يرفــض مــا طرحــه وكيــل املدعيــة بعــدم املمانعــة مــن زيــارة‬\n      ‫ابنتــه يف منــزل والدتهــا ويطالــب باحلكــم بزيــارة ابنتــه يف بيتــه وعليــه‬\n      ‫قــررت الكتابــة لقســم اخلبــراء لتحديــد مــدة الزيــارة ومكانهــا ويف‬\n      ‫جلســة أخــرى بتاريــخ ‪1434/01/14‬ه ـ وفيهــا حضــر حامــل بطاقــة‬\n      ‫وكيــا عــن ‪ ......‬بصفتــه وكيــا عــن املدعــي بالوكالــة (‪ ).....‬يف‬\n      ‫‪1433/6/9‬ه ـ جلــد ‪ 20481‬الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بالريــاض كمــا حضــر وكيــل املدعــى عليــه واملدعــي أصالــة ووكيلــه‬\n      ‫ووكيــل املدعــى عليهــا احلاضــرون يف جلســات ســابقة وقــد وردنــا قــرار‬\n      ‫قســم اخلبــراء تاريــخ ‪1433/12/26‬ه ـ ونــص احلاجــة منــه (وجــرى عــرض‬\n      ‫الصلــح عليهمــا بشــأن الزيــارة فلــم يصطلحــا وقــد أقــر وكيــل املدعــى‬\n      ‫عليهــا بأنــه ال مانــع لــدى موكلتــه مــن زيــارة املدعــى البنتــه يف منزلهــا‬\n      ‫مبدئي ـ ًا حتــى تتحســن نفســيتها ومــن ثــم ميكــن االتفــاق بعــد حتســن‬\n      ‫نفســيتها بــأن تقــوم بزيــارة والدهــا يف منزلــه نظــر ًا لالعتــداءات التــي‬\n      ‫كانــت تقــع عليهــا وتكــون يومـ ًا واحــد ًا منــزل والدتهــا كمــا يف إقــراره‬\n      ‫املرفــق وأقــر املدعــي برغبتــه يف زيــارة ابنتــه لــه يف بيتــه أســبوعي ًا مــن‬\n      ‫بعــد عصــر يــوم األربعــاء مباشــرة إلــى قبــل صــاة املغــرب مــن يــوم اجلمعــة‬\n      ‫وأمــا اإلجــازات املدرســية فتكــون عنــده يف النصــف األول مــن اإلجــازة‬\n      ‫الصيفيــة كمــا يف إقــراره املرفــق وقــد حضــرت البنــت (‪ ).....‬وأقــرت‬\n\n\n‫‪309‬‬\n\f‫بعــدم رغبتهــا يف زيــارة والدهــا يف منزلــه وذكــرت عــدة أســباب مرفقــة‬\n‫باملعاملــة لــذا فــإن الــذي نــراه إن ثبــت لــدى فضيلــة ناظــر القضيــة مــا‬\n‫ذكرتــه احملضونــة فتكــون الزيــارة يف منــزل والدتهــا يــوم األربعــاء مــن‬\n‫كل أســبوع مــن بعــد صــاة العصــر يــوم األربعــاء حتــى صــاة املغــرب‬\n‫وإن لــم يثبــت ذلــك فتكــون الزيــارة أســبوعي ًا مــن بعــد صــاة العصــر‬\n‫يــوم األربعــاء حتــى صــاة العصــر يــوم اخلميــس ويف اإلجــازات تكــون‬\n‫الزيــارة لــأب يف اإلجــازة الصيفيــة يف الشــهر األول منهــا وهــو شــهر‬\n‫شــعبان كامــا ويف األعيــاد تكــون الزيــارة لــأب يف عيــد األضحــى‬\n‫يأخــذ ابنتــه مــع بدايــة إجــازة عيــد األضحــى ويعيدهــا يــوم األربعــاء‬\n‫األخيــر قبــل الدراســة علــى أن يقــوم املدعي بأخذ ابنتــه لزيارته وإعادتها‬\n‫ملنــزل والدتهــا هــذا مــا لدينا)أه ـ وبعــرض ذلــك علــى املدعــي أصالــة‬\n‫واملدعــى عليــه وكالــة قــال املدعــي أصالــة ال أوافــق علــى تقديــر الزيــارة‬\n‫املرصــودة أعــاه فهــي غيــر كافيــة وال أوافــق علــى القــرار جملــة‬\n‫وتفصيــا فــا يكفــي زيــارة يــوم واحــد ملــدة أربــع وعشــرين ســاعة‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال أوافــق‬\n‫علــى الزيــارة تكــون يف بيــت والدتهــا علــى مــا جــاء يف القــرار املرصــود‬\n‫أعــاه أمــا الذهــاب لبيــت والدهــا فابنتــه ال توافــق علــى ذلــك هكــذا‬\n‫أجــاب وقــد جــرى االطــاع علــى مــا مت إرفاقــه يف قســم اخلبــراء منســوب ًا‬\n‫للبنــت (‪ ).....‬املتضمــن (أنــا ال أرغــب بزيــارة والــدي يف منزلــه وإذا أبــي‬\n‫يرغــب بزيارتــي فليتفضــل عنــدي يف البيــت وذلــك ألســباب منهــا القســوة‬\n‫مــن بابــا وعمــي وجدتــي وأخــاف أال أرجــع ألمــي وتعرضــت للعنــف مــن‬\n‫جدتــي واخلنــق واإلهانــة يف املدرســة ومــا كنــت أقــدر أتنفــس وكانــت‬\n‫مامــا تســاعدني وأنــا أبكــي وكل هــذا أمــام مــن يف املدرســة وأنــي‬\n\n\n                                                                                     ‫‪310‬‬\n\f      ‫أتعالــج نفســي ًا بســبب هــذه احلادثــة وانقطــاع أبــي عــن زيارتــي ‪ 4‬ســنوات‬\n      ‫وأخــاف مــن القســوة واملعاملــة الســيئة مــن زوجــة والــدي) أه ـ وبعــرض‬\n      ‫ذلــك علــى املدعــي أصالــة قــال هــذا غيــر صحيــح هكــذا أجــاب ‪ .‬وهــذا‬\n      ‫وقــد جــرى ســؤاله هــل يســكن مــع زوجتــه احلاليــة يف بيــت مســتقل قــال‬\n      ‫نعــم فأنــا أســكن يف بيــت مســتقل مــع أوالدي وزوجتــي (‪ ).....‬ووالدتــي‬\n      ‫يف بيــت مســتقل لوحدهــا خــارج مدينــة الريــاض هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه وكالــة قــال صحيــح بأنــه يســكن مــع زوجتــه‬\n      ‫احلاليــة وأوالدهــا ولكــن والدتــه تســكن معــه وليســت يف بيــت مســتقل‬\n      ‫هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى صــك احلضانــة الصــادر‬\n      ‫مــن هــذه احملكمــة جلــد ‪19/35‬بتاريــخ ‪1430/10/22‬ه ـ املتضمــن‬\n      ‫حكــم احلضانــة للمدعــى عليهــا بابنــة املدعــي (‪ ).....‬فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وألن الولــد مأمــور باإلحســان لوالديــه فقــد قــال‬\n      ‫اهلل تعالــى ((وقضــى ربــك أال تعبــدوا إال إيــاه وبالوالديــن إحســانا)) وهــو‬\n      ‫محتــاج إلــى أبيــه كمــا هــو محتــاج إلــى أمــه والبنــت محتاجــة إلــى أبيهــا‬\n      ‫يف تزويجهــا وتربيتهــا علــى أهــداف حســنة قــد ال جتدهــا عنــد األم وملــا‬\n      ‫فيــه مــن تربيــة لهــا علــى صلــة الرحــم بأبيهــا وأقاربــه وألن يف مثــل حــال‬\n      ‫اخلصمــن عنــد حصــول الفرقــة بينهمــا قــد حتصــل اخلالفــات وتظهــر‬\n      ‫الدعــاوى الكاذبــة لذلــك كلــه فقــد حكمــت مبــا جــاء يف قســم اخلبراء‬\n      ‫ونصــه (فتكــون الزيــارة أســبوعي ًا مــن بعــد صــاة العصــر يــوم األربعــاء‬\n      ‫حتــى صــاة العصــر يــوم اخلميــس ويف اإلجــازات تكــون الزيــارة لــأب‬\n      ‫يف اإلجــازة الصيفيــة يف الشــهر األول منهــا وهــو شــهر شــعبان كامــا‬\n      ‫ويف األعيــاد تكــون الزيــارة لــأب يف عيــد األضحــى يأخــذ ابنتــه مــع‬\n      ‫بدايــة إجــازة عيــد األضحــى ويعيدهــا يــوم األربعــاء األخيــر قبــل الدراســة‬\n\n\n‫‪311‬‬\n\f‫علــى أن يقــوم املدعــي بأخــذ ابنتــه لزيارتــه وإعادتهــا ملنــزل والدتهــا)) مــع‬\n‫أخــذ كفيــل علــى املدعــي أصالــة يف االلتــزام بإعــادة ابنتــه (‪ ).....‬إلــى‬\n‫والدتهــا بعــد نهايــة فتــرة كل زيــارة وبعــد إعالنــه لــم يقنــع بــه املدعــي‬\n‫أصالــة وكذلــك لــم يقنــع بــه املدعــى عليــه وكالــة وطلبــا متيــزه واســتعد‬\n‫التقــدمي الئحــة اعتراضيــة فأفهمــا بــأن عليهمــا مراجعــة احملكمــة يــوم‬\n‫االثنــن ‪1434/1/19‬ه ـ الســتالم نســخة مــن احلكــم وأن لهمــا مــدة‬\n‫ثالثــن يوم ـ ًا تبــدأ مــن موعــد اســتالم نســخة احلكــم وإذا انتهــت املــدة‬\n‫ولــم يقدمــا خاللهــا الئحتهمــا االعتراضيــة فيســقط حــق مــن لــم يعتــرض‬\n‫ويكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/01/14‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/02/13‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي وقــدم الئحتــه االعتراضيــة‬\n‫املقيــدة يف احملكمــة برقــم يف ‪1434/2/13‬ه ـ واملكونــة مــن ســبع‬\n‫ورقــات مكتوبــة باحلاســب اآللــي مــع مرفقاتهــا وقــد رفعــت اجللســة‬\n‫لدراســتها ويف جلســة أخــرى بتاريــخ ‪1434/2/17‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر وكيــل املدعــى عليهــا وقــدم الئحتــه االعتراضيــة املقيــدة‬\n‫يف احملكمــة برقــم يف ‪1434/2/17‬ه ـ واملكونــة مــن ورقتــن مكتوبــة‬\n‫باحلاســب اآللــي مــع مرفقاتهــا وقــد رفعــت اجللســة لدراســتها ويف جلســة‬\n‫أخــرى بتاريــخ ‪1434/4/2‬ه وفيهــا حضــر املدعــي أصالــة وحضر وكيله‬\n‫كمــا حضــر املدعــى عليــه وكالــة احلاضــرون يف جلســة ســابقة وبعــد‬\n‫االطــاع علــى الالئحــة املقدمــة مــن املدعــى عليــه وكالــة جــرى ســؤاله‬\n‫عــن القضيــة التــي يذكــر بأنــه مســجل فيهــا بــاغ ضــد املدعــي ووالدتــه‬\n‫بشــأن االعتــداء علــى ابنتــه (‪ ).....‬فقــال إن املعاملــة لــدى إدارة احلقــوق‬\n\n\n                                                                                        ‫‪312‬‬\n\f      ‫املدنيــة وســوف أحضــر رقمهــا غــدا لطلبهــا منكــم مــن احلقــوق املدنيــة‬\n      ‫لالطــاع عليهــا لوجــود مــا يؤثــر فيهــا علــى احلكــم هكــذا أجــاب ويف‬\n      ‫جلســة أخــرى بتاريــخ ‪1434/5/6‬ه ـ حضــر املدعــي أصالــة وحضــر‬\n      ‫وكيلــه كمــا حضــر املدعــى عليــه وكالــة احلاضــرون يف جلســة ســابقة‬\n      ‫وقــد ســبق الكتابــة ملديــر إدارة تنفيــذ األحــكام احلقوقيــة برقــم (‪).....‬‬\n      ‫وتاريــخ ‪1434/04/06‬ه ـ لتزويدنــا ببيانــات املدعــى عليــه وكالــة ولــم‬\n      ‫تردنــا اإلفــادة حتــى تاريخــه ويف جلســة أخــرى بتاريــخ ‪1434/06/25‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n      ‫احلاضــران يف اجللســة الســابقة‪ ،‬وقــد ســبق الكتابــة ملديــر إدارة تنفيــذ‬\n      ‫األحــكام احلقوقيــة برقــم (‪ ).....‬وتاريــخ ‪1434/04/06‬ه لتزويدنــا‬\n      ‫ببيانــات املدعــى عليــه وكالــة ولــم تردنــا اإلفــادة حتــى تاريخــه‪ ،‬كمــا‬\n      ‫قــرر املدعــى عليــه وكالــة بــأن قــام مبراجعــة إدارة تنفيــذ األحــكام‬\n      ‫احلقوقيــة ومت إفادتــه بــأن املعاملــة صــدرت إلــى احملكمــة ‪ ،‬ومبراجعــة‬\n      ‫االتصــاالت اإلداريــة يف احملكمــة أفــاد املوظــف بــأن املعاملــة قــد‬\n      ‫أحيلــت باخلطــأ لدائــرة التنفيــذ الثانيــة وقــد أبــرز ورقــة املراجعــة التــي‬\n      ‫تثبــت ذلــك وأنهــا أحيلــت لدائــرة التنفيــذ برقــم القيــد ‪ 341484344‬يف‬\n      ‫‪1434/06/21‬هــ‪ ،‬كمــا تعهــد املدعــى عليــه وكالــة مبراجعــة دائــرة‬\n                                                           ‫التنفيــذ إلحالتهــا ملكتبنــا‪.‬‬\n      ‫ويف جلســة أخــرى بتاريــخ ‪1434/07/10‬ه ـ حضــر املدعــي أصالــة‬\n      ‫ووكيلــه واملدعــى عليــه وكالــة احلاضــرون يف اجللســة الســابقة‪،‬‬\n      ‫وجــرى ســؤال املدعــى عليــه وكالــة عــن املعاملــة التــي وعــد بإحضارهــا‬\n      ‫والتعقيــب عليهــا يف اجللســة الســابقة ‪ ،‬فقــال إن املعاملــة بعــد مراجعــة‬\n      ‫قســم صحائــف الدعــوى قالــوا بأنهــا مفقــودة ويطلبــون مهلــة للبحــث‬\n\n\n‫‪313‬‬\n\f‫عنهــا هكــذا قــرر‪ ،‬ونظــرا لعــدم إحضــار املدعــى عليــه وكالــة بينتــه‬\n‫والتــي طلــب املهلــة مــن أجــل إحضارهــا أكثــر مــن مــرة‪ ،‬ممــا يعــد ذلــك‬\n‫عجــزا عــن إحضارهــا ‪ ،‬ولكــون ذلــك فيــه ضــرر بخصمــه وبنــاء علــى‬\n‫املــادة (‪ )122‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ‪ ،‬وبعــد‬\n‫االطــاع علــى الالئحتــن االعتراضيتــن املقدمتــن مــن املدعــي واملدعــى‬\n‫عليــه وكالــة واملشــار لهمــا يف جلســات ســابقة لــم يظهــر لــي ســوى مــا‬\n‫حكمــت بــه وقــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيقــه‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/10‬ه ـ‬\n‫احلمد هلل وحده وبعد يف هذا اليوم الثالثاء ‪1434/09/01‬هـ وقد عادت‬\n‫املعاملــة مــن محكمــة االســتئناف بكتابهــم وتاريــخ ‪1434/08/14‬ه ـ‬\n‫وبرفقــه القــرار وتاريــخ ‪1434/7/30‬ه ـ الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية الثانيــة املتضمــن مــا نصــه (وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحتــن االعتراضيتــن وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى‬\n‫احلكــم ) اهــ‪ .‬وكــي ال يخفــى جــرى إحلاقــه ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                               ‫ســلم علــى محمــد‪ ،‬حــرر يف ‪1434/09/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض وتاريــخ ‪1433/7/11‬ه ـ املرفــق بهــا الصــك الصــادر من فضيلة‬\n‫القاضــي باحملكمــة الشــيخ(‪ ).....‬وتاريــخ ‪1434/1/17‬ه ـ اخلــاص‬\n‫بدعــوى يف قضيــة زيــارة أوالده وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحتــن‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫االعتراضيتــن وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":305,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2fa340bf2cfb9a2e68edb1296e8c104d1834dd5e19f7f98aee075a63e12f0c12","normalized_text_hash":"923ae917b01de3f16bf675f91181ec5096fadc09d1154489ce2a507c277f30a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p305-3413376"},{"id":"46cce139-f652-5479-bfc6-c1885fedc1a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"زيارة -املطالبة بزيارة أم البنتها وحتديد وقت لذلك -وافق املدعى عليه على الطلب واختلفا يف طريقة الزيارة -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب قرار اخلبراء- حكم الزيارة مشمول بالنفاذ املعجل .","document_number":"3410413","case_number":"3267845","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"زيارة -املطالبة بزيارة أم البنتها وحتديد وقت لذلك -وافق املدعى عليه على الطلب واختلفا يف طريقة الزيارة -حتديد الزيارة ووقتها عن طريق قسم اخلبراء -احلكم مبوجب قرار اخلبراء- حكم الزيارة مشمول بالنفاذ املعجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3410413 :‬‬\n                   ‫َر ْق ُم الدعوى‪3267845 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34201776‬تاريخه‪1434/4/3:‬هـ‬\n\n\n‫زيــارة ‪ -‬املطالبــة بزيــارة أم البنتهــا وحتديــد وقــت لذلــك ‪ -‬وافــق املدعى‬\n‫عليــه علــى الطلــب واختلفــا يف طريقــة الزيــارة ‪ -‬حتديــد الزيــارة‬\n‫ووقتهــا عــن طريــق قســم اخلبــراء ‪ -‬احلكــم مبوجــب قــرار اخلبــراء‪-‬‬\n                               ‫حكــم الزيــارة مشــمول بالنفــاذ املعجــل ‪.‬‬\n\n\n\n\n‫‪ -1‬قــال اهلل تعالــى (وقضــى ربــك أال تعبــدوا إال إيــاه وبالوالديــن‬\n                                                                     ‫إحســانا)‬\n‫‪ -2‬قــول الرســول صلــى اهلل عليــه وســلم مــن أولــى النــاس بصحبتــي‬\n‫قــال (امــك قــال ثــم مــن قــال أمــك قــال ثــم مــن قــال أمــك قــال ثــم‬\n                                                             ‫مــن قــال أبــوك)‪.‬‬\n                     ‫‪-3‬املادة رقم ‪ 199-198‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت أم بدعواهــا ضــد مطلقهــا تطالبــه بتمكينهــا مــن زيــارة ابنتهــا ‪-‬‬\n‫صــادق املدعــى عليــه علــى دعــوى املدعيــة ووافــق علــى طلبهــا ‪ -‬اختلــف‬\n‫الطرفــان علــى وقــت الزيــارة ‪ -‬كتبــت احملكمــة لهيئــة النظــر لديهــا‬\n‫فاجتمعــت الهيئــة بالطرفــن وقــررت حتديــد موعــد الزيــارة ووافقــت‬\n‫املدعيــة علــى قــرار الهيئــة يف حتديــد الزيــارة ورفضــه املدعــى عليــه‬\n\n                                                                                   ‫‪316‬‬\n\f      ‫بحجــة انــه وقــت طويــل وفيــه مبيــت ويرفــض مبيــت ابنتــه عنــد والدتهــا‬\n      ‫‪ -‬حكمــت احملكمــة مبوجــب قــرار هيئــة النظــر والزمــت األب بــأن‬\n      ‫يقــوم هــو بإيصالهــا إلــى بيــت أمهــا وان تكــون املدعيــة هــي املســؤولة‬\n      ‫عــن إعادتهــا وكان احلكــم مشــمو ًال بالنفــاذ املعجــل بــدون كفالــة بنــاء‬\n      ‫علــى املــادة ‪ 199/198‬مــن نظــام املرافعــات الشــرعية ‪ -‬لــم يقنــع املدعــى‬\n                                                              ‫عليــه ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامة‪/‬املســاعد وتاريــخ ‪1432/03/05‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n      ‫‪1432/3/5‬ه وفيهــا حضــرت املدعيــة (‪ ).....‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي (‪ ).....‬وحضــر أخوهــا املعــرف لها (‪ ).....‬ســعودي اجلنســية‬\n      ‫وحضــر حلضــوره (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬قائلــة يف دعواهــا ‪ ......‬املدعــى عليــه هــو مطلقــي مبوجــب الصــك‬\n      ‫الشــرعي الصــادر مــن قبــل احملكمــة العامــة بالريــاض رقــم (‪).....‬‬\n      ‫وتاريــخ ‪1432/11/27‬ه ـ وقــد أجنبــت منــه علــى فــراش الزوجيــة بنت ـ ًا‬\n      ‫واحــدة اســمها (‪ ).....‬املولــودة بتاريــخ ‪1419/02/23‬ه ـ وألن البنــت‬\n      ‫يف حضانــة ورعايــة والدهــا أرغــب يف حتديــد وقــت لزيارتهــا لــي هــذه‬\n      ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه صــادق علــى صحتــه الدعــوى‬\n      ‫جملــة وتفصيــا وقــرر بأنــه ال مانــع لــدي مــن حتديــد وقــت لزيــارة ابنتنــا‬\n      ‫لهــا وهكــذا أجــاب ثــم قــرر الطرفــان أن هنــاك جلســة لــدى هيئــة‬\n      ‫النظــر يــوم الثالثــاء ‪1433/08/27‬ه ـ لتحديــد وقــت الزيــارة ومــا يتعلــق‬\n\n‫‪317‬‬\n\f‫بشــؤون البنــت وتطلــب اإلمهــال حتــى ذلــك احلــن فأجيــب لطلبهــا ويف‬\n‫جلســة أخــرى حضــرت (‪ ).....‬ســعودية وحضــر أخوهــا املعــرف لهــا (‪).....‬‬\n‫ســعودي ســجل رقــم (‪ ).....‬وحضــر حلضــوره (‪ ).....‬ســجل رقــم(‪ ).....‬وقــد‬\n‫وردنــا خطــاب هيئــة النظــر قــرار رقــم (‪ ).....‬وتاريــخ ‪1433/11/08‬ه ـ‬\n                       ‫واملتضمــن مــا نصــه قــرار وتاريــخ ‪1433/11/02‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ...‬وبعــد ‪:‬‬\n‫بنــاء علــى خطــاب فضيلــة القاضــي وتاريــخ ‪1433/07/20‬ه ـ بخصــوص‬\n‫دعــوى (‪ ).....‬ضــد (‪ ).....‬ومطالبــة املدعيــة بزيــارة ابنتهــا (‪ ).....‬وطلــب‬\n‫فضيلتــه حتديــد وقــت الزيــارة املناســبة نفيــد فضيلتــه انــه جــرى اجللــوس‬\n‫مــع الطرفــن ومداولــة الصلــح بينهمــا يف أكثــر مــن جلســة ولــم نتوصــل‬\n‫إلــى حــل ينهــي النــزاع القائــم بينهمــا وقــد طالبــت املدعيــة أن تكــون‬\n‫الزيــارة يومــن باألســبوع أمــا املدعــى عليــه فإنــه ال مانــع لديــه مــن متكني‬\n‫املدعيــة مــن زيــارة ابنتهــا يف آخــر جمعــة مــن كل شــهر وإذا أرادت‬\n‫املدعيــة زيــارة ابنتهــا يف مــدة اقــل مــن ذلــك فإنــه ال مانــع لديــه بشــرط ان‬\n‫تأتــي لزيارتهــا يف منزلــه وبرفقتهــا أحــد محارمهــا متــى مــا أرادا ذلــك مــا‬\n‫عــدا يــوم اخلميــس كل ذلــك جــاء بإقراريهمــا املرفقــن بطــي املعاملة ويف‬\n‫يــوم األربعــاء املوافــق ‪1433/10/25‬ه ـ حضــرت البنــت محــل الدعــوى‬\n‫برفقــة والدهــا املدعــى عليــه وأقــر أنهــا تطلــب زيــارة والدتهــا يــوم اجلمعــة‬\n‫أســبوع بعــد أســبوع وأن يكــون الوقــت مــن الســاعة السادســة مســاء‬\n‫إلــى الســاعة الثامنــة مســاء مــن نفــس اليــوم كمــا ذكــرت أن والدهــا‬\n‫ليــس لــه أي ضغــوط عليهــا أو تدخــل بخصــوص حتديــد الزيــارة وجتــدون‬\n‫إقرارهــا بطــي املعاملــة ويف يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ‬\n‫حضــرت املدعيــة إلــى مكتبنــا وجــرى اطالعهــا علــى مــا كتبــت ابنتهــا‬\n\n\n                                                                                         ‫‪318‬‬\n\f      ‫بخصــوص الزيــارة وأفــادت أن مــا كتبتــه ابنتهــا جــراء ضغــوط مــن‬\n      ‫والدهــا كمــا ذكــرت أن البنــت عاشــت معهــا وبحضانتهــا مــدة اثنــي‬\n      ‫عشــرة ســنة وكانــت متعلقــة بهــا أمــا والدهــا فــا يزورهــا تلــك الفتــرة إال‬\n      ‫نــادر ًا وكانــت تخــاف منــه كثيــر ًا إضافــة إلــى أن البنــت تســكن حاليـ ًا‬\n      ‫مــع والدهــا واخلادمــة فقــط وال تــدري رمبــا تكــون عمتهــا (‪ ).....‬معهــم‬\n      ‫يف املنــزل كمــا أن والدهــا كثيــر اخلــروج مــن املنــزل كمــا ذكــرت‬\n      ‫انــه البــد مــن األخــذ بعــن االعتبــار بــدون النظــر إلــى رغبــة البنــت ألن‬\n      ‫البنــت يف مرحلــة املراهقــة ويعتريهــا مــا يعتــري النســاء فهــي بحاجــة إلــى‬\n      ‫والدتهــا واستشــارتها وكذلــك إرشــادها ملــا فيه مصلحتهــا كما أفادت‬\n      ‫أن البنــت انقطعــت عنهــا ملــدة ثــاث ســنوات ولــم تتمكــن مــن التواصــل‬\n      ‫معهــا إال نــادر ًا أمــا والدهــا فانــه ال يرغــب بزيارتهــا بســبب ان املدعيــة‬\n      ‫طلقــت منــه بــدون رضــاه وقــد ضايقهــا يف عملهــا ورفــع عليهــا اكثــر مــن‬\n      ‫قضيــة يف احملكمــة اجلزائيــة والعامــة وكلهــا حكــم بصــرف النظــر‬\n      ‫عنهــا كمــا أن لديهــا دعــوى بالنفقــة والزيــارة عليــه كل ذلــك جــاء يف‬\n      ‫إقرارهــا املرفــق بطــي املعاملــة والــذي نــراه بعــد اجللــوس مــع الطرفــن‬\n      ‫بأكثــر مــن جلســة والتأمــل يف حالهمــا ومــا جــاء يف إقرارهمــا وإقــرار‬\n      ‫البنــت أن تكــون الزيــارة يــوم اخلميــس مــن الســاعة اخلامســة عصــر ًا‬\n      ‫حتــى يــوم اجلمعــة الســاعة اخلامســة عصــرا وذلــك لعظــم حــق األم ومــا‬\n      ‫جــاء يف عمــوم األدلــة الــواردة عنــه عليــه الصــاة والســام بحــق األم ومــن‬\n      ‫ذلــك قولــه للرجــل الــذي ســأله ‪ :‬مــن أولــى النــاس بصحبتــي يــا رســول‬\n      ‫اهلل قــال أمــك قــال ثــم مــن قــال أمــك قــال ثــم مــن قــال أمــك قــال ثــم مــن‬\n      ‫قــال أبــوك والبــد مــن تربيــة البنــت علــى النهــج الصحيــح وهــو معرفــة‬\n      ‫قــدر والدتهــا وأن زيارتهــا أســبوع بعــد أســبوع كمــا طالبــت البنــت فيــه‬\n\n\n‫‪319‬‬\n\f‫محــذور شــرعي حيــث انــه ليــس مــن البــر واإلحســان الــذي أمــر اهلل بــه‬\n‫وحــث عليــه رســوله صلــى اهلل عليــه وســلم ( وقضــى ربــك أال تعبــدوا‬\n‫إال إيــاه وبالوالديــن إحســاناً) ‪ .‬هــذا مــا لدينــا واهلل يحفظكــم أعضــاء‬\n‫مكتــب الصلــح وتوقيعــه و وتوقيعــه ) أ‪.‬هــ‪ .‬وبعرضــه علــى الطرفــن‬\n‫قــررا موافقتهمــا علــى ذلــك علــى أن يكــون اللقــاء عصــر يــوم األربعــاء‬\n‫إلــى عصــر يــوم اخلميــس مــن كل أســبوع ثــم عــاد األب وقــرر رغبتــه‬\n‫أن يكــون الزيــارة مــن بعــد يــوم األربعــاء إلــى عصــر اخلميــس ولكــن‬\n‫كل أســبوعني هكــذا أجــاب عليــه وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وملــا تضمنــه نقــرر هيئــة النظــر وهــم أهــل اخلبــرة ومــا ورد مــن‬\n‫حيثيــات فيــه حيــال حاجــة البنــت إلــى التواصــل مــع أمهــا وبرهــا وان‬\n‫هــذا يقتضــي التواصــل القريــب ال البعيــد خصوصــا مــع بلــوغ البنــت هــذه‬\n‫الســن لذلــك كلــه وبنــاء علــى املــادة ‪ 199 - 198‬مــن نظــام املرافعــات‬\n‫فقــد حكمــت بزيــارة البنــت (‪ ).....‬ألمهــا كل أســبوع مــن عصــر يــوم‬\n‫األربعــاء إلــى عصــر يــوم اخلميــس علــى أن يكــون املســؤول عــن إيصالهــا‬\n‫ألمهــا هــو والدهــا واملســؤول عــن إعادتهــا لوالدهــا هــي أمهــا وذلــك‬\n‫حكمــا مشــموال بالنفــاذ املعجــل بــدون كفالــة فقنعــت املدعيــة ولــم‬\n‫يقنــع املدعــى عليــه فافهــم بــان لــه أن يتقــدم باعتراضــه علــى احلكــم‬\n‫مــن تاريــخ اســتالم نســخة احلكــم وهــو هــذا اليــوم ‪1434/01/12‬ه ملــدة‬\n‫ال تتجــاوز ثالثــون يومــا ففهــم ذلــك إذا لــم يقــدم االعتــراض خــال املــدة‬\n‫فإنــه يســقط حــق االعتــراض ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل‬\n         ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/1/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء املوافق‪1434/05/22‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 08.15‬وقــد عــادت املعاملــة مــن محكمــة‬\n\n\n                                                                                      ‫‪320‬‬\n\f      ‫االســتئناف وبرفقهــا قــرار دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n      ‫وتاريــخ ‪1434/04/03‬ه ـ واملتضمــن‪ :‬أنــه بدراســة الصــك وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n      ‫باألكثريــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى مراعــاة تدويــن شــرح‬\n      ‫اطالعــه علــى الالئحــة االعتراضيــة وذلــك يف الضبــط حســب التعليمــات‬\n      ‫ال ‪ ).....( .‬ختمــه وتوقيعــه ‪ ).....( ،‬ختمــه وتوقيعــه ‪ ).....( ،‬ختمــه‬\n                                                                              ‫مســتقب ً‬\n      ‫وتوقيعــه ‪ .‬اهــ‪ .‬وبذلــك يكــون احلكــم قــد اكتســب القطعيــة وحتــى ال‬\n      ‫يخفــى جــرى تدوينــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة املســاعد‬\n      ‫وتاريــخ ‪1434/4/13‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n      ‫باحملكمــة الشــيخ (‪ ).....‬وتاريــخ ‪1434/1/12‬ه ـ اخلــاص بدعــوى‬\n      ‫(‪ ).....‬يف قضيــة زيــارة أوالده وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة باألكثريــة علــى‬\n      ‫احلكــم مــع تنبيــه فضيلتــه إلــى مراعــاة تدويــن شــرح اطالعــه علــى‬\n      ‫ال‬\n      ‫الالئحــة االعتراضيــة وذلــك يف الضبــط حســب التعليمــات مســتقب ً‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪321‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                  ‫املوضوع‬                   ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة الزوجة بسداد املؤخر من الصداق‬\n  ‫‪5‬‬      ‫وحلفها بيمني النفي واحلكم على املدعى‬      ‫صداق‬     ‫‪1‬‬\n                   ‫عليه بدفع املؤخر‬\n\n\n         ‫مطالبة الزوجة بصداق مؤخر وتكاليف‬\n           ‫احلفل حيث وقع الطالق قبل الدخول‬\n  ‫‪9‬‬                                                ‫صداق‬     ‫‪2‬‬\n           ‫باقرار املتداعيني وإلزام املدعى عليه‬\n         ‫(الزوج) بدفع نصف املهر وتكاليف احلفل‬\n\n\n           ‫طلب أرملة مبؤخر صداقها وما أضيف‬\n  ‫‪15‬‬      ‫عليه من زيادة من التركة وإثبات صحة‬       ‫صداق‬     ‫‪3‬‬\n                 ‫دعواها بشاهد وميينها‬\n\n\n          ‫مطالبة الزوجة زوجها بدفع املهر املتفق‬\n  ‫‪24‬‬     ‫عليه وسماع الدعوى غيابي ًا واحلكم على‬     ‫صداق‬     ‫‪4‬‬\n                       ‫الزوج بدفع املهر‬\n\n\n          ‫املطالبة باملهر بعد طالق الزوجة حسب‬\n          ‫العادات والتقاليد القبلية يف باكستان‬\n  ‫‪32‬‬                                               ‫صداق‬     ‫‪5‬‬\n             ‫واحلكم برد الدعوى لعدم ثبوتها‬\n                ‫وملخالفتها أحكام الشريعة‬\n\n\n            ‫مطالبة الزوجة لزوجها بعد الطالق‬\n          ‫برد ذهبها حيث أخذه وال بينة للمدعية‬\n  ‫‪44‬‬                                               ‫صداق‬     ‫‪6‬‬\n         ‫ورفضها ميني املدعى عليه (الزوج) واحلكم‬\n                       ‫برد دعواها‬\n\f‫الصفحة‬                  ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫املطالبة من وكيل الزوجة للمدعى عليه‬\n         ‫(الزوج)بإعادة مبلغ استلمه من وليها مقابل‬\n  ‫‪48‬‬       ‫طالقها حيث وقع الطالق وأثبت بصك‬           ‫صداق‬     ‫‪7‬‬\n            ‫شرعي قبل استالم العوض ومصادقة‬\n           ‫املدعى عليه وإلزامه برد املبلغ للمدعية‬\n\n\n          ‫مطالبة الزوج بإمتام الزواج ومتكينه من‬\n         ‫زوجته ورغبة الزوجة يف عدم أمتام النكاح‬\n  ‫‪59‬‬        ‫من غير سبب ظاهر‪،‬مخالفة الزوجة‬            ‫صداق‬     ‫‪8‬‬\n           ‫لزوجها وإلزامها برد املبالغ التي دفعها‬\n                  ‫الزوج من مهر وشبكة‬\n\n\n          ‫مطالبة مطلقة بالصداق املؤخر ورفض‬\n          ‫الزوج السداد ألن الطالق سببه املرأة‬\n  ‫‪65‬‬                                                 ‫صداق‬     ‫‪9‬‬\n          ‫ومصادقته على عقد النكاح وصك‬\n           ‫الطالق واحلكم عليه بدفع املؤخر‬\n\n\n          ‫مطالبة أم بإثبات عضل األب البنته ونقل‬\n           ‫الوالية إلى األخوة أنكر املدعى عليه‬\n  ‫‪73‬‬      ‫العضل ولم تثبت املدعية ما تدعيها وألن‬      ‫عضل‬      ‫‪10‬‬\n           ‫األصل براءة الذمة وال بينه لديها أخلت‬\n                   ‫احملكمة سبيل األب‬\n\n\n         ‫ادعت ابنة تطالب بإثبات غيبة والدها ورفع‬\n  ‫‪80‬‬      ‫والية تزويجها عنه وجعلها لألخ الشقيق‪.‬‬      ‫عضل‬      ‫‪11‬‬\n                        ‫الضرر يزال‬\n\n\n         ‫عضل األب لبناته وقيام البينة على الدعوى‬\n  ‫‪85‬‬      ‫بالشاهدين املعدلني واحلكم برفع والية‬       ‫عضل‬      ‫‪12‬‬\n              ‫األب الغائب وجعلها لألخ الشقيق‬\n\f‫الصفحة‬                  ‫املوضوع‬                     ‫التصنيف‬      ‫م‬\n\n\n             ‫احلكم بثبوت عضل الولي(األخ)‬\n  ‫‪92‬‬     ‫للمدعيتني بشهادة الشهود العدول وانتقال‬       ‫عضل‬        ‫‪13‬‬\n            ‫والية النكاح إلى احلاكم الشرعي‬\n\n\n         ‫مطالبة البنتني بإثبات عضل والدهما ورفع‬\n           ‫واليته عنهما وجعلها ألخيهما الشقيق‬\n          ‫ومطالبة أم املدعيتني برفع والية األب عن‬\n ‫‪100‬‬                                                  ‫عضل‬        ‫‪14‬‬\n         ‫بقية بناتها حتى ال يتضررن واثبات العضل‬\n         ‫بشهادة الشاهدين وإفادات اخلطاب وجعل‬\n         ‫والية التزويج جلميع البنات ألخيهن الشقيق‬\n\n\n          ‫مطالبة بنت بإلزام والدها بتزويجها أو‬\n           ‫احلكم بعضله رفض والدها تزويجها‬\n             ‫من اخلاطب كونه أجنبي ولشهادة‬\n ‫‪114‬‬      ‫الشهود بصالحيته وكفء اخلاطب ثبت‬             ‫عضل‬        ‫‪15‬‬\n          ‫لدى احملكمة صالحية اخلاطب ورفض‬\n          ‫احملكمة والية األب وجعلتها للحاكم‬\n                        ‫الشرعي‬\n\n\n          ‫مطالبة أخو الزوجة املتوفاة بإحلاق نسب‬\n ‫‪125‬‬                                                ‫إثبات نسب‬    ‫‪16‬‬\n              ‫ابنة أخته بأبيها املدعى عليه‬\n\n\n          ‫طلب إضافة بنت يف دفتر العائلة اخلاص‬\n ‫‪133‬‬                                                ‫إثبات نسب‬    ‫‪17‬‬\n                  ‫بوالدها املدعى عليه‬\n\n\n          ‫مطالبة الزوجة إثبات طالقها من زوجها‬\n            ‫املدعى عليه حيث طلقها ولم يراجعها‬\n           ‫ونفي الزوج لذلك حيث أقر مبراجعتها‬\n ‫‪143‬‬                                                ‫إثبات طالق‬   ‫‪18‬‬\n            ‫وقبول الزوجة لشهادة الشهود ووجود‬\n         ‫القرينة مع ميني املدعية‪،‬حيث تشرع اليمني‬\n                 ‫يف جانب أقوى املتداعيني‬\n\f‫الصفحة‬                   ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫طلب األم حضانة أوالدها حيث لم تتزوج‬\n          ‫بعد الطالق وتسكن يف سكن مستقل‬\n          ‫ومطالبة الزوج بحضانة ابنته ذات األربعة‬\n ‫‪159‬‬                                                  ‫حضانة‬    ‫‪19‬‬\n         ‫عشر عام ًا وتخيير األوالد بني أبيهم وأمهم‬\n         ‫واحلكم بحضانة الطفل ألمه لكونها لم‬\n            ‫تتزوج ولم يبلغ الطفل السن السابعة‬\n\n\n          ‫طلب األب حضانة أوالده ‪ ،‬وأن مطلقته‬\n          ‫(املدعى عليها) ال تصلح حلضانتهم حيث‬\n         ‫أنها ال حتافظ على الصالة وكثرة اخلروج‬\n ‫‪170‬‬       ‫من املنزل ووجود القنوات الفاسدة يف‬         ‫حضانة‬    ‫‪20‬‬\n          ‫منزلها ‪،‬مت تخيير األبناء فقرروا رغبتهم‬\n          ‫اإلقامة مع والدتهم ‪ ،‬واحلكم برد دعوى‬\n                ‫املدعي يف مطالبته باحلضانة‬\n\n\n         ‫طلب األم حضانة ابنها وتخيير االبن بني‬\n ‫‪180‬‬     ‫أمه وأبيه واختياره لوالده واحلكم ألبيه‬       ‫حضانة‬    ‫‪21‬‬\n         ‫بحضانته حيث قد بلغ السابعة من العمر‬\n\n\n         ‫مطالبة الزوج ملطلقته بحضانة ابنته التي‬\n          ‫جتاوزت السبع سنوات وتخيير القاضي‬\n ‫‪185‬‬                                                  ‫حضانة‬    ‫‪22‬‬\n         ‫البنت بني والديها فاختارت أمها‪ ،‬حكم‬\n         ‫القاضي لألم باحلضانة ألنها أحق من األب‬\n\n\n          ‫طلب حضانة بنت جتاوزت السابعة من‬\n          ‫أمها كون أبيها متزوج من عدة نساء‬\n ‫‪191‬‬                                                  ‫حضانة‬    ‫‪23‬‬\n          ‫وطلب أبيها احلضانة ملساومة األم على‬\n                    ‫التنازل عن النفقة‬\n\n\n            ‫طلب حضانة أوالد واحلكم لألم غير‬\n ‫‪196‬‬                                                  ‫حضانة‬    ‫‪24‬‬\n         ‫املتزوجة باحلضانة كونها األحق باحلضانة‬\n\f‫الصفحة‬                  ‫املوضوع‬                    ‫التصنيف‬   ‫م‬\n\n\n          ‫احلكم بحضانة البنات لألم من زوجها‬\n ‫‪203‬‬     ‫املتغيب عن البالد وقد طلقت منه مبوجب‬       ‫حضانة‬    ‫‪25‬‬\n              ‫صك من احملكمة الشرعية‬\n\n\n          ‫طلب اجلد حضانة أوالد ابنه املتوفى وقد‬\n            ‫تزوجت أمهم واحلكم لألم باحلضانة‬\n ‫‪208‬‬     ‫مصلحة لألبناء مع حضور زوج األم وإقراره‬     ‫حضانة‬    ‫‪26‬‬\n            ‫أنه ال مانع من بقاء أوالد زوجته عنده‬\n                     ‫وحتت حضانة أمهم‬\n\n\n           ‫طلب األم حضانة األوالد مع بقاء عقد‬\n            ‫الزوجية حيث ساءت العشرة بينهما‬\n ‫‪213‬‬                                                ‫حضانة‬    ‫‪27‬‬\n            ‫وخرجت الزوجة من بيت الزوجية‪،‬‬\n           ‫واحلكم بالنفاذ املعجل لألم باحلضانة‬\n\n\n          ‫طلب األم حضانة األوالد من بلغ ومن لم‬\n ‫‪217‬‬       ‫يبلغ مع تسليم األوراق الثبوتية وشهادة‬    ‫حضانة‬    ‫‪28‬‬\n                          ‫امليالد‪.‬‬\n\n\n          ‫احلكم بحضانة ابن عمره سبع سنوات‬\n ‫‪223‬‬      ‫لوالدته من دون تخيير بني األب واألم‬       ‫حضانة‬    ‫‪29‬‬\n          ‫لصالحية األم خالف ًا لقاعدة التخيير‬\n\n\n         ‫احلكم باحلضانة لألم كونها األحق حيث‬\n         ‫لم تتزوج وإلزامها بتمكني األب من زيارة‬\n ‫‪227‬‬                                                ‫حضانة‬    ‫‪30‬‬\n            ‫ابنتيه وحتديد مدة الزيارة عن طريق‬\n                         ‫اخلبراء‬\n\f‫الصفحة‬                  ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫طلب اجلدة حضانة بنت ابنتها ورغبة البنت‬\n ‫‪241‬‬      ‫أن تكون عند جدتها ألمها وتفضيلها‬           ‫حضانة‬    ‫‪31‬‬\n          ‫لذلك واألخذ برأي أهل اخلبرة يف ذلك‬\n\n\n          ‫طلب حضانة األوالد من الزوجة الناشر‬\n          ‫واختالف مكان إقامة الوالدين وتخيير‬\n ‫‪247‬‬                                                 ‫حضانة‬    ‫‪32‬‬\n           ‫األوالد بني والدهم ووالدتهم ملن جتاوز‬\n                         ‫السابعة‬\n\n\n         ‫مطالبة مبستندات تخص احملضون (جواز‬\n            ‫سفر وشهادة ميالد) وسفر احلاضنة‬\n ‫‪260‬‬                                                 ‫حضانة‬    ‫‪33‬‬\n         ‫باحملضون لغرض مؤقت ال يؤثر يف حقها‬\n                       ‫يف احلضانة‬\n\n\n            ‫احلكم باستحقاق األم حضانة بنت‬\n ‫‪267‬‬     ‫جتاوزت السابعة رغم زواج األم وعمل األب‬      ‫حضانة‬    ‫‪34‬‬\n                   ‫خارج مقر سكنه‬\n\n\n         ‫مطالبة األب املدعي ابنته البالغة (املدعى‬\n ‫‪274‬‬      ‫عليها) الغير متزوجة بتسليم نفسها له‬        ‫حضانة‬    ‫‪35‬‬\n                        ‫خوف ًا عليها‬\n\n\n          ‫املطالبة بحضانة أوالد بالغني وصرف‬\n ‫‪281‬‬      ‫النظر عن ذلك واحلكم بحضانة البنت‬           ‫حضانة‬    ‫‪36‬‬\n            ‫الغير بالغة ألمها كونها لم تتزوج‬\n\n\n         ‫طلب العمة حضانة أوالد أخيها لزواج األم‬\n ‫‪285‬‬     ‫وعملها وموافقة زوج األم على حضانة األم‬      ‫حضانة‬    ‫‪37‬‬\n           ‫ألوالدها وحترير ذلك يف عقد النكاح‬\n\f‫الصفحة‬                   ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n           ‫حضانة بنات دون السابعة ألمهم رغم‬\n ‫‪293‬‬      ‫تنازلها عن احلضانة مقابل اخللع كونه‬         ‫حضانة‬    ‫‪38‬‬\n                      ‫األصلح لهن‬\n\n\n         ‫مطالبة األب بزيارة ابنته وحتديد الزيارة‬\n ‫‪305‬‬                                                  ‫زيارة‬    ‫‪39‬‬\n              ‫ووقتها عن طريق قسم اخلبراء‬\n\n\n         ‫املطالبة بزيارة أم ألبنتها وحتديد الزيارة‬\n ‫‪316‬‬      ‫ووقتها عن طريق قسم اخلبراء واحلكم‬           ‫زيارة‬    ‫‪40‬‬\n                        ‫مبوجبه‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":316,"source_page_end":328,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b0e241a754a2a1ec9d30fd06a5421fe9463590cbe67f3383e4064c97952055f0","normalized_text_hash":"43150b3c3bbeca2473554546b694e976252a1a452dfdd24296252fd1bf74da5c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p316-3410413"},{"id":"cb8bc7a0-f55d-51bd-a937-745ee1480a5a","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة طفل -املطالبة بنفقة الطفل من والدته -دفع املدعى عليه بامتناعه عن النفقة المتناع الزيارة البنته -صرف النظر عن طلب األم نفقة ابنتها املاضية من األب ألنها لم تنو الرجوع بالنفقة عليه .","document_number":"347261","case_number":"3333621","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/10","year":"1434","subject":"نفقة -نفقة طفل -املطالبة بنفقة الطفل من والدته -دفع املدعى عليه بامتناعه عن النفقة المتناع الزيارة البنته -صرف النظر عن طلب األم نفقة ابنتها املاضية من األب ألنها لم تنو الرجوع بالنفقة عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/1/10 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪347261 :‬‬\n                       ‫َر ْق ُم الدعوى‪3333621 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 34277428‬تاريخه‪1434/7/24 :‬هـ‬\n\n\n\n    ‫نفقــة‪ -‬نفقــة طفــل‪ -‬املطالبــة بنفقــة الطفــل مــن والدتــه‪ -‬دفــع املدعــى‬\n    ‫عليــه بامتناعــه عــن النفقــة المتنــاع الزيــارة البنتــه‪ -‬صــرف النظــر‬\n    ‫عــن طلــب األم نفقــة ابنتهــا املاضيــة مــن األب ألنهــا لــم تنــو الرجــوع‬\n                                                                  ‫بالنفقــة عليــه ‪.‬‬\n\n\n\n    ‫مــا قــرره الفقهــاء مــن أن نفقــه األقــارب مــن آبــاء وابنائهــم وغيرهــم‬\n    ‫تســقط أذا انفــق غيــر مــن جتــب عليــه النفقــة عليهــم بغيــر نيــة الرجــوع‬\n    ‫جــاء يف كشــاف القنــاع (‪( )161/13‬ولــو امتنــع زوج أو قريــب مــن نفقــة‬\n    ‫واجبــة بــأن تطلــب منــه النفقــة فيمتنــع فقــام بهــا غيــره رجــع عليــه‬\n                                                            ‫منفــق بنيــة الرجــوع)‬\n\n\n\n\n    ‫ادعــت املدعيــة علــى املدعــى عليــه وكالــة بــأن موكلــه تزوجهــا ثــم‬\n    ‫طلقهــا بعــد أن أجنبــت لــه طفلــة وأنــه مــن تاريــخ والدة الطفلــة حتــى‬\n    ‫أخذهــا والدهــا لــم ينفــق عليهــا ســوى ألــف ومائتــن وخمســن ريــاالً‪،‬‬\n    ‫طلبــت املدعيــة إلــزام املدعــى عليــه بدفــع نفقــه ابنتهــا عــن املــدة املاضية‪،‬‬\n    ‫صــادق املدعــى عليــه وكالــة علــى مــا جــاء يف الدعــوى ودفــع بــأن ســبب‬\n    ‫امتنــاع موكلــه مــن النفقــة هــو منعــه مــن زيــارة ابنتــه‪ ،‬أبــرزت املدعيــة‬\n\n‫‪5‬‬\n\f‫ورقــة الصلــح واالتفــاق ومت رصــد مضمونهــا‪ ،‬جــرى ســؤال املدعيــة هــل‬\n‫كانــت تنــوي الرجــوع بالنفقــة على املدعى عليه قالت الســوى يف الشــهر‬\n‫األخيــر قبــل أن يأخــذ املدعــى عليــه ابنتــه‪ ،‬جرى تقدير نفقه هذا الشــهر‬\n‫عــن طريــق هيئــة النظــر‪ ،‬حيــث إن املطالبــة بالنفقــة تســقط إذا لــم ينــو‬\n‫املنفــق الرجــوع بالنفقــة علــى مــن جتــب عليــه لــذا صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بــأن يدفــع للمدعيــة نفقــة الشــهر األخيــر وصــرف النظــر‬\n‫عمــا زاد عــن ذلــك ممــا جــاء يف دعــوى املدعيــة‪ ،‬اعترضــت املدعيــة علــى‬\n                     ‫احلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بنجــران املســاعد برقــم ‪ 3333621‬وتاريــخ ‪ 1433/01/12‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3385627‬وتاريــخ ‪ 1433/01/12‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافق‪1433/02/10‬ه ـ حضــرت ‪ ...‬ســعودية اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬واملعــرف بهــا مــن قبــل اخيهــا ‪ ...‬مدعيــة‬\n‫علــى ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...‬الغائــب عــن‬\n‫مجلــس احلكــم وحضــر بالوكالــة عنــه ‪ ...‬ســعودي اجلنســية رقــم ‪...‬‬\n‫مبوجــب صــك الوكالــه رقــم‪ 34154‬بتاريــخ ‪1425/11/17‬ه ـ والتــي‬\n‫تخولــه حــق املرافعــة واملدافعــة لــدى احملكمــة ضــد طليقتــه ‪...‬قائلــة يف‬\n‫دعواهــا تزوجــت املدعــى عليــه ‪ ...‬يف عــام ‪1417‬ه ـ واجنبــت منــه ابنــة‬\n‫إســمها ‪ ...‬وعمرها االن ‪13‬ســنه وطلقني يف ‪1420/12/29‬هـ ولم ينفق‬\n‫علــى ابنتــي منــذ والد تهــا إال ألــف ومائتــن وخمســن ريــاال حتــى هــذا‬\n\n                                                                                    ‫‪6‬‬\n\f    ‫اليــوم أطلــب إلزامــه بالنفقــة املاضيــة علــى ابنتــي هــذه دعــواى وبعــرض‬\n    ‫ا ماذكرتــه‬     ‫ماجــاء يف الدعــوى علــى املدعــى عليــه وكالــة أجــاب قائ ـ ً‬\n    ‫املدعيــة صحيــح جملــة وأمــا التفصيــل فقــد أنفــق موكلــي علــى ابنتــه‬\n    ‫يف بدايــة االمــر النــه كان بينــه وبــن طليقتــه اتفــاق أن ينفــق علــى أن‬\n    ‫ميكنــوه مــن الزيــاره فبعــد إخاللهــم بالشــرط لــم يســتلموا بعدهــا شــيئا‬\n    ‫فقــد رفضــوا اســتالم النفقــة وتســليم البنــت للزيــارة ثــم ابــرزت املدعيــة‬\n    ‫ورقــة الصلــح واالتفــاق ووجــد أنهــا تتضمــن االتفــاق بــن وكيــل املدعيــة‬\n    ‫اخيهــا ‪...‬احلاضــر وطليقهــا ‪...‬واإلتفــاق يتضمــن أن ينفــق املدعــى عليــه‬\n    ‫‪...‬علــى ابنتــه مببلــغ ألفــن وخمســمائه ريــال ســنويا ويحــق لــي أخــذ البنــت‬\n    ‫للزيــاره يف كل شــهر وبعــرض الورقــه علــى املدعى عليــه وكاله صادقه‬\n    ‫عليهــا وبســؤال املدعيــة عــن ســبب منعــه للمدعــى عليــه‪ ...‬مــن زيــارة ابنتــه‬\n    ‫ومنعــه مــن اســتالم النفقــة أجابــت أنــا لــم أمنعــه مــن ذلــك ولكنــه لــم‬\n    ‫يــأت ألخذهــا ولــم يــأت لتســليم النفقــة هكــذا أجابــت وبســؤال املدعــى‬\n    ‫عليــه وكالــة عــن بيناتــه يف منعــه لــه بالزيــارة واســتالم النفقــة أجــاب‬\n    ‫بأنــه ال ميلــك ســوى شــاهد واحــد يشــهد بذلــك اســمه ‪ ...‬ثــم جــرى ســؤال‬\n    ‫املدعيــة عــن نفقتهــا علــى إبنتهــا هــل كانــت بينــة الرجــوع علــى والدهــا‬\n    ‫فقالــت ال حتــى شــهر جمــادى الثانيــة مــن عــام ‪1432‬ه ـ ويف شــهر رجــب‬\n    ‫مــن نفــس العــام أخــذ البنــت ولــم يرجعهــا حتــى تاريخــه ثــم رفعــت اجللســة‬\n    ‫للكتابــة لهيئــة النظــر لتقديــر النفقــة الشــهرية للبنــت مــع مراعــاة راتــب‬\n    ‫والدهــا ويف جلســة أخــرى حضــرت املدعيــة بتعريــف أخيهــا ‪...‬املضبوطــة‬\n    ‫هويتهمــا ســابق ًا وحضــر حلضورهــا وكيــل املدعــى عليــه املضبوطــة‬\n    ‫هويتــه ســابق ًا وقــد عــادت املعاملــة مــن هيئــة النظــر وبرفقهــا القــرار‬\n    ‫املتضمــن تقديرهــم للنفقــة باالشــهر االخيــرة بســتمائة ريــال ســعودي عــن‬\n\n\n‫‪7‬‬\n\f‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعيــة‬     ‫كل شــهر فبنـ ً‬\n‫بإنفاقهــا علــى ابنتهــا بغيــر نيــة الرجــوع علــى والــد الفتــاة اال يف شــهر‬\n‫جمــادي الثانيــة مــن عــام ‪1432‬ه ـ حيــث انتقلــت الفتــاة لبيــت والدهــا‬\n‫يف الشــهر الــذي يليــه وملــا قــرره الفقهــاء مــن ان نفقــة االقــارب مــن أبــاء‬\n‫وأبنــاء وغيرهــم تســقط اذا انفــق غيــر مــن جتــب عليــه النفقــة عليهــم‬\n‫بغيــر نيــة الرجــوع جــاء يف كشــاف القنــاع ‪ ( : 161 / 13‬ولــو امتنــع زوج‬\n‫أو قريــب مــن نفقــة واجبــة بــأن تطلــب منــه النفقــة فيمتنــع فقــام بهــا غيــره‬\n‫رجــع عليــه منفــق بنيــة الرجــوع ) أ‪.‬ه ـ فقــد حكمــت بإلــزام املدعــى‬\n‫عليــه أصالــة ‪ ...‬أن يدفــع للمدعيــة مبلغ ـ ًا وقــدره ســتمائة ريــال ســعودي‬\n‫بهــذا حكمــت وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة عــدم‬\n‫قناعتهــا باحلكــم واســتعدت بتقــدمي الئحــة اعتراضيــة وجــرى افهامهــا‬\n‫باســتالم نســخة احلكــم يف هــذا اليــوم وتقــدمي الئحتهــا يف مــدة أقصاهــا‬\n‫ثالثــون يوم ـ ًا تبــدأ يف هــذا اليــوم وان حقهــا يف االعتــراض يســقط اذا‬\n‫انتهــت املــدة ولــم تتقــدم بالئحتهــا االعتراضيــة كمــا قــرر املدعــى عليــه‬\n‫وكالـ ًة القناعــة باحلكــم وذلــك بعــد أن مت التأكــد مــن وكالتــه وأنهــا‬\n‫تخولــه قبــول االحــكام وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/10‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف برقــم ‪ 34537146‬وتاريــخ‬\n‫‪1434/04/21‬ه ـ برفقهــا القــرار الصــادر مــن دائــرة األحوال الشــخصية‬\n‫برقم ‪ 34183460‬وتاريخ ‪1434/04/09‬هـ ونص احلاجة منه‪( :‬وبدراسة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة والالئحــة االعتراضيــة لوحــظ‬\n‫مــا يلــي ‪ :‬وجــد يف الالئحــة االعتراضيــة مــا يلفــت النظــر وذلــك يف‬\n\n\n                                                                                         ‫‪8‬‬\n\f    ‫الفقــرة األولــى والثالثــة فعلــى فضيلتــه اإلطــاع علــى مــا ذكــر بالالئحــة‬\n    ‫وإعــادة النظــر يف حكمــه فلمالحظــة مــا ذكــر وإحلــاق مــا يســتجد‬\n    ‫بالضبــط وملخصــة الصــك وســجله واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬دائــرة األحــوال الشــخصية واألوقــاف‬\n    ‫والوصايــا والقصــار وبيــوت املــال ‪ .‬قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n    ‫( لــه وجهــة نظــر ) قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n    ‫‪...‬ختمــه وتوقيعــه ) فأجيــب أصحــاب الفضيلــة عمــا الحظــوه بأنــي وبعــد‬\n    ‫مراجعــة مــا كتــب يف الالئحــة االعتراضيــة مــرة أخــرى وخاصــة الفقــرة‬\n    ‫األولــى والثالثــة منهــا لــم أجــد مــا يؤثــر فيمــا حكمــت لكونــي ناقشــت‬\n    ‫املدعيــة يف أثنــاء اجللســة التــي أخــذت فيهــا إقرارهــا بأنهــا انفقــت بغيــر‬\n    ‫نيــة الرجــوع وشــرحت لهــا املــراد عــدة مــرات ولــم أدون إقرارهــا إال بعــد‬\n    ‫فهمهــا التــام للمــراد كمــا أن إقامتهــا دعــوى ســابقة ال يلــزم منــه أن‬\n    ‫إنفاقهــا كان بنيــة الرجــوع فقــد يتقــدم الشــخص بدعــوى ويتركهــا‬\n    ‫وينــوي التبــرع بعــد ذلــك فيمــا انفــق لــذا فإنــي أفيــد أصحــاب الفضيلــة‬\n    ‫ـاق علــى مــا حكمــت بــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬  ‫بأنــي بـ ٍ‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/05/25‬ه ـ ‪.‬‬\n    ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n    ‫فلــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بنجــران والقائــم بعمــل املكتــب‬\n    ‫القضائــي الســادس فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n    ‫مبنطقــة عســير برقــم ‪ 341428648‬وتاريــخ ‪1434/08/2‬ه ـ برفقهــا‬\n    ‫القــرار الصــادر مــن دائــرة األحــوال الشــخصية برقــم ‪ 34277428‬وتاريخ‬\n    ‫‪1434/07/24‬ه ـ ونــص احلاجــة منــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطه‬\n    ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط‬\n\n\n‫‪9‬‬\n\f‫وصــك احلكــم بنــاء علــى قــرار الدائــرة رقــم ‪ 34183460‬وتاريــخ‬\n‫‪1434/4/9‬ه ـ تقــررت املوافقــة علــى احلكــم باألكثريــة بعــد اإلجــراء‬\n‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n‫املــال ‪ .‬قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف‪ ...‬ختمــه‬\n‫وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه وحتــى ال يخفــى جــرى حتريــره‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه وســلم‪.‬‬\n                                               ‫حــرر يف ‪ 1434/08/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية و األوقــاف والوصايــا والقصــار‬\n‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة لهــذه احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة بنجــران‬\n‫برقــم ‪ 341013690‬وتاريــخ ‪1434/6/4‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة الشيخ‪....../‬املســجل برقــم‪ 347261‬وتاريــخ ‪1434/1/10‬ه ـ‬\n‫اخلاصــة بدعــوى ‪...‬ضــد ‪...‬بشــأن نفقــة علــى الصفــة املوضحــة بالصــك‬\n‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون بباطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n‫وأحلقــه بالضبــط وصــك احلكــم بنــاء على قرار الدائــرة رقم ‪34183460‬‬\n‫وتاريــخ ‪1434/4/9‬ه ـ تقــررت املوافقــة علــى احلكــم باألكثريــة بعــد‬\n‫اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمد و آله وصحبه‬\n‫وســلم ‪.‬دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n                                                                          ‫املــال‪.‬‬\n\n\n\n                                                                                     ‫‪10‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":5,"source_page_end":10,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7cb949488b3c7f86b53952f64395dacbc6daedc02c27cf758dfc0e8cced794ab","normalized_text_hash":"99bc4229892fc9cd1f2d4140e039e5a38408070c995e9e0045d71c8ea1b9de37","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p5-347261"},{"id":"b14d6503-3cb3-527d-8022-4e203413b1a5","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -طلب نفقة األبناء عن املدة املاضية -من جتاوز من األبناء سن البلوغ فليس لوالدته املطالبه بنفقته إال بوكالة عنه -يشترط نية الرجوع ملن قام بالنفقة الواجبة على غيره.","document_number":"3377548","case_number":"32279617","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/2/13","year":"1434","subject":"نفقة -طلب نفقة األبناء عن املدة املاضية -من جتاوز من األبناء سن البلوغ فليس لوالدته املطالبه بنفقته إال بوكالة عنه -يشترط نية الرجوع ملن قام بالنفقة الواجبة على غيره.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/2/13 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3377548 :‬‬\n                        ‫َر ْق ُم الدعوى‪32279617 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 3450961‬تاريخه‪1434/3/20 :‬هـ‬\n\n\n\n     ‫نفقــة‪ -‬طلــب نفقــة األبنــاء عــن املــدة املاضيــة‪ -‬مــن جتــاوز مــن األبنــاء‬\n     ‫ســن البلــوغ فليــس لوالدتــه املطالبــه بنفقتــه إال بوكالة عنه‪ -‬يشــترط‬\n                      ‫نيــة الرجــوع ملــن قــام بالنفقــة الواجبــة علــى غيــره‪.‬‬\n\n\n\n\n     ‫قــال يف كشــاف القنــاع (ولــو امتنــع زوج أو قريــب مــن نفقــه واجبــة بــأن‬\n     ‫تطلــب منــه النفقــة فيمتنــع فقــام بهــا غيــره رجــع عليــه منفــق بنيــة‬\n                               ‫الرجــوع ألنــه قــام عنــه بواجــب كقضــاء دينــه)‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــة للمدعــى عليــه‬\n     ‫وأجنبــت منــه ثالثــة أبنــاء األول مولــود يف ‪1461/8/10‬ه ـ والثانــي مولــود‬\n     ‫يف ‪1491/10/2‬ه ـ والثالــث مولــود يف ‪1422/11/23‬هــ‪ ،‬وقــد جلــس‬\n     ‫االبــن األول والثانــي عنــد موكلتــه ســبعة أشــهر وعشــرة أيــام ولــم ينفــق‬\n     ‫املدعــى عليــه عليهمــا طيلــة هــذه الفتــرة‪ ،‬طلــب املدعــي وكالــة إلــزام‬\n     ‫املدعــى عليــه بدفــع نفقــة االبنــن املذكوريــن خــال فتــرة جلوســهما‬\n     ‫عنــد والدتهمــا وقدرهــا ألــف ريــال شــهري ًا لــكل واحــد منهمــا‪ ،‬أقــر‬\n     ‫املدعــى عليــه مبــا جــاء يف الدعــوى وذكــر بأنــه اتصــل بخــال األبنــاء‬\n     ‫ليقــوم بإحضارهــم إال أنــه قــال الدخــل لــي ثــم ذهــب إلــى الشــرطة يطلــب‬\n\n‫‪11‬‬\n\f‫تســليمهم ولــم يجــد جــدوى وكانــت والدتهــم تأمرهــم باجللــوس عندهــا‪،‬‬\n‫أنكــر املدعــي وكالــة مــا ذكــره املدعــى عليــه‪ ،‬قــرر املدعــى عليــه‬\n‫أنــه البينــه لديــه وطلــب ميــن املدعيــة أصالــة‪ ،‬حضــرت املدعيــة أصالــة‬\n‫وقــررت أنهــا لــم تامــر ابنائهــا بالبقــاء عندهــا ورفضــت أداء اليمــن‪ ،‬ورد‬\n‫قــرار هيئــة النظــر املتضمــن تقديــر نفقــة االبنــن املذكوريــن عــن املــدة‬\n‫املذكــورة وروعــي يف ذلــك االلتزامــات املترتبــة علــى والدهمــا وكذلــك‬\n‫روعــي أن االبنــن يدرســان باملرحلــة املتوســطة‪ ،‬صــدر احلكــم علــى‬\n‫املدعــى عليــه بــأن يدفــع للمدعيــة أصالــة نفقــة الســبعة أشــهر وعشــرة‬\n‫أيــام حســبما جــاء يف قــرار هيئــة النظــر‪ ،‬قنعــت املدعيــة باحلكــم ولــم‬\n‫يقنــع املدعــى عليــه‪ ،‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف‬\n‫مبالحظــات أهمهــا أن االبــن األول جتــاوز ســن البلــوغ وليــس لوالدتــه‬\n‫املطالبــة إال بوكالــة عنــه وأيضـ ًا النفقــة املطالــب بهــا عــن مــدة ماضيــة‬\n‫ولــم يســال فضيلتــه ملــاذا لــم تطالــب املدعيــة بالنفقــة يف وقتهــا وينبغــي‬\n‫مراعــاة مــا قــرره أهــل العلــم بشــأن ســقوط نفقــة القريــب مبضــي‬\n‫املدة‪،‬أجــاب فضيلــة القاضــي بــأن االبــن األكبــر وإن جتــاوز ســن البلــوغ‬\n‫إال أن املدعيــة والدتــه تطالــب بنفقــة ماضيــة أنفقتهــا وليســت مســتقبلة‪،‬‬\n‫كمــا جــرى ســؤال املدعيــة ملــاذا لــم تطالــب بالنفقــة مــن حــن حضــور‬\n‫األبنــاء لديهــا فقالــت إن املدعــى عليــه ابــن خالتهــا وكانــت تتحــرج مــن‬\n‫مطالبتــه حتــى عرضــت األمــر علــى والدتــه فقالــت مــن حقــك أن تطالبــي‬\n‫بالنفقــة‪ ،‬وســقوط نفقــة القريــب مبضــي املــدة وذلــك يف حــال عــدم نيــة‬\n‫املنفــق الرجــوع كمــا ذكــر ذلــك يف كشــاف القنــاع‪ ،‬صــدق احلكــم‬\n                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بينبــع‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بينبع‪/‬املســاعد برقــم ‪ 32279617‬وتاريــخ ‪ 1432/07/11‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 32868216‬وتاريــخ ‪ 1432/07/11‬ه ـ ففــي يــوم‬\n     ‫السبت املوافق‪ 1432/08/01‬هـ أفتتحت اجللسة الساعة ‪ 11 : 01‬وفيها‬\n     ‫حضــر املدعــي وكالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪...‬الوكيــل الشــرعي عــن املدعيــه ‪...‬مبوجــب الوكالــة رقــم ‪32159298‬‬\n     ‫وتاريــخ ‪1432/07/09‬ه ـ الصــادرة مــن كتابــة عــدل محافظــة ينبــع‬\n     ‫وحضــر حلضــوره املدعــى عليــه ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪...‬وقــرر املدعــي قائــا ان موكلتــي ســبق وان تزوجــت‬\n     ‫املدعــى عليــه واجنبــت منــه ثالثــه ابنــاء ‪...‬املولــود يف ‪1416/08/10‬هـ و‪...‬‬\n     ‫املولــود يف ‪1419/10/02‬ه ـ و‪ ...‬املولــود يف ‪1422/11/23‬ه ـ وقــد جلــس‬\n     ‫‪...‬و‪ ...‬عنــد موكلتــي مــن تاريــخ ‪1431/12/11‬هـ حتى ‪1432/07/20‬هـ‬\n     ‫ولــم ينفــق املدعــى عليــه عليهمــا طيلــة هــذه الفتــرة اطلــب احلكــم عليــه‬\n     ‫والزامــه بدفــع نفقتهمــا خــال فتــرة جلوســهما لــدى والدتهــم وقدرهــا‬\n     ‫الــف ريــال لــكل واحــد منهمــا شــهري ًا هــذه دعــواي وبســؤال املدعــى‬\n     ‫عليــه قــال ماذكــره املدعــي مــن زواجــي مبوكلتــه واجنبــت منــي ثالثــه‬\n     ‫ابنــاء ثــم طلقتهــا فصحيــح وامــا ماذكــر مــن جلــوس ابنــي ‪ ....‬و‪...‬عنــد‬\n     ‫والدتهــم مــن تاريــخ ‪1431/12/11‬ه ـ وحتــي تاريــخ ‪1432/07/20‬ه ـ‬\n     ‫فصحيــح ايض ـ ًا وقــد اتصلــت بخــال االبنــاء ‪...‬ليقــوم بإحضاراالبنــاء اال‬\n     ‫انــه قــال الدخــل لــي بهــم ثــم ذهبــت الــى الشــرطه لطلــب تســليمهم ولــم‬\n\n‫‪13‬‬\n\f‫أجــد جــدوى وكانــت والدتهــم تأمرهــم باجللــوس عندهــا هكــذا أجــاب‬\n‫فســألت املدعــي هــل جلوســهم يف بيــت والدتهــم كان بطلــب منهــا فقــال‬\n‫ال هكــذا اجــاب وحيــث تطلــب االمــر الكتابــه لهيئــة النظــر لتقديــر‬\n‫النفقــه لــكل واحــد منهمــا لــذا رفعــت اجللســة حلــن ورود االجابــه احلمــد‬\n‫هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبع‪/‬املســاعد برقــم ‪ 32279617‬وتاريخ‪1432/11/7‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32868216‬وتاريخ‪1432/7/11‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق ‪1432/11/18‬ه ـ أفتتحــت اجللســة الســاعة ‪ 11 : 57‬وفيهــا‬\n‫حضــر املدعــي وكالــة واملدعــى عليــه وجــرى ســؤال املدعــى عليــه‬\n‫هــل لديــك بينــة علــى أن والدتهــم تأمرهــم بالبقــاء عندهــا فقــال البينــه‬\n‫عنــدي وأطلــب ميــن والدتهــم وإلحضــار األم ألداء اليمــن رفعــت اجللســة‬\n‫ويف يــوم االربعــاء املوافــق ‪1432/11/21‬ه ـ أفتتحــت اجللســة الســاعة‬\n‫‪ 12 : 00‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه كمــا حضــرت‬\n‫املدعيــه اصالــة ‪...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫وبســؤالها عمــا ذكــره املدعــى عليــه مــن انهــا كانــت تأمرهــم بالبقــاء‬\n‫لديهــا اجابــت قائلــه ماذكــره املدعــى عليــه مــن اننــي آمرهــم بالبقــاء‬\n‫عنــدي غيــر صحيــح وبعــرض ذلــك علــى املدعــى عليــه قــال ماذكرتــه‬\n‫غيــر صحيــح وأطلــب ميينهــا وبعــرض ذلــك علــى املدعيــه رفضــت ذلــك‬\n‫وللتأمــل رفعــت اجللســة ويف يــوم االربعــاء املوافــق ‪1433/01/12‬ه ـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر املدعــي واملدعــى عليــه‬\n‫وقــد رأيــت الكتابــه للجنــة االصــاح حملاولــة االصــاح بــن الطرفــن‬\n‫وتخويفهمــا بــاهلل وحلــن ورود االفــادة رفعــت اجللســة ويف يــوم االثنــن‬\n\n\n                                                                                   ‫‪14‬‬\n\f     ‫املوافــق ‪1433/02/08‬ه ـ أفتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا‬\n     ‫حضــر املدعــي واملدعــى عليــه وجــرى االطــاع علــى قــرار هيئــة النظــر‬\n     ‫رقــم ‪ 66‬يف ‪1432/9/13‬ه ـ املرفــق باملعاملــة وهــذا نصــه ( احلمــد هلل‬\n     ‫وحــده وبعــد ويف يــوم الســبت املوافــق ‪1432/09/13‬ه ـ ويف متــام الســاعة‬\n     ‫الواحــدة واربعــون دقيقــه وبنــاء علــى خطــاب فضيلــة القاضــي ‪...‬رقــم‬\n     ‫‪ 321009019‬يف ‪1432/8/8‬ه ـ والــذي يطلــب فيــه حتديــد نفقــه وذلــك‬\n     ‫بنــاء علــى دعــوى املــرأة ‪ ...‬ضــد ‪...‬وذلــك البنيهــا ‪...‬و‪ ...‬عليــه فقــد حضــر‬\n     ‫املدعــى عليــه ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ولــم‬\n     ‫يحضــر الوكيــل الشــرعي للمدعيــة فقــد جــرى ســؤال املدعــى عليــه عــن‬\n     ‫راتبــه فأفــاد ان صــايف الراتــب هــو ســبعة اآلف وتســعمائة ريــال وأنــه‬\n     ‫يعــول والديــه ولديــه زوجــة وثالثــة أبنــاء آخريــن خــاف االثنــن محــل‬\n     ‫الدعــوى وبالنظــر يف حــال والــد االبنــن فقــد تقــرر هيئــة النظــر نفقــه‬\n     ‫شــهريه لــكل واحــد منهمــا ســبعمائة وخمســون ريــاال وأمــا بخصــوص‬\n     ‫شــهر ذو القعــده لعــام ‪1431‬ه ـ فيكــون مقــدار النفقــة الــف ريــال لــكل‬\n     ‫ابــن وقــد روعــي يف ذلــك اإللتزامــات املترتبــة علــى والــده كمــا روعــي‬\n     ‫أن االبنــن يدرســان باملرحلــة املتوســطه وبــاهلل التوفيــق وصلــي اهلل علــى‬\n     ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1432/9/13‬ه ـ ) عضــو‬\n     ‫هيئــة النظــر ‪ ...‬توقيعــه و ‪...‬توقيعــه املدعــى عليــه ‪...‬توقيعــه رئيــس قســم‬\n     ‫اخلبــراء ‪...‬توقيعــه وبنــاء علــى ماســبق مــن الدعــوى واالجابــه وملــا جــاء‬\n     ‫يف قــرار هيئــة النظــر مــن ان النفقــة الشــهريه لــكل واحــد مــن االبنــن‬\n     ‫ســبعمائه وخمســون ريــاال ومبــا ان االبنــن جلســا عنــد والدتهــم مــدة‬\n     ‫ســبعة اشــهر وتســعة ايــام لــذا فقــد حكمــت بــأن يدفــع املدعــى عليــه‬\n     ‫للمدعيــه اصالــة مبلــغ عشــرة اآلف وتســعمائه وخمســن ريــاال كاملــة‬\n\n\n‫‪15‬‬\n\f‫حــاال هــذا ماظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــي قــرر‬\n‫قناعتــه بــه وقــرر املدعــى عليــه اعتراضــه بالئحــه اعتراضيــه فأفهــم بــأن‬\n‫لــه مــده ثالثــن يومــا تبــدا مــن هــذا اليــوم فــإذا لــم يتقــدم خاللهــا بشــي‬\n‫فــان احلكــم يكــون مكتســبا للقطعيــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/02/8‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1433/08/14‬ه ـ‬\n‫افتتحــت اجللســة الســاعة احلاديــة عشــرة صباحــا وفيهــا حضــرت‬\n‫املدعيــة ‪ ...‬واملعــرف بهــا مــن قبــل أخيهــا ‪...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ ...‬واملدعــى عليــه ‪ ...‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باخلطــاب رقــم ‪ 33836283‬يف ‪1433/5/15‬ه ـ مالحظـ ًا عليهــا بالقــرار‬\n‫رقــم ‪ 33237413‬يف ‪1433/5/9‬ه ـ وهــذا نــص احلاجــة منــه ( وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر باألكثريــة إعادتهــا‬\n‫لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬ســمع فضيلتــه دعــوى ‪ ....‬عــن‬\n‫طريــق وكيلهــا تطالــب بنفقــة ابنيهــا ‪...‬و‪ ...‬تبــن أن ‪ ...‬قــد جتــاوز ســن‬\n‫البلــوغ وليــس لوالدتــه املطالبــة إال بوكالــة منــه ‪ -2 .‬النفقــة املطالــب‬\n‫بهــا عــن مــدة ماضيــة ولــم يســأل فضيلتــه ملــاذا لــم تطالــب بالنفقــة‬\n‫يف وقتهــا يومــا بيــوم أو شــهرا بشــهر حتــى اجتمعــت كل هــذه املــدة‬\n‫وينبغــي مراعــاة مــا قــرره أهــل العلــم بشــأن ســقوط نفقــة القريــب مبضــي‬\n‫املــدة ‪ -3 .‬ورد يف الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه‬\n‫مــا يســتحق النظــر واملناقشــة ومــن ذلــك وجــود دعــوى ســابقة وصلــح‬\n‫بشــأن احلضانــة والزيــارة ومــا ذكــره مــن حتريــض املدعيــة وابنهــا ‪..‬‬\n‫الــخ كمــا أنــه لــم يتــم اثبــات اســتالم الالئحــة االعتراضيــة بالضبــط‬\n‫واإلجابــة عليهــا حســب التعليمــات واهلل املوفــق وصلــى اهلل وســلم علــى‬\n\n\n                                                                                         ‫‪16‬‬\n\f     ‫نبينــا محمــد قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف د‪....‬‬\n     ‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه موافــق علــى احلكــم)‬\n     ‫ا ه ـ وعليــه أجيــب أصحــاب الفضيلــة عــن مالحظتهــم األولــى بــأن ‪...‬‬\n     ‫قــد جتــاوز ســن البلــوغ وليــس لوالدتــه املطالبــة إال بوكالــة منــه بــأن‬\n     ‫املدعيــة تطالــب بنفقــة ماضيــة وليســت مســتقبلة وعليــه أجيــب أصحــاب‬\n     ‫الفضيلــة علــى مالحظاتهــم الثانيــة بأنــه جــرى ســؤال املدعيــة ملــاذا لــم‬\n     ‫تطالــب بنفقــة ابنيهــا فقالــت أنــه بينــي وبــن املدعــى عليــه قرابــة وهــو‬\n     ‫ابــن خالتــي وكنــت أحتــرج مــن ذلــك وقــد عرضــت ذلــك علــى والــدة‬\n     ‫املدعــى عليــه فقالــت مــن حقــك أن تطالبــي بالنفقــة فتقدمــت بذلــك‬\n     ‫هكــذا أجابــت وأمــا مــا ذكــره أصحــاب الفضيلــة مــن ســقوط نفقــة‬\n     ‫القريــب مبضــي املــدة فإنــه يف حــال عــدم نيــة املنفــق بالرجــوع علــى مــن‬\n     ‫أنفــق قــال يف كشــاف القنــاع (ولــو امتنــع زوج أو قريــب مــن نفقــة واجبــة‬\n     ‫بــأن تطلــب منــه) النفقــة (فيمتنــع) فقــام بهــا غيــره (رجــع عليــه منفــق‬\n     ‫بنيــة الرجــوع ) إلنــه قــام عنــه بواجــب كقضــاء دينــة) وأمــا مالحظاتهــم‬\n     ‫الثالثــة فــإن احلضانــة لــأب والزيــارة لــأم حســب الصــك الصــادر منــي‬\n     ‫برقــم ‪ 4/28‬يف ‪1431/7/24‬ه ـ وأمــا حتريــض املدعيــة أبنائهــا علــى‬\n     ‫والدهــم فســألتها عــن ذلــك فقالــت إننــي لــم أحرضهــم علــى والدهــم‬\n     ‫وأبنائــي يأتــون إلــي وقــد أعدتهــم إلــى والدهــم أكثــر مــن مــرة ولكــن‬\n     ‫يرفضــون البقــاء عنــد والدهــم إلن زوجتــه تضربهــم وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــال إن زوجتــي ال تضربهــم ولكــن تزجرهــم لعــدم أداء‬\n     ‫واجباتهــم املدرســية وبنــاء علــى مــا ســبق لــم يظهــر لــي ســوى مــا حكمــت‬\n     ‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪ 1433/08/14‬ه ـ‬\n\n\n‫‪17‬‬\n\f‫ويف يــوم الثالثــاء املوافــق‪ 1433/10/24‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪09:00‬وفيهــا حضــر املدعــي ‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم‪...‬‬\n‫الوكيــل الشــرعي عــن اختــه ‪ ...‬مبوجــب الوكالــة رقــم ‪33434273‬‬\n‫وتاريــخ ‪1433/10/22‬ه ـ والصــادرة مــن كتابــة عــدل ينبــع واملخــول لــه‬\n‫فيهــا املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ ...‬كمــا حضــر حلضــوره أبنــاء املتداعــن وهــم‬\n‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬واملضــاف بســجل‬\n‫والــده ‪ ...‬ســعودي اجلنســية بالســجل رقــم ‪ ...‬واملضــاف بســجل والــده و‪...‬‬\n‫ســعودي بالســجل رقــم ‪...‬واملضــاف بســجل والــده وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف مالحظــا عليهــا بالقــرار رقــم ‪33400757‬‬\n‫وتاريــخ ‪1433/09/03‬ه ـ وهــذا نــص احلاجــة منــه ( وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا‬\n‫لفضيلــة حاكمهــا ملالحظــة ‪ :‬ان إجابــة فضيلتــه غيــر كافيــه فالصــك‬\n‫الســابق محكــوم فيــه باحلضانــة لــأب والزيــارة لــأم فكيــف تطالــب‬\n‫بالنفقــه واحلضانــة لــأب كمــا انهــا لــم تطالــب بالنفقــة اال بتاريــخ‬\n‫‪1432/07/11‬ه ـ حســب صحيفــة الدعــوى فكيــف يحكــم لهــا‬\n‫قبــل هــذا التاريــخ وليــس لهــا حــق اال يف الزيــارة واهلل املوفــق ) قــاض‬\n‫اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي ‪ ...‬ســبقت موافقتــي علــى احلكــم‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه وعليــه أجيــب أصحــاب‬\n‫الفضيلــة عــن مالحظتهــم األولــى بأنــه جــرى ســؤال األبنــاء احلاضريــن‬\n‫ملــاذا لــم جتلســوا يف بيــت والدكــم فأجابــوا بــأن ذهبنــا لبيــت والدنــا‬\n‫اكثــر مــن مــرة وطردنــا مــن البيــت وزوجــة والدنــا تضربنــا فلهــذا‬\n‫ذهبنــا لبيــت والدتنــا هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n\n\n                                                                                  ‫‪18‬‬\n\f     ‫قــال اننــي لــم اضربهــم وقــد ذهبــت الــى الشــرطة الجــل اســتالم ابنائــي‬\n     ‫فرفــض خالهــم ‪ ...‬حضــور والدتهــم للشــرطة الجــل تســليم االبنــاء الــي‬\n     ‫وبعــد ثالثــه ايــام تقدمــت املدعيــه بشــكوى لــدى شــرطة البلــد بأننــي‬\n     ‫مســيئ لالبنــاء واننــي اضربهــم كمــا أضــاف املدعــي بــأن والدهــم قــد‬\n     ‫هــدد ابنــه ‪...‬بالســاح وقــال لــي واهلل ألجيبــك هكــذا قــال وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه قــال ماذكــره املدعــي مــن تهديــد ابنــي بالســاح غيــر‬\n     ‫صحيــح وامــا ماذكــر مــن قولــي بأنــي اجيبــك صحيــح وامــا مالحظتهــم‬\n     ‫الثانيــة فانــه ســبق اجلــواب عنهــا ولهــذا لــم يظهــر لــي ســوى ماحكمــت‬\n     ‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                    ‫وســلم ‪ .‬حــرر يف ‪ 1433/10/24‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n     ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n     ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس محكمــة‬\n     ‫ينبــع العامــة املســاعد رقــم ‪ 331721171‬وتاريــخ ‪1434/ 1/12‬ه ـ املرفق‬\n     ‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪... /‬القاضــي باحملكمــة العامــة‬\n     ‫بينبــع برقــم ‪ 3377548‬وتاريــخ ‪1433/ 2/13‬ه ـ املتضمــن دعــوى املــرأة‬\n     ‫‪...‬ضــد ‪ ...‬يف نفقــة أوالدهــا ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجابــه علــى القــرار ‪،‬‬\n     ‫واهلل املوفــق ‪ .‬وصلــى اهلل عل ـ ـ ــى نبينــا محمــد وعلـ ـ ــى آلـ ـ ـ ــه وصحب ـ ـ ــه‬\n                                                                                        ‫وســلم‪.‬‬\n\n\n\n\n‫‪19‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":11,"source_page_end":19,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3845ba1e926ba0d8fff56deda372a1bdbed06f2c6b8f4dd9f63811dc73cd3f2d","normalized_text_hash":"6e04f8e1bd153f995047f0528f168be7ee54d81c0d21970f5b6c26e83bd99617","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p11-3377548"},{"id":"58dafee4-b703-56a9-ba80-d858e81a5690","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة وأوالد -املطالبة بالنفقة املاضية واملستقبلية -الدفع بعدم استحقاق الزوجة للنفقة لنشوزها -التنازل عن النفقة بشرط الطاق واحلضانة -تقدير النفقة من قبل قسم اخلبراء -النفقة ال تسقط بالتقادم -حلف الزوجة اليمن على عدم نفقة الزوج -النفقة بنية الرجوع -اإللزام بالنفقة املاضية","document_number":"3396987","case_number":"3326768","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/28","year":"1434","subject":"نفقة -نفقة زوجة وأوالد -املطالبة بالنفقة املاضية واملستقبلية -الدفع بعدم استحقاق الزوجة للنفقة لنشوزها -التنازل عن النفقة بشرط الطاق واحلضانة -تقدير النفقة من قبل قسم اخلبراء -النفقة ال تسقط بالتقادم -حلف الزوجة اليمن على عدم نفقة الزوج -النفقة بنية الرجوع -اإللزام بالنفقة املاضية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1433/8/28 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪3396987 :‬‬\n                     ‫َر ْق ُم الدعوى‪3326768 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 345811‬تاريخه‪1434/1/7 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة وأوالد ‪ -‬املطالبــة بالنفقــة املاضيــة واملســتقبلية‬\n‫‪ -‬الدفــع بعــدم اســتحقاق الزوجــة للنفقــة لنشــوزها ‪ -‬التنــازل عــن‬\n‫النفقــة بشــرط الطــاق واحلضانــة ‪ -‬تقديــر النفقــة مــن قبــل قســم‬\n‫اخلبــراء ‪ -‬النفقــة ال تســقط بالتقــادم ‪ -‬حلــف الزوجــة اليمــن علــى‬\n‫عــدم نفقــة الــزوج ‪ -‬النفقــة بنيــة الرجــوع ‪ -‬اإللــزام بالنفقــة املاضيــة‬\n                                                              ‫واملســتقبلية ‪.‬‬\n\n\n\n\n                                             ‫‪ -1‬قاعدة ‪ :‬من ترك دعواه ترك‬\n                                                  ‫‪ -2‬قاعدة ‪ :‬العادة محكمة‬\n                               ‫‪ -3‬قاعدة ‪ :‬املعروف عرف ًا كاملشروط شرط ًا ‪.‬‬\n‫‪ -4‬قــال شــيخ اإلســام يف الفتــاوى (‪( : )134/34‬إذا كان االبــن يف‬\n‫حضانــة أمــه فأنفقــت عليــه تنــوى بذلــك الرجــوع علــى األب فلهــا أن‬\n‫ترجــع علــى األب يف أظهــر قولــي العلمــاء وهــو مذهــب مالــك واحمــد‬\n                          ‫يف ظاهــر مذهبــه الــذي عليــه قدمــاء أصاحبــه)‪.‬‬\n‫‪ -5‬قــال ابــن قدامــة يف الــكايف (‪( : )97/5‬وإذا وجــد اليمــن املوجــب‬\n‫للنفقــة فلــم ينفــق حتــى مضــت مــدة صــارت النفقــة دينـ ًا يف ذمته ســواء‬\n‫تركهــا لعــذر أو غيــره حلديــث عمــر رضــي اهلل عنــه وألنــه مــال يجــب‬\n   ‫علــى ســبيل البــدل يف عقــد معاوضــة فلــم يســقط مبضــي الزمــن) ‪.‬‬\n\n                                                                                  ‫‪20‬‬\n\f     ‫‪ -6‬قــال إبراهيــم بــن ضويــان يف منــار الســبيل (‪( : )1046/3‬مــن غــاب‬\n     ‫عــن زوجتــه مــدة ولــم ينفــق عليهــا لزمتــه نفقــة الزمــن املاضــي) ‪ .‬وقــال‬\n     ‫يف موضــع آخــر (‪( : )1052/2‬حيــث امتنــع منهــا الــزوج أو قريــب وأنفــق‬\n             ‫أجنبــي بنيــة الرجــوع رجــع ألنــه قــام عنــه بواجــب قضــاء دينــه)‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة علــى زوجهــا املدعــى عليــه بأنهــا عنــد أهلهــا مــن تاريــخ‬\n     ‫‪1427/6/30‬ه ـ وإنهــا أجنبــت بنتـ ًا بتاريــخ ‪1427/7/27‬ه ـ وأن املدعــى‬\n     ‫عليــه لــم ينفــق عليهــا وال علــى ابنتهــا طيلــة هــذه املــدة‪ ،‬طلبــت املدعيــة‬\n     ‫إلــزام املدعــى عليــه بدفــع نفقتهــا ونفقــة ابنتهــا عن املــدة املاضية وحتديد‬\n     ‫نفقــة مســتقبلية‪ ،‬صــادق املدعــى عليــه علــى الدعــوى ودفــع بــأن املدعيــة‬\n     ‫خرجــت مــن البيــت بغيــر إذنــه‪ ،‬قــرر املدعــى عليــه بأنــه دفــع البنتــه عنــد‬\n     ‫والدتهــا ألف ـ ًا وخمســمائة ريــال‪ ،‬قــرر املدعــى عليــه بأنــه ال مانــع لديــه‬\n     ‫مــن النفقــة علــى ابنتــه دون املدعيــة‪ ،‬ذكــرت املدعيــة بأنهــا لــم تخــرج‬\n     ‫مــن بيــت املدعــى عليــه بغيــر إذنــه وهــو الــذي أوصلهــا لبيــت أهلهــا‪ ،‬مت‬\n     ‫عــرض الصلــح بــن الطرفــن فتعــذر ذلــك‪ ،‬رأت جلنــة الصلــح حتديــد‬\n     ‫نفقــة البنــت خمســمائة ريــال شــهري ًا عــن النفقــة املاضيــة واملســتقبلية‬\n     ‫وتنازلــت املدعيــة عــن نفقتهــا حســب احملضــر املرفــق‪ ،‬قــررت املدعيــة ان‬\n     ‫تنازلهــا عــن نفقتهــا مشــروط بطالقهــا وحضانتهــا البنتهــا وأن املدعــى‬\n     ‫عليــه رفــض ذلــك‪ ،‬قــرر املدعــى عليــه عــدم موافقتــه علــى مــا ذكرتــه‬\n     ‫املدعيــة مــن تنازلهــا عــن النفقــة بشــرط الطــاق واحلضانــة‪ ،‬جــرى تقدير‬\n     ‫نفقــة املدعيــة مــن قبــل قســم اخلبــراء‪ ،‬قــررت املدعيــة ان مجمــوع مــا‬\n     ‫اســتلمته مــن املدعــى عليــه ثالثــة اآلف ريــال‪ ،‬قــرر املدعــى عليــه انــه ال‬\n‫‪21‬‬\n\f‫بينــة لديــه علــى أن املدعيــة هــي التــي خرجــت مــن بيتــه بغيــر إذنــه‪ ،‬جــرى‬\n‫إفهــام املدعــى عليــه بــأن لــه ميــن املدعيــة علــى أنهــا لــم تخــرج بغيــر إذنــه‬\n‫وأنهــا لــم ترفــض الرجــوع إليــه إال بتاريــخ ‪1433/6/16‬ه ـ وكانــت قبــل‬\n‫ذلــك تريــد الرجــوع وأنهــا كانــت تنــوى الرجــوع عليــه بالنفقــة‪ ،‬فقــرر‬\n‫انــه ال يطلــب ميينهــا‪ ،‬يف جلســة أخــرى حضــرت املدعيــة برفقــة والدهــا‬\n‫وحلفــت اليمــن املطلوبــة‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n‫نفقــة املدعيــة مــن تاريــخ ‪1427/6/30‬ه ـ حتــى تاريــخ ‪1433/6/16‬هــ‪،‬‬\n‫إلــزام املدعــى عليــه بدفــع نفقــة ابنتــه عــن املــدة املاضيــة ونفقــة مســتقبلية‬\n‫شــهري ًا قدرهــا خمســمائة ريــال‪ ،‬قنعــت املدعيــة باحلكــم‪ ،‬قــدم املدعــى‬\n    ‫عليــه الئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائف‪/‬املكلــف برقــم ‪ 3326768‬وتاريــخ ‪ 1433/01/10‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3366040‬وتاريــخ ‪ 1433/01/10‬ه ـ واملتعلقــة‬\n‫بدعــوى ‪ ...‬ضــد ‪ ...‬يف دعــوى بنفقــة ويف يــوم األحــد ‪1433/03/27‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة ‪09 : 11‬صباحــا وفيهــا حضــرت املــرأة‬\n‫املدعيــة ‪ ...‬حتمــل رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪ ...‬يحمــل بطاقــة‬\n‫الهويــة الوطنيــة رقــم ‪ ...‬وحضــر حلضورهــا املدعــى عليــه ‪ ...‬يحمــل بطاقــة‬\n‫الهويــة الوطنيــة رقــم ‪ ...‬وادعــت املدعيــة قائلــة يف دعواهــا ان املدعــى‬\n‫عليــه هــذا احلاضــر زوجــي تزوجنــي بالعقــد الصحيــح ودخــل بــي يف‬\n‫‪1425/9/25‬ه ـ واجنبــت لــه علــى فــراش الزوجيــة االبنــة ‪ ...‬وهــي مــن‬\n                                                                                            ‫‪22‬‬\n\f     ‫مواليــد‪ .../7/27‬ومــن تاريــخ ‪1427/6/30‬ه ـ وحتــى هــذا اليــوم وانــا‬\n     ‫عنــد أهلــي وحتــت حضانتــي ابنتــي ‪...‬ولــم ينفــق علــي املدعــى عليــه وال‬\n     ‫علــى ابنتــه طيلــة هــذه املــدة لــذا اطلــب الــزام املدعــى عليــه بتقديــر نفقــه‬\n     ‫ماضيــة ومســتقبلية لــي والبنتــه هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n     ‫دعــوى املدعيــة أجــاب قائــا كل مــا ذكرتــه املــرأة املدعيــة مــن أنهــا‬\n     ‫زوجتــي تزوجتهــا بالعقــد الصحيــح ودخلــت بهــا يف ‪1425/9/25‬ه ـ‬\n     ‫واجنبــت لــي علــى فــراش الزوجيــة االبنــة ‪ ...‬وهــي مــن مواليــد ‪.../7/27‬‬\n     ‫فهــذا صحيــح وقــد خرجــت املدعيــة مــن منزلــي وبــدون اذنــي يف‬\n     ‫‪1427/6/30‬ه ـ وقــد دفعــت البنتــي عنــد والدتهــا مبلــغ الــف وخمســمائة‬\n     ‫ريــال وال مانــع لــدي مــن االنفــاق علــى ابنتــي وتقديــر النفقــة الشــرعية‬\n     ‫أمــا بالنســبة للمدعيــة فــا نفقــة لهــا عنــدي هكــذا أجــاب وبعــرض ذلــك‬\n     ‫علــى املــرأة املدعيــة قالــت قــد دفــع لــي مبلــغ الــف ريــال فقــط عنــد والدة‬\n     ‫ابنتــي ولــم أخــرج مــن منزلــه بــدون إذنــه وهــو الــذي قــام بإيصالــي الــى‬\n     ‫أهلــي هكــذا قــررت وبــن أخــذ ورد ومحاولــة االصــاح بــن الطرفــن‬\n     ‫إال اننــي لــم أتوصــل الــى نتيجــة فجــرى ســؤال املدعــى عليــه هــل لديــك‬\n     ‫البينــة علــى أنــك ســلمتها مبلــغ ألــف وخمســمائة ريــال وكذلــك البينــة‬\n     ‫أنهــا هــي التــي خرجــت فقــال ال بينــة لــدي اال اهلل عــز وجــل فعليــه فقــد‬\n     ‫مت االتصــال علــى جلنــة االصــاح وقــد مت حتديــد موعــد يف هــذا اليــوم‬\n     ‫واملوعــد يف مكتبنــا يف يــوم الثالثــاء ‪1433/6/17‬ه ـ الســاعة التاســعة‬\n     ‫والنصــف وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/03/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1433/06/17‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪10 : 59‬وفيهــا حضــرت املــرأة املدعيــة ‪...‬‬\n\n\n‫‪23‬‬\n\f‫واملعــرف بهــا مــن قبــل والدهــا ‪ ...‬املدونــة هويتهمــا ســابقا وحضــر‬\n‫حلضورهــا املدعــى عليــه ‪...‬املثبتــة هويتــه ســابقا وقــد عــادت إلينــا املعاملــة‬\n‫من مكتب الصلح بالقرار رقم ‪/135‬ص يف ‪1433/3/28‬هـ واملتضمن‬\n‫مــا نصــه( وبعــرض الصلــح علــى الطرفــن وقــد تعــذر ذلــك وتــرى اللجنــة‬\n‫أن تكــون نفقــة الطفلــة املاضيــة خمســمائة ريــال واملســتقبلية خمســمائة‬\n‫ريــال بنــاء علــى إقــرار والــد الطفلــة املرفــق باملعاملة بأن راتبــه ثالثة آالف‬\n‫ريــال أمــا مــا يخــص نفقــة املدعيــة فتجــدون برفــق صــورة قــرار الصلــح‬\n‫املرفــق برقــم ‪/131‬ص يف ‪1433/3/27‬ه ـ املتضمــن تنازلهــا عــن نفقتها‪.‬‬\n‫املدعيــة بصمتهــا املدعــى عليــه بصمتــه اعضــاء جلنــة الصلــح ‪ ...‬توقيعــه‬\n‫‪ ...‬توقيعــه ‪ ...‬توقيعــه رئيــس قســم االصــاح ‪...‬توقيعه)ا‪.‬ه ـ وبعــرض هــذا‬\n‫القــرار علــى املــرأة املدعيــة قالــت ال أقبــل بهــذا واطلــب نفقتــي حيــث ان‬\n‫تنازلــي مشــروط مبوجــب طالقــي وان تكــون البنــت يف حضانتــي وقــد‬\n‫رفــض املدعــى عليــه ذلــك كمــا يتضــح مــن الدعــوى الســابقة هكــذا‬\n‫قــررت وبعرضــه علــى املدعــى عليــه قــال ال أقبــل مبــا ذكــر يف قــرار جلنــة‬\n‫الصلــح حيــث أننــي ال أســتطيع دفــع ذلــك أمــا مــا ذكرتــه مــن أن تنــازل‬\n‫املــرأة الســابق مبقابــل الطــاق وكذلــك أن تكــون احلاضنــة لديهــا فــا‬\n‫أوافــق علــى ذلــك وأطلــب حضانــة ابنتــي هكــذا قــرر فجرى ســؤال املرأة‬\n‫املدعيــة هــل أنتــي مســتعدة بالرجــوع إلــى املدعــى عليــه فقالــت بعــد هــذا‬\n‫اليــوم لــن أرجــع إلــى زوجــي وغيــر مســتعده بذلــك هكــذا قــررت فجــرى‬\n‫ســؤال املدعــى عليــه هــل ترغــب بزوجتــك فقــال لــم أخرجهــا مــن منزلهــا‬\n‫والــذي أخرجهــا هــو الــذي يعيدهــا وال أقبــل بيمــن املــرأة املدعية هكذا‬\n‫قــرر فجــرى ســؤال املــرأة املدعيــة هــل أنتــي مســتعده ببــذل اليمــن علــى‬\n‫ان املدعــى عليــه لــم يدفــع ســوى مبلــغ ألــف ريــال وهــل أنتــي مســتعده‬\n\n\n                                                                                         ‫‪24‬‬\n\f     ‫كذلــك علــى انــه كانــت نيتــك الرجــوع علــى زوجــك مبــا دفعتــي وان‬\n     ‫املدعــى عليــه هــو الــذي قــام بإخراجــك فقالــت نعــم وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــال ال أقبــل بيمــن املــرأة املدعيــة هكــذا قــرر هــذا كمــا‬\n     ‫جــرى االتصــال علــى جلنــة الصلــح لتقديــر نفقــة الزوجــة وقــد مت حتديــد‬\n     ‫موعــد يف يــوم األحــد الســاعة ‪1433/6/22‬ه ـ الســاعة ‪10.00‬صباحــا‬\n     ‫واملوعــد يف مكتبنــا يف يــوم البــت ‪1433/7/5‬ه ـ الســاعة ‪ 11.00‬وحــرر‬\n                        ‫يف ‪1433/6/17‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت ‪ 1433/07/‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪11.00‬وفيهــا حضــرت املــرأة املدعيــة ‪...‬واملعــرف بهــا مــن قبــل‬\n     ‫‪ ...‬املدونــة هويتهمــا ســابقا وحضــر حلضورهــا املدعــى عليــه ‪ ...‬واملدونــه‬\n     ‫هويتــه ســابقا وقــد ورد إلينــا قــرار مــن مكتــب الصلــح بهــذه احملكمــة‬\n     ‫برقــم ‪/267‬ص يف ‪1433/6/23‬ه ـ واملتضمــن مــا نصــه (وبعرض الصلح‬\n     ‫بينهمــا فقــد تعــذر الصلــح وتــرى اللجنــة أن تكــون نفقــة الزوجــة املاضيــة‬\n     ‫خمســمائة ريــال ونفقــة الطفلــة ‪...‬املاضيــة واملســتقبلية خمســمائة ريــال‬\n     ‫أعضــاء اللجنــة ‪... ....‬رئيــس قســم الصلــح ‪...‬توقيعهــم ) أ‪ .‬ه ـ وبعــرض ذلك‬\n     ‫علــى املدعــى عليــه قــال لســت موافــق علــى ذلــك هكــذا قــرر وبعرضــه‬\n     ‫علــى املــرأة املدعيــة قالــت كل مــا جــاء فيــه صحيــح هكــذا قــررت‬\n     ‫وبــن أخــذ ورد ومحاولــة اإلصــاح بــن الطرفــن اال أننــي لــم أتوصــل‬\n     ‫إلــى نتيجــة فجــرى ســؤال املدعــى عليــه هــل لديــك البينــة علــى صحــة‬\n     ‫دفعــك الــذي دفعــت بــه مــن أن املــرأة هــي التــي خرجــت فقــال ال بينــة لــدي‬\n     ‫إال اهلل عــز وجــل الــذي يعلــم الســر واخفــى هكــذا قــرر فجــرى ســؤاله‬\n     ‫هــل تقبــل بيمــن املدعيــة علــى اآلتــي أوال علــى أنهــا لــم تخــرج بغيــر إذنــك‬\n     ‫ثانيــا انهــا لــم ترفــض الرجــوع علــى الطــاق اال يف تاريــخ ‪1433/6/16‬ه ـ‬\n\n\n‫‪25‬‬\n\f‫وكان قبــل ذلــك تريــد الرجــوع ثالثــا انهــا كانــت تنــوي بالنفقــة الرجــوع‬\n‫إليــه رابعــا أن املبلــغ الــذي دفعتــه هــو ألــف ريــال فقــال ال أقبــل بيمينهــا‬\n‫بــأي شــيء بخصــوص اســتالمها هكــذا قــرر فجــرى ســؤال املــرأة‬\n‫املدعيــة هــل أنتــي مســتعدة ببــذل اليمــن علــى االمــور األربعــة التــي جــرى‬\n‫ذكرهــا آنفــا أطلــب املهلــة للرجــوع إلــى حســاباتي هكــذا قــررت ثــم‬\n‫رفعــت اجللســة يف الســاعة ‪ 12.00‬وحتــى يــوم االربعــاء ‪1433/8/28‬ه ـ‬\n‫الســاعة ‪ 8.30‬وحــرر يف ‪1433/7/5‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                 ‫محمــد صلــى اهلل عليــه وســلم‪.‬‬\n‫احلمــد هلل وحــده ويف يــوم االربعــاء افتتحــت اجللســة الســاعة ‪ 9.00‬وفيهــا‬\n‫حضــرت املــرأة املدعيــة ‪...‬واملعــرف بهــا والدهــا ‪...‬املدونــة هويتهمــا‬\n‫ســابقا ولــم يحضــر املدعــى عليــه ‪...‬وقــد تبلــغ مبوعــد اجللســة يف اجللســة‬\n‫املاضيــة فعليــه وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n‫الشــرعية فقــد قــررت الســير يف دعــوى املــرأة املدعيــة يف غيــاب املدعــى‬\n‫عيــه فجــرى ســؤال املــرأة املدعيــة هــل أحضــرت اجلــواب الــذي طلبتــي‬\n‫املهلــة مــن اجلــه فقالــت نعــم ثــم قــررت قائلــة أنــه بالرجــوع إلــى حســاباتي‬\n‫وكذلــك الرجــوع إلــى اخوتــي ووالــدي لــم نســتلم مــن املدعــى عليه ســوى‬\n‫مبلــغ ثالثــة آالف ريــال وعنــد إنفاقــي علــى نفســي وعلــى ابنتــي كنــت‬\n‫انــوي الرجــوع علــى املدعــى عليــه ولــم أمنعــه مــن نفســي حتــى تاريــخ‬\n‫‪1433/6/16‬ه ـ وأنــا مســتعده ببــذل اليمــن متــى مــا طلبــت منــي واقصــر‬\n‫دعــواي علــى املطالبــة بنفقتــي حتــى تاريــخ ‪1433/6/16‬ه ـ هكــذا‬\n‫قــررت بحضــرة وشــهادة والدهــا فجــرى ســؤالها هــل أنتــي مســتعده ببــذل‬\n‫اليمــن علــى صحــة دعــواك فقالــت نعــم فجــرى نصحهــا وتخويفهــا بــاهلل‬\n‫عــز وجــل مــن مغبــة هــذه اليمــن إال أنهــا أصــرت فأذنــت لهــا فحلفــت‬\n\n\n                                                                                         ‫‪26‬‬\n\f     ‫قائــا واهلل العظيــم الــذي ال إلــه إال هــو املهلــك املــدرك بــأن املدعــى عليــه‬\n     ‫الغائــب عــن املجلــس الشــرعي ‪ ...‬وبتاريــخ ‪1427/6/30‬ه ـ أحضرنــي‬\n     ‫زوجــي إلــى منــزل أهلــي برضــاه وبإذنــه ومــن ذلــك التاريــخ وحتــى تاريــخ‬\n     ‫‪1433/6/16‬ه ـ لــم أمنعــه مــن نفســي وال مانــع لــدي مــن الرجــوع إليــه‬\n     ‫حتــى تاريــخ ‪1433/6/16‬ه ـ ولــم ينفــق املدعــى عليــه ال علــي وال علــى‬\n     ‫ابنتــه ســوى مبلــغ ثالثــة آالف ريــال وال أعلــم أن والــدي وال أخوتــي قــد‬\n     ‫اســتلموا غيــر هــذا املبلــغ وكنــت أنــوي عنــد اإلنفــاق الرجــوع إليــه واهلل‬\n     ‫العظيــم هكــذا حلفــت فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وبنــاء‬\n     ‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ومبــا ان‬\n     ‫املدعــى عليــه لــم يقــدم عــذرا إليضــاح ســبب غيابــه وملصادقــة املدعــى‬\n     ‫عليــه بــأن زوجتــه مــن ‪1427/6/30‬ه ـ ليســت لديــه وأن ابنتــه مــن والدتهــا‬\n     ‫وحتــى هــذا اليــوم لــم ينفــق عليهمــا ســوى املبلــغ الــذي ذكــر وقــد قــرر‬\n     ‫العلمــاء قاعــده مــن تــرك دعــواه تــرك ومبــا أنــه قــد دفــع بــأن زوجتــه‬\n     ‫قــد خرجــت منزلــه بــدون اذنــه وانهــا امتنعــت مــن الرجــوع إليــه وإلقــراره‬\n     ‫أال بينــة لديــه ســوى اهلل عــز وجــل ومبــا أن املدعــى عليهــا قــد قصــرت‬\n                                                ‫نفقتهــا حتــى تاريــخ ‪1433/6/16‬ه ـ‬\n     ‫وال عــذر ملــن أقــر ولقــرار جلنــة الصلــح واملــدون آنفــا وقــد قــرر العلمــاء‬\n     ‫قاعــده شــرعية العــادة محكمــة واملعــروف عرفــا كاملشــروط شــرطا‬\n     ‫وقــد ذكــر شــيخ اإلســام ابــن تيمــه يف مجمــوع الفتــاوى ‪134/34‬‬\n     ‫مــا نصــه (اذا كان االبــن يف حضانــة أمــه فأنفقــت عليــه تنــوي بذلــك‬\n     ‫الرجــوع علــى األب فلهــا أن ترجــع علــى األب يف أظهــر قولــي العلمــاء وهــو‬\n     ‫مذهــب مالــك وأحمــد يف ظاهــر مذهبــه الــذي عليــه قدمــاء أصحابــه)‬\n     ‫أ‪.‬ه ـ وقــد ذكــر ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه الــكايف ‪97/5‬‬\n\n\n‫‪27‬‬\n\f‫مــا نصــه( واذا وجــد اليمــن املوجــب للنفقــة فلــم ينفــق حتــى مضــت مــدة‬\n‫صــارت النفقــة دينــا يف ذمتــه ســواء تركهــا لعــذر أو غيــره حلديــث عمــر‬\n‫رضــي اهلل عنــه وألنــه مــال يجــب علــى ســبيل البــدل يف عقــد معاوضة فلم‬\n‫يســقط مبضــي الزمــن) وقــد ذكــر إبراهيــم ابــن ضويــان رحمــه تعالــى‬\n‫يف كتابــه منــار الســبيل ‪ 1046/3‬مــا نصــه ( ومــن غــاب عــن زوجتــه مــدة‬\n‫ولــم ينفــق عليهــا لزمتــه نفقــة الزمــن املاضــي) أ‪.‬ه ـ وقــد ذكــر رحمــه‬\n‫تعالــى يف موضــع آخــر صحيفــة ‪ 1052‬مــا نصــه (حيــث امتنــع منهــا الــزوج‬\n‫أو قريــب وأنفــق أجنبــي بنيــة الرجــوع رجــع ألنــه قــام عنــه بواجــب قضــاء‬\n‫دينــه )أ‪.‬ه ـ وكالمــه هــذا يف نفقــة الصغيــر كمــا ذكر ذلــك يف التنقيح‬\n‫املشــبع‪ 286‬وكذلــك إقــرار املــرأة املدعيــة باقتصارهــا علــى النفقــة‬\n‫اخلاصــة بهــا حتــى ‪1433/6/16‬ه ـ وكذلــك لــم تســتلم مــن نفقهــا ونفقــة‬\n‫ابنتهــا ســوى مبلــغ ثالثــة آالف ريــال ومبــا أنهــا قــد بذلــت اليمــن جلميــع‬\n‫ذلــك فقــد ألزمــت باآلتــي أوال بــأن يدفــع املدعــى عليــه ‪...‬نفقــة املدعيــة‬\n‫للســنوات املاضيــة وهــي واحــد وســبعون شــهرا ومجموعهــا مبلــغ خمســة‬\n‫وثالثــن ألفــا وخمســمائة ريــال وبعــد املقاصــاه وخصــم مبلــغ ثالثــة آالف‬\n‫ريــال فيصبــح املبلــغ مبلــغ اثنــن وثالثــن ألفــا وخمســمائة ريــال ثانيــا بــأن‬\n‫يدفــع املدعــى عليــه للمدعيــة نفقــة االبنــة ‪...‬مــن تاريــخ ‪1427/7/27‬ه ـ‬\n‫وحتــى تاريــخ ‪1433/8/25‬ه ـ ومجموعهــا مبلــغ ســتة وثالثــن ألفــا‬\n‫وخمســمائة ريــال ثالثــا فقــد ألزمــت املدعــى عليــه بــأن يدفــع للمدعيــة‬\n‫نفقــة االبنــة ‪ ...‬املســتقبلية وهــي مبلــغ خمســمائة ريــال اعتبــار مــن تاريــخ‬\n‫‪1433/9/25‬ه ـ وبــه حكمــت وبعرضــه عليهــا قنعــت بــه وأفهمتهــا بــأن‬\n‫هــذا احلكــم حكــم حضــوري خاضــع لالســتئناف حســب التعليمــات‬\n            ‫وحــرر يف ‪1433/8/28‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n\n\n                                                                                        ‫‪28‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن ‪1434/2/18‬ه ـ افتتحــت‬\n     ‫اجللســة يف الســاعة الثامنــة والنصــف وقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف مبكــة املكرمــة بالقــرار رقــم ‪ 345811‬يف ‪1434/1/7‬ه ـ‬\n     ‫واملتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم قاضــي اســتئناف ‪...‬ختمــه‬\n     ‫وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه‬\n     ‫وتوقيعــه وقــد تركــت طيلــت هــذه الفتــره لــم يهمــش عليهــا حيــث كان‬\n     ‫لــدي برنامــج يف القضــاء اجلزائــي ملــدة ثمانيــة اســابيع اعتبــار ًا مــن‬\n     ‫تاريــخ ‪1433/12/18‬ه ـ وذلــك مبوجــب خطــاب وكيــل الــوزارة برقــم‬\n     ‫‪ 1923396‬يف ‪1433/11/1‬ه ـ وحــرر يف ‪14334/2/18‬ه ـ وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن‬\n     ‫قضاة الدائرة األولى لألحوال الشــخصية واألوقاف والوصايا والقصار‬\n     ‫وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكــة املكرمة جرى منا‬\n     ‫االطــاع علــى الصــك رقــم ‪ 33396987‬وتاريــخ ‪1433/8/28‬ه ـ الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة العامــة بالطائــف الشــيخ ‪ ...‬املتضمــن‬\n     ‫دعــوى ‪ ...‬ضــد ‪ ...‬يف نفقــة وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪29‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":20,"source_page_end":29,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6959507b8b7c4e4197a99347228edef5ba098112e0185cd9634d88bd1fc1dd2c","normalized_text_hash":"14696530726e7f5b65a173d745a4216e1851558a6cce9e166befe659f3a7f903","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p20-3396987"},{"id":"fc813a86-80a8-5723-a0b3-8c00ececf942","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة مدة محددة -نفقة بنت املاضية و املستقبلية -إدخال والد الزوجة لتقرير نفقته على البنت من عدمه -القول قول الزوجة يف عدم النشوز مع ميينها -ال تقبل شهادة عمودي النسب بعضهم لبعض -من صح إقراره يف شيء قبلت ميينه على إنكاره -احلكم بنفقة املدعية وابنتها املدة املذكورة.","document_number":"3418724","case_number":"33176903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف عقدت اجللسة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"نفقة -نفقة زوجة مدة محددة -نفقة بنت املاضية و املستقبلية -إدخال والد الزوجة لتقرير نفقته على البنت من عدمه -القول قول الزوجة يف عدم النشوز مع ميينها -ال تقبل شهادة عمودي النسب بعضهم لبعض -من صح إقراره يف شيء قبلت ميينه على إنكاره -احلكم بنفقة املدعية وابنتها املدة املذكورة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3418724 :‬‬\n                   ‫َر ْق ُم الدعوى‪33176903 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 3455386‬تاريخه‪1434/3/4 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة مــدة محــددة ‪ -‬نفقــة بنــت املاضيــة و املســتقبلية‬\n‫‪ -‬إدخــال والــد الزوجــة لتقريــر نفقتــه علــى البنــت مــن عدمــه ‪ -‬القــول‬\n‫قــول الزوجــة يف عــدم النشــوز مــع ميينهــا ‪ -‬ال تقبــل شــهادة عمــودي‬\n‫النســب بعضهــم لبعــض ‪ -‬مــن صــح إقــراره يف شــيء قبلــت ميينــه علــى‬\n               ‫إنــكاره ‪ -‬احلكــم بنفقــة املدعيــة وابنتهــا املــدة املذكــورة‪.‬‬\n\n\n\n\n                              ‫‪ -1‬قوله تعالى « لينفق ذو سعة من سعته»‬\n          ‫‪ -2‬قوله تعالى « وعلى املولود له رزقهن وكسوتهن باملعروف»‬\n‫‪ -3‬قــال يف كشــاف القنــاع « وال تقبــل شــهادة عمــودي النســب بعضهــم‬\n                                                          ‫لبعــض» ‪. 313/15‬‬\n‫‪ -4‬قــال يف كشــاف القنــاع ( وإن اختلــف الزوجــان يف نشــوزها بعــد‬\n‫االعتــراف بالتســليم أو اختلفــا يف االتفــاق عليهــا أو يف تســليم النفقــة‬\n        ‫إليهــا فالقــول قولهــا ألن األصــل عــدم ذلــك ) ‪142-141/13‬ه ـ‬\n                    ‫‪ -5‬من صح إقراره يف شيء قبلت ميينه على إنكاره ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــة للمدعــى عليــه ورزق‬\n‫منهــا بأربعــة أوالد واصغرهــم بنت ـ ًا عمرهــا تســعة أعــوام وقــد مت فســخ‬\n\n                                                                                    ‫‪30‬‬\n\f     ‫نــكاح موكلتــه مــن املدعــى عليــه يف ‪1431/6/25‬ه ـ كمــا أن البنــت‬\n     ‫كانــت يف حضانــة والدتهــا واملدعــى وكالــة يطالــب بنفقــة موكلتــه‬\n     ‫مــن تاريــخ ‪1426/8/17‬ه ـ وحتــى تاريــخ فســخ نكاحهــا ونفقــة ابنتــه‬\n     ‫التــي كانــت يف حضانــة والدتهــا مــن ‪ 1426/8/17‬ه ـ وحتــى اســتالمها‬\n     ‫مــن قبــل والدهــا يف ‪1433/4/4‬هــ‪ ،‬أجــاب املدعــى عليــه باملصادقــة‬\n     ‫علــى الدعــوى ودفــع بــأن املدعيــة أصالــة ال تســتحق النفقــة عليهــا ألنهــا‬\n     ‫كانــت ناشــز ًا وكذلــك والدهــا اســتعد بنفقتهــا ونفقــة ابنتهــا ولــذا‬\n     ‫فإنــه غيــر ملــزم بهــذه املطالبــة‪ ،‬حضــر والــد املدعيــة أصالــة وانكــر‬\n     ‫دفــع املدعــى عليــه‪ ،‬قــرر املدعــى عليــه إن بينتــه علــى نشــوز املدعيــة هــم‬\n     ‫أوالده‪ ،‬طلــب املدعــى عليــه ميــن املدعيــة ووالدهــا‪ ،‬حلفــت املدعيــة علــى‬\n     ‫إنهــا لــم تكــن ناشــز ًا وحلــف والدهــا علــى نفــى دفــع املدعــى عليــه‪ ،‬ثــم‬\n     ‫تقــدر نفقــة املدعيــة املاضيــة مبلغــا قــدره أربعمائــة ريــال والبنــت ثالثمائــة‬\n     ‫ريــال مــن قبــل هيئــة النظــر‪ ،‬قــرر ناظــر القضيــة لألســباب املرصــودة‬\n     ‫يف نــص القضيــة ولقولــه تعالــى ((لينفــق ذو ســعه مــن ســعته)) احلكــم‬\n     ‫علــى املدعــى عليــه بتســليم املدعيــة نفقتهــا ونفقــة ابنتهــا مبلغــا قــدره‬\n     ‫ســبعة وأربعــون ألفـ ًا ومائــة وســته وســتون ريــاالً‪ ،‬قــررت املدعيــة ووالدهــا‬\n     ‫القناعــة وقــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة‬\n                                             ‫االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ .....‬القاضــي باحملكمــة العامــة بالطائــف عقــدت اجللســة للنظــر يف‬\n     ‫دعــوى ضــد بطلــب النفقــة املقيــدة برقــم ‪ 33465116‬يف ‪1433/3/12‬هـ‬\n\n‫‪31‬‬\n\f‫واحملالــة لــي مــن فضيلــة الرئيــس برقــم ‪ 33176903‬يف ‪1433/3/12‬ه ـ‬\n‫وفيهــا حضــر ‪ .....‬فلســطيني اجلنســية برخصــة إقامــة رقــم ‪ .....‬بصفتــه‬\n‫ا عــن املدعيــه مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬                 ‫وكي ـ ً‬\n‫الثانيــة بالطائــف رقــم ‪ 11812‬يف ‪1433/2/27‬ه ـ والتــي تخولــه إقامــة‬\n‫وســماع الدعــاوى واملطالبــات املقامــة مــن موكلتــه ضــد املدعــى‬\n‫عليــه واملدافعــة واملرافعــة وحضــور اجللســات وتقــدمي البينــات واالقــرار‬\n‫واالنــكار واملطالبــة بنفقــة ابنتهــا وادعــى علــى احلاضــر معــه املدونــة‬\n‫ا يف دعــواه إن املدعــى عليــه كان زوج ـ ًا ملوكلتــي‬         ‫هويتــه ســابق ًا قائ ـ ً‬\n‫وقــد مت فســخ نكاحهــا بتاريــخ ‪1431/6/25‬ه ـ بعــد أن أجنبــت منــه‬\n‫علــى فــراش الزوجيــة أربعــة أوالد األول وعمرهــا ســتة عشــر عام ـ ًا‬\n‫والثانــي وعمــره أربعــة عشــر عام ـ ًا والثالــث وعمــره أحــد عشــر عام ـ ًا‬\n‫والرابــع وعمرهــا تســعة أعــوام ولــم ينفــق علــى موكلتــي مــن تاريــخ‬\n‫‪1426/8/17‬ه ـ حتــى تاريــخ فســخ النــكاح يف ‪1431/6/25‬ه ـ كما لم‬\n‫ينفــق علــى ابنتهــا مــن تاريــخ ‪1426/8/17‬ه ـ وحتــى تاريــخ اســتالمه لهــا‬\n‫يف تاريــخ ‪1433/4/4‬ه ـ لــذا أطلــب ســؤاله وإلزامــه بدفــع نفقة موكلتي‬\n‫وابنتهــا مــن املدعــى عليــه خــال املــدة املذكــورة بعــد تقديرهــا هــذه‬\n‫دعــواي وبعرضهــا علــى املدعــى عليــه اســتعد باإلجابــة عليهــا يف اجللســة‬\n‫القادمــة ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة كمــا حضــر‬\n‫املدعــى عليــه وبســؤال املدعــى عليــه عــن جوابــه علــى الدعــوى أجــاب‬\n‫ا مــا ذكــره املدعــي وكالــة يف دعــواه مــن الــزواج وفســخ النــكاح‬             ‫قائـ ً‬\n‫واألوالد وأعمارهــم كلــه صحيــح وكذلــك مــا ذكــر مــن عــدم نفقتــي‬\n‫علــى املدعيــة أصالــة وابنتــي خــال املــدة التــي ذكرهــا املدعــي وكالــة‬\n‫صحيــح ولكــن ال جتــب علـ ّـي نفقــة املدعيــة وال نفقــة ابنتنــا ألن املدعيــة‬\n\n\n                                                                                             ‫‪32‬‬\n\f     ‫تعتبــر ناشــز ًا فقــد خرجــت مــن بيتــي طــوال املــدة املذكــورة بــدون علمــي‬\n     ‫ورضــاي وقــد حجــزت البنــت عنــي فلــم اســتطع خــال تلــك املــدة رؤيتهــا‬\n     ‫وزيارتهــا كمــا أن والــد املدعيــة قــد اســتعد بنفقــة املدعيــة وبنفقــة ابنتــي‬\n     ‫وقــد حلــف علــى ذلــك واملدعيــة وابنتنــا كانــت عنــده هكــذا أجــاب‬\n     ‫وبعــرض جوابــه علــى املدعــي وكالــة قــال موكلتــي لــم تكــن ناشــز َا بــل‬\n     ‫املدعــى عليــه هــو الــذي تركهــا ويــدل علــى ذلــك صــك فســخ النــكاح‬\n     ‫وأبــرز صــك ًا صــادر ًا مــن احملكمــة العامــة بجــدة برقــم ‪ 8/200/99‬يف‬\n     ‫‪1430/5/21‬ه ـ وقــال بأنــه صــك فســخ النــكاح وأمــا والــد موكلتــي‬\n     ‫فلــم يســتعد بنفقــة موكلتــي وابنتهــا هكــذا أجــاب لــذا رفعــت اجللســة‬\n     ‫إلدخــال والــد املدعيــة ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n     ‫واملدعــى عليــه كمــا حضــر والــد املدعيــة حامــل رخصــة إقامــة رقــم‬\n     ‫وبســؤال والــد املدعيــة عــن مــا ذكــره املدعــى عليــه يف اجللســة الســابقة‬\n     ‫مــن أنــه اســتعد بنفقــة ابنــة املدعــى عليــه وأنــه حلــف علــى ذلــك واملدعيــة‬\n     ‫وابنتــه كانــت عنــده أجــاب والدهــا بــأن مــا ذكــره املدعــى عليــه غيــر‬\n     ‫صحيــح وإمنــا الصحيــح أنــه حــن جاءتنــي بنتــي ومعهــا طفلتهــا قلــت‬\n     ‫لــه بعدهــا بيومــن يــا إذا طلقــت بنتــي وأرســلت ورقتهــا فأنــا أتكفــل‬\n     ‫بتربيــة البنــت وســأنفق عليهــا ولكنــه لــم يقــم بذلــك ولــم يطلــق ابنتــي‬\n     ‫وإمنــا اضطرنــي لتقــدمي الدعــاوى والذهــاب إلــى املنطقــة الشــرقية وتقــدمي‬\n     ‫دعــوى هنــاك وحصــل بيننــا مرافعــات انتهــت بفســخ نــكاح ابنتــي منــه‬\n     ‫ـف بالشــرط الــذي اشــترطته‬      ‫وحيــث إنــه لــم يقــم بتطليــق ابنتــي ولــم يـ ِ‬\n     ‫عليــه فإنــي لــم أتكفــل بالنفقــة ونطالبــه بنفقــة البنــت املاضيــة ونفقــة‬\n     ‫الزوجــة مــن تاريــخ خروجهــا وحتــى تاريــخ فســخ نكاحهــا وبعــرض‬\n     ‫جوابــه علــى املدعــى عليــه قــال إن والدهــا تكفــل بالنفقــة علــى البنــت‬\n\n\n‫‪33‬‬\n\f‫ولــم يشــترط علــي تطليــق ابنتــه وأمــا نفقــة الزوجــة فقــد كانــت ناشــز ًا‬\n‫وال أوافــق علــى إعطائهــا النفقــة فــكل قولــه غيــر صحيــح فجرى ســؤاله‬\n‫ألــك بينــة علــى أن والــد املــرأة تكفــل بالنفقــة مــن غيــر قيــد وال شــرط‬\n‫فأجــاب ليــس لــدي بينــة علــى ذلــك وأطلــب ميــن والدهــا علــى أنــه اشــترط‬\n‫أن أطلــق ابنتــه وأوصــل لــه ورقــة طالقهــا حتــى ينفــق علــى ابنتــي هكــذا‬\n‫قــال وبعــرض ذلــك علــى والــد املدعيــة اســتعد بــأداء اليمــن يف اجللســة‬\n‫القادمــة فأفهــم بــأن عليــه حضــور اجللســة القادمــة وإحضــار املدعيــة ثــم‬\n‫عقــدت اجللســة وفيهــا حضــرت املدعيــة أصالــة ‪ .....‬فلســطينية اجلنســية‬\n‫مبوجــب رخصــة إقامــة رقــم ‪ .....‬املعــرف بهــا مــن قبــل والدهــا احلاضــر‬\n‫ووكيلهــا كمــا حضــر املدعــى عليــه ويف هــذه اجللســة جــرى ســؤال‬\n‫املدعــى عليــه هــل لديــه بينــة علــى أن املدعيــة أصالــة كانــت ناشــز ًا‬\n‫فقــال شــهادة أوالدي أو ميينهــا فجــرى إفهامــه بــأن شــهادة أوالده ال تقبــل‬\n‫لوجــود املانــع فقــال أريــد ميينهــا علــى أنهــا لــم تكــن ناشــز ًا وميــن والدهــا‬\n‫علــى عــدم اســتعداده بدفــع نفقــة املدعيــة ونفقــة ابنتنــا هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعيــة ووالدهــا اســتعدا بحلــف اليمــن فأذنــت‬\n‫ا واهلل العظيــم أننــي لــم‬ ‫لهمــا بعــد وعظهمــا فحلــف والــد املدعيــة قائ ـ ً‬\n‫ألتــزم للمدعــى عليــه بنفقــة ابنتــي وابنتهــا إال إذا أحضــر ورقــة طالقهــا‬\n‫وأنــه لــم يحضــر ورقــة طالقهــا واهلل العظيــم وحلفــت املدعيــة قائلــة واهلل‬\n‫العظيــم أننــي لــم أنشــز عــن طاعــة زوجــي وأنــه هــو الــذي تركنــي بنفســه‬\n‫واهلل العظيــم هكــذا حلفــا هــذا وقــد جــرى اإلطــاع علــى صــورة الصــك‬\n‫الــذي ســبق وأن أحضرهــا املدعــي وكالــة وأشــير إليــه ســابق ًا فوجــد‬\n‫مضمونهــا دعــوى املدعيــة ضــد املدعــى عليــه بطلــب فســخ نكاحهــا منــه‬\n‫وقــد نظرهــا فضيلــة مصــدره غيابي ـ ًا لعــدم العثــور علــى املدعــى عليــه‬\n\n\n                                                                                            ‫‪34‬‬\n\f     ‫وفســخ نــكاح املدعيــة بنــاء علــى شــهادة شــاهدي املدعيــة بــأن املدعــى‬\n     ‫عليــه غيــر منفــق وجــاء يف شــهادتهما أن املدعــى عليــه تــرك زوجتــه منــذ‬\n     ‫ثــاث ســنوات عنــد أهلهــا أ ‪ .‬ه ـ كمــا ســبق مخاطبــة مكتــب الصلــح‬\n     ‫بهــذه احملكمــة حملاولــة الصلــح أو تقديــر النفقــة فــورد قــرار املكتــب‬\n     ‫رقــم ‪/151‬ص يف ‪1433/4/11‬ه ـ املرفــق مــع املعاملــة وفيــه (وبعــرض‬\n     ‫الصلــح علــى الطرفــن وتقريــب وجهــات النظــر تعــذر الصلــح بينهمــا‬\n     ‫عليــه تــرى اللجنــة بعــد رأي فضيلتكــم أن تكــون النفقــة املاضيــة‬\n     ‫للزوجــة أربعمائــة ريــال وأن تكــون النفقــة املاضيــة للطفلــة ثالثمائــة‬\n     ‫ريــال وبــاهلل التوفيــق) أ‪.‬ه ـ وبعــرض هــذا القــرار علــى الطرفــن لــم تبــدي‬\n     ‫املدعيــة جتاهــه شــيء وأمــا املدعــى عليــه فقــال بــأن هــذا التقديــر عندمــا‬\n     ‫كان راتبــي ثالثــة أالف وأنــا أحتــج عليــه وبســؤال الطرفــن هــل لديهمــا‬\n     ‫إضافــة قالــت املدعيــة ليــس لــدي إضافــة وأمــا املدعــى عليــه فقــال بأنــه‬\n     ‫تقــادم العهــد بالنفقــة والنفقــة إلحيــاء النفــس ووالدهــا ميســور احلــال‬\n     ‫هكــذا أضــاف فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وكالــة بطلــب‬\n     ‫نفقــة املدعيــة مــن تاريــخ ‪1426/8/17‬ه ـ حتــى تاريــخ فســخ النــكاح يف‬\n     ‫‪1431/6/25‬ه ـ ونفقــة ابنتهــا مــن تاريــخ ‪1426/8/17‬ه ـ وحتــى تاريــخ‬\n     ‫‪1433/4/4‬ه ـ ومــا ورد يف إجابــة املدعــى عليــه ومصادقتــه علــى عــدم‬\n     ‫نفقتــه علــى املدعيــة وابنتهمــا خــال تلــك املــدة ودفعــه بــأن املدعيــة‬\n     ‫كانــت ناشــز ًا وأن والدهــا اســتعد بنفقتهــا ونفقــة ابنتهمــا وإلنــكار‬\n     ‫املدعــي وكالــة مــا دفــع بــه املدعــى عليــه وملــا ورد يف إجابــة والــد املدعيــة‬\n     ‫الــذي مت إدخالــه مــن أنــه لــم يلتــزم بالنفقــة إال إذا طلــق املدعــى عليــه‬\n     ‫ابنتــه وأنــه لــم يطلقهــا ويفــي بهــذا الشــرط وإلنــكار املدعــى عليــه وجــود‬\n     ‫هــذا الشــرط وملــا قــرره مــن عــدم وجــود بينــة لديــه علــى اســتعداد والــد‬\n\n\n‫‪35‬‬\n\f‫املدعيــة بالنفقــة وعلــى نشــوز املدعيــة إال شــهادة أوالده علــى النشــوز‬\n‫وشــهادة الولــد لوالــده ال تقبــل لوجــود مانــع وهــو قرابــة الــوالدة قــال يف‬\n‫الكشــاف ((وال تقبــل شــهادة عمــودي النســب بعضهــم لبعــض)) أ ‪ .‬ه ـ‬\n‫‪313/15‬ولطلــب املدعــى عليــه ميــن املدعيــة ووالدهــا علــى نفــي مــا دفــع‬\n‫بــه وحللفهمــا علــى نفــي ذلــك بعــد اإلذن لهمــا وألن القــول قــول املــرأة يف‬\n‫عدم نشــوزها قال يف الكشــاف (( وإن اختلفا أي الزوجان يف نشــوزها‬\n‫بعــد االعتــراف بالتســليم أو اختلفــا يف اإلنفــاق عليهــا أو يف تســليم النفقة‬\n‫إليهــا فالقــول قولهــا ألن األصــل عــدم ذلــك)) أ ‪ .‬ه ـ ‪ 142-141/13‬وألن‬\n‫ميــن والــد املدعيــة وإن لــم يكــن مدعــى عليــه مقبولــة ألن مــن صــح‬\n‫إقــراره يف شــيء قبلــت ميينــه علــى إنــكاره وملــا ورد يف قــرار مكتــب‬\n‫الصلــح مــن تقديــر نفقــة املدعيــة بأربعمائــة ريــال وابنتهمــا بثالثمائــة‬\n‫ريــال شــهري ًا وألن كامــل املــدة التــي لــم ينفــق فيهــا علــى املدعيــة هــي‬\n‫ســبعة وخمســون شــهر ًا وثالثــة وعشــرون يومـ ًا وإجمالــي نفقــة هــذه املــدة‬\n‫حســب التقديــر املشــار إليــه ثالثــة وعشــرون ألفـ ًا وثالثمائة وســتة رياالت‬\n‫وكامــل املــدة التــي لــم ينفــق فيهــا علــى ابنتهمــا هــي تســعة وســبعون‬\n‫شــهر ًا وســبعة عشــر يومـ ًا وإجمالــي نفقــة هــذه املــدة حســب التقديــر هــو‬\n‫ثالثــة وعشــرون ألــف ومائــة وثالثــون ريــا ًال لذلــك كلــه ولقولــه ســبحانه‬\n‫وتعالــى (لينفــق ذو ســعة مــن ســعته) وقولــه ســبحانه (وعلــى املولــود لــه‬\n‫رزقهــن وكســوتهن باملعــروف) فقــد حكمــت علــى املدعــى عليــه بدفــع‬\n‫ســبعة وأربعــن ألف ـ ًا ومائــة وســتة وســتني ريــا ًال للمدعيــة أصالــة نفقتهــا‬\n‫وابنتهــا للمــدة املذكــورة بعاليــه وبإعــان احلكــم علــى الطرفــن قــررت‬\n‫املدعيــة ووالدهــا القناعــة وأمــا املدعــى عليــه فقــرر عدمهــا فجــرى‬\n‫إفهامــه باالنتظــار بعــد إغــاق اجللســة الســتالم نســخة مــن صــك احلكــم‬\n\n\n                                                                                       ‫‪36‬‬\n\f     ‫وتقــدمي مــا لديــه خــال ثالثــن يوم ـ ًا مــن تاريــخ اليــوم وبــاهلل التوفيــق‬\n     ‫حــرر يف ‪1434/1/20‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه أجمعــن ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي الســاعة لعاشــرة مــن هــذا اليــوم االثنــن‬\n     ‫املوافــق ‪1434/3/23‬ه ـ عقــدت اجللســة وقــد عــادت املعاملــة مــن‬\n     ‫محكمــة االســتئناف بخطــاب فضيلــة رئيســها رقــم ‪ 34486688‬يف‬\n     ‫‪1434/3/14‬ه ـ وقــد ظهــر صــك احلكــم بقــرار الدائــرة الثانيــة لألحوال‬\n     ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة رقــم ‪ 3455386‬يف ‪1434/3/4‬ه ـ‬\n     ‫ونصــه (( احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n     ‫‪ 3418724‬يف ‪1434/1/20‬ه ـ الصــادر مــن فضيلــة الشــيخ وأصدرنــا‬\n     ‫القــرار رقــم ‪ 3455386‬وتاريــخ ‪1434/3/4‬ه ـ املتضمــن املوافقــة علــى‬\n     ‫احلكــم واهلل املوفــق)) أ‪.‬ه ـ قاضــي اســتئناف ختمــه وتوقيعــه قاضــي‬\n     ‫اســتئناف د‪ .....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه لــذا‬\n     ‫جــرى إحلاقــه وبــاهلل التوفيــق حــرر يف ‪1434/3/23‬ه ـ وصلــى اهلل وســلم‬\n                               ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n     ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n     ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n     ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة‬\n     ‫املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي‬\n     ‫باحملكمــة العامــة بالطائــف برقــم ‪ 3418724‬وتاريــخ ‪1434/01/20‬ه ـ‬\n     ‫املتضمــن دعــوى‪ .....‬ضــد‪ .....‬يف نفقــة وبدراســة الصــك وصــورة ضبطــه‬\n     ‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                           ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n‫‪37‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":30,"source_page_end":37,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"666b9f3e39bfa585453cf800ed77f545c7fb3d65d5d3c73efba5f46109eb06c2","normalized_text_hash":"08448a791abda952bb26761c14b10fc02f6f63190a1db65067a77a6fb3833721","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p30-3418724"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
